def _run_st12f_replay_paper_evidence_fixture_preflight_v1() -> tuple[tuple[str, str], ...]:
    lock = _valid_lock()
    replay = _lane()
    divergence = _divergence()
    bundle = _bundle()
    review = _review()
    first_section = bundle.calibration_and_probability_quality
    duplicate_rows = list(first_section.identity_dispositions)
    duplicate_rows[1] = replace(duplicate_rows[1], evidence_identity=duplicate_rows[0].evidence_identity)
    cases = (
        ("ST12-TEST::122", lambda: replace(lock, cohort_template_ids=(lock.cohort_template_ids[1], lock.cohort_template_ids[0], *lock.cohort_template_ids[2:])), ReasonCode.ST12F_TEMPLATE_ROSTER_MISMATCH, "LOCK_TEMPLATE_ORDER"),
        ("ST12-TEST::126", lambda: replace(replay, expected_result_contract_id="ST12F-PAPER-CONTRACT::MATH-01"), ReasonCode.ST12F_LANE_SUBSTITUTION_FORBIDDEN, "LANE_IDENTITY"),
        ("ST12-TEST::132", lambda: _bundle(calibration_and_probability_quality=EvidenceSectionV1(first_section.section_id, tuple(duplicate_rows))), ReasonCode.ST12F_EVIDENCE_IDENTITY_INVALID, "EVIDENCE_IDENTITY_UNION"),
        ("ST12-TEST::133", lambda: replace(divergence, latency_delta=None), ReasonCode.ST12F_EVIDENCE_INCOMPLETE, "DIVERGENCE_INCOMPARABLE"),
        ("ST12-TEST::136", lambda: replace(first_section.identity_dispositions[0], evidence_record_refs=()), ReasonCode.ST12F_EVIDENCE_INCOMPLETE, "EVIDENCE_RECEIPT"),
        ("ST12-TEST::137", lambda: replace(replay, completed_at=replay.started_at - timedelta(seconds=1)), ReasonCode.POINT_IN_TIME_FRESHNESS_OR_SEQUENCE_INVALID, "LANE_TIME_SEQUENCE"),
        ("ST12-TEST::138", lambda: replace(review, reviewer_identity=review.bundle_producer_identity), ReasonCode.ST12F_SELF_REVIEW_FORBIDDEN, "INDEPENDENT_REVIEW_SEGREGATION"),
        ("ST12-TEST::139", lambda: replace(replay, fixture_only_not_evidence=1), ReasonCode.CONTRACT_OR_TYPE_INVALID, "FIXTURE_EVIDENCE_BOUNDARY"),
    )
    results: list[tuple[str, str]] = []
    for case_id, mutate, reason, stage in cases:
        # Exact seam baselines have already constructed successfully; only the
        # declared field/roster mutation is applied below.
        try:
            mutate()
        except ContractValidationError as exc:
            assert exc.reason_code is reason
        else:
            raise AssertionError(f"{case_id} did not reach {stage}")
        results.append((case_id, stage))
    assert tuple(case_id for case_id, _ in results) == _SEMANTIC_IDS
    return tuple(results)


def _lp03_wait_until_native_clock_v1(clock, target_ns):
    """Wait for a sampled wall or monotonic timestamp used by a timing fixture."""
    from time import sleep

    while (observed_ns := clock()) < target_ns:
        sleep((target_ns - observed_ns) / 1_000_000_000)
    return observed_ns


def _lp03_cold_fixture_keys_v1():
    """Both test processes derive the same public, synthetic-only key cohort."""
    from hashlib import sha256
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    roles = ("owner","issuer","producer","svc_supervisor","reviewer","readiness","pretrade","agent_receiver","svc_receiver")
    return {role:Ed25519PrivateKey.from_private_bytes(sha256(("LP03 TEST-ONLY RESTART FIXTURE:"+role).encode()).digest())
        for role in roles}


def _lp03_retain_cold_writer_fixture_v1(tmp_path, state, fixture_keys):
    """Keep the last live native holder in the writer until the parent probes."""
    import sys
    from os import getpid, getppid

    from src.qtt.agents.pr169_agent_orch1_resolvers import EvidenceHostBindingV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.latency_policy import _EvidenceLocalClockV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.sqlite_reference import SQLiteReferenceAdapterV1

    config = state.host.public_configuration
    candidate = next(store for store in config.store_bindings if store.role is m.EvidenceStoreRoleV1.CONTROL)
    original = state.control_store
    second_host = EvidenceHostBindingV1.for_software_conformance_v1(config,role_signing_key=fixture_keys["issuer"])
    second = SQLiteReferenceAdapterV1.open_evidence_store_v1(host_binding=second_host,store_binding=candidate,
        owned_role_root=Path(original.database_path).parent,busy_timeout_ms=0,max_transaction_attempts=1)
    try:
        first = state.lifecycle_first_operation
        process_identity = _EvidenceLocalClockV1().process_identity_ref
        assert process_identity == first.grant_record.deadline_clock_and_process.process_identity_ref
        control_relative = Path(original.database_path).relative_to(tmp_path).as_posix()
        launch = dict(public_configuration=config,original_envelope=state.owner_envelopes[0][1],
            control_path=control_relative, old_process_identity=process_identity,
            native_runtime_pid=getpid(), native_runtime_parent_pid=getppid(),
            exact_first_grant=first.grant_record.record_id)
        original.close()
        work=tmp_path/"cold-native-transfer.tmp"
        with work.open("xb") as handle:handle.write(deterministic_json(launch).encode("utf-8"))
        work.rename(tmp_path/"cold-native-transfer.json")
        assert sys.stdin.buffer.readline(16)==b"release\n"
    finally:
        second.close()


def _assert_lp03_cold_native_archive_v1(tmp_path, case):
    """Verify reopening the exact files in a different native Python process."""
    from hashlib import sha256
    from pathlib import Path
    import subprocess
    import sys
    from time import monotonic, monotonic_ns, time_ns

    import pytest
    from src.qtt.agents.pr169_agent_orch1_resolvers import AgentOrchService,EvidenceHostBindingV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError,ReasonCode
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.latency_policy import _EvidenceLocalClockV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import (
        _evidence_canonical_object_v1, deterministic_json, validate_relative_path,
    )
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.sqlite_reference import SQLiteReferenceAdapterV1

    tmp_path.mkdir()
    script = ("from pathlib import Path; from "
        "tests.stage1_prediction_markets.qku_computation_control_plane.tranche_f.test_replay_paper_evidence_matrix "
        "import _assert_lp03_authorization_data_contract as run; import sys; "
        "run(Path(sys.argv[1]), selected_math='MATH-35', cold_native_writer=sys.argv[2])")
    archive_keys=_lp03_cold_fixture_keys_v1()
    transfer=tmp_path/"cold-native-transfer.json"
    stdout_path,stderr_path=tmp_path/"native-writer.stdout.bin",tmp_path/"native-writer.stderr.bin"
    writer = None
    forced_launcher_stop = False
    try:
        with stdout_path.open("xb") as stdout, stderr_path.open("xb") as stderr:
            with subprocess.Popen((sys.executable,"-B","-c",script,str(tmp_path),case),stdin=subprocess.PIPE,
                    stdout=stdout,stderr=stderr) as writer:
                try:
                    until=monotonic()+120
                    while not transfer.is_file() and writer.poll() is None and monotonic()<until:
                        _lp03_wait_until_native_clock_v1(monotonic_ns, monotonic_ns() + 25_000_000)
                    assert transfer.is_file() and writer.poll() is None, (writer.poll(),stderr_path.read_bytes()[-16000:])
                    transfer_raw=transfer.read_bytes()
                    received=_evidence_canonical_object_v1(transfer_raw,max_bytes=131072)
                    config=m.EvidenceHostPublicConfigurationV1.from_canonical_mapping(received["public_configuration"])
                    old=m.EvidenceSignedMessageV1.from_canonical_mapping(received["original_envelope"])
                    old_message=m.EvidenceAuthorizationMessageV1.from_canonical_mapping(
                        _evidence_canonical_object_v1(old.canonical_message.encode("utf-8")))
                    old_envelope=m.OwnerEvidenceEnvelopeV1.from_canonical_mapping(json.loads(deterministic_json(old_message.payload)))
                    process_kind, process_fields = received["old_process_identity"].split("::")
                    observed_grant_pid, _, _ = process_fields.split(":")
                    runtime_pid = received["native_runtime_pid"]
                    runtime_parent_pid = received["native_runtime_parent_pid"]
                    assert type(runtime_pid) is int and type(runtime_parent_pid) is int
                    assert runtime_pid > 0 and runtime_parent_pid > 0
                    assert process_kind == "LP03-PROCESS" and observed_grant_pid == str(runtime_pid)
                    # A Windows virtual-environment launcher can be the native runtime parent.
                    assert writer.pid in (runtime_pid, runtime_parent_pid)
                    print("LP03_COLD_NATIVE_WRITER_PROCESS_JOIN=" + deterministic_json(dict(
                        case=case, native_launch_pid=writer.pid, native_runtime_pid=runtime_pid,
                        native_runtime_parent_pid=runtime_parent_pid,
                        original_process_identity=received["old_process_identity"],
                        exact_public_transfer_sha256=sha256(transfer_raw).hexdigest())))
                    control_path = tmp_path / validate_relative_path(received["control_path"])
                    assert control_path.name == "control.sqlite3"
                    control_binding = next(item for item in config.store_bindings if item.role is m.EvidenceStoreRoleV1.CONTROL)
                    original_binding = next(
                        item for item in old_envelope.store_bindings if item.role is m.EvidenceStoreRoleV1.CONTROL
                    )
                    assert control_binding == original_binding
                    root_stat, file_stat = control_path.parent.stat(), control_path.stat()
                    assert (root_stat.st_dev, root_stat.st_ino) == original_binding.resolved_root_identity
                    assert (file_stat.st_dev, file_stat.st_ino) == original_binding.database_file_identity
                    generation=config.generation+1
                    config=replace(config,generation=generation)
                    host=EvidenceHostBindingV1.for_software_conformance_v1(config,role_signing_key=archive_keys["issuer"])
                    with pytest.raises(ComputationControlPlaneError,match="LP03_CONTROL_NATIVE_LOCK_UNAVAILABLE:33") as contention:
                        SQLiteReferenceAdapterV1.open_evidence_store_v1(host_binding=host,store_binding=control_binding,
                            owned_role_root=control_path.parent,busy_timeout_ms=0,max_transaction_attempts=1)
                    assert contention.value.reason_code is ReasonCode.EVIDENCE_RUN_UNRESOLVED
                    writer.stdin.write(b"release\n")
                    writer.stdin.flush()
                    assert writer.wait(timeout=20)==0, stderr_path.read_bytes()[-16000:]
                finally:
                    if writer.poll() is None:
                        # Closing the owned pipe lets the original runtime unwind before its launcher exits.
                        writer.stdin.close()
                        try:
                            writer.wait(timeout=20)
                        except subprocess.TimeoutExpired:
                            forced_launcher_stop = True
                            writer.terminate()
                            writer.wait(timeout=20)
    finally:
        from base64 import b64encode

        writer_streams = {}
        stream_observations = {}
        segment_bytes = 24_576
        for stream_name, path in (("STDOUT", stdout_path), ("STDERR", stderr_path)):
            raw = path.read_bytes() if path.is_file() else None
            writer_streams[stream_name] = raw
            stream_observations[stream_name] = (
                None if raw is None else dict(bytes=len(raw), sha256=sha256(raw).hexdigest())
            )
            for ordinal, offset in enumerate(range(0, len(raw or b""), segment_bytes)):
                segment = raw[offset:offset + segment_bytes]
                print("LP03_COLD_NATIVE_WRITER_STREAM_SEGMENT=" + deterministic_json(dict(
                    case=case, stream=stream_name, ordinal=ordinal, offset=offset,
                    byte_count=len(segment), data_base64=b64encode(segment).decode("ascii"))))
        print("LP03_COLD_NATIVE_WRITER_TERMINAL_STREAMS=" + deterministic_json(dict(
            case=case, original_writer_pid=None if writer is None else writer.pid,
            native_exit=None if writer is None else writer.poll(),
            forced_launcher_stop=forced_launcher_stop, streams=stream_observations)))
    writer_raw = writer_streams["STDOUT"]
    assert writer_raw and writer_streams["STDERR"] == b""
    assert _EvidenceLocalClockV1().process_identity_ref != received["old_process_identity"]
    now=time_ns()
    expiry=old_message.exclusive_expiry_wall_ns
    assert now<expiry
    plan=replace(old_envelope.assembly_scope.scenario_plan_body_or_existing_ref.plan,generation=generation)
    scope=replace(old_envelope.assembly_scope,generation=generation,scope_ref="LP03-SCOPE::cold-current",
        scenario_plan_body_or_existing_ref=m.EvidenceInlinePlanV1(plan))
    envelope=replace(old_envelope,envelope_ref="LP03-ENVELOPE::cold-current",assembly_scope=scope)
    message=replace(old_message,subject=envelope.envelope_ref,generation=generation,nonce="fc"*32,valid_from_wall_ns=now,
        payload=json.loads(deterministic_json(envelope)))
    wire=deterministic_json(message)
    current=m.EvidenceSignedMessageV1(wire,archive_keys["owner"].sign(b"QTT-LP03-EVIDENCE-AUTH-V1\0"+wire.encode("utf-8")).hex())
    adapters=[]
    try:
        control=SQLiteReferenceAdapterV1.open_evidence_store_v1(host_binding=host,store_binding=control_binding,
            owned_role_root=control_path.parent,busy_timeout_ms=0,max_transaction_attempts=1)
        adapters.append(control)
        role_stores=[]
        roles = ((m.EvidenceStoreRoleV1.REPLAY,"QKU_COMPUTATION_CONTROL_PLANE","producer"),
            (m.EvidenceStoreRoleV1.PAPER,"QKU_COMPUTATION_CONTROL_PLANE","producer"),
            (m.EvidenceStoreRoleV1.REVIEW,"INDEPENDENT_EVIDENCE_REVIEW","reviewer"))
        for role,owner,key in roles:
            binding=next(row for row in config.store_bindings if row.role is role)
            role_host=EvidenceHostBindingV1.for_software_conformance_v1(replace(config,service_owner=owner,
                service_principal=binding.allowed_writer_principal,signing_key_id="LP03-KEY::"+key),role_signing_key=archive_keys[key])
            adapter=SQLiteReferenceAdapterV1.open_evidence_store_v1(host_binding=role_host,store_binding=binding,
                owned_role_root=tmp_path/role.value.lower(),busy_timeout_ms=0,max_transaction_attempts=1)
            adapters.append(adapter)
            role_stores.append((adapter,role_host))
        issuer=AgentOrchService()
        context=issuer.bind_evidence_authority_v1(host,control_store=control,original_owner_envelopes=(current,),
            original_historical_owner_envelopes=(old,),original_cold_role_stores=tuple(role_stores))
        report=issuer.recover_cold_evidence_control_v1(envelope.envelope_ref,
            historical_owner_envelope_ref=old_envelope.envelope_ref,issuer_context=context)
        assert report["disposition"]=="ORIGINAL_CONTROL_ROSTER_OBSERVED"
        assert report["original_assembly_grant_ref"]==received["exact_first_grant"]
        assert report["revocation"].target_generation==0 and report["revocation"].new_generation==1
        observed=report["current_publication_readbacks"]
        if case=="complete":
            from src.qtt.stage1_prediction_markets.qku_computation_control_plane.receipts import _lp03_spine_from_storage_v1

            revocation_ref = report["revocation"].record_id
            row = control._connection.execute("SELECT payload_json FROM receipt_records WHERE record_id=?",
                                              (revocation_ref,)).fetchone()
            original_revocation = _lp03_spine_from_storage_v1(row[0].encode("utf-8"), expected_record_id=revocation_ref)
            assert original_revocation.typed_payload.record == report["revocation"]
            reference = InMemoryPersistenceAdapterV1()
            transaction = reference.begin_transaction()
            try:
                with pytest.raises(ComputationControlPlaneError, match="LP03_CONTROL_REQUIRES_ORIGINAL_ROLE_STORE") as denied:
                    reference.insert_receipt_record(transaction, original_revocation)
                assert denied.value.reason_code is ReasonCode.PERSISTENCE_UNAVAILABLE
                transaction.commit()
            finally:
                if transaction.is_active:
                    transaction.rollback()
            assert reference.get_record(revocation_ref) is None
            print("LP03_COLD_REFERENCE_INSERT_DENIAL=" + deterministic_json(dict(
                original_revocation_ref=revocation_ref, reason=denied.value.reason_code.value, present=False)))
            assert report["original_lanes"]==(("REPLAY","ORIGINAL_CONTROL_COLLECTED"),("PAPER","ORIGINAL_CONTROL_COLLECTED"))
            assert tuple(row["disposition"] for row in observed)==("CURRENT_ORIGINAL_PUBLICATION_READBACK",)*2
            assert all(len(row["original_parent_bytes"])>=11 for row in observed)
            assert len(report["original_conformance_roster"])==3
            proof=report["original_signed_review_readback"]
            assert proof["original_signed_review_ref"]==report["original_conformance_roster"][0]+"::REVIEW:1"
            assert proof["original_review_decision"]=="PASS_SOFTWARE_CONFORMANCE"
        else:
            assert report["original_lanes"]==(("REPLAY","ORIGINAL_NATIVE_TERMINAL_FINALIZATION_UNPROVEN"),
                ("PAPER","ORIGINAL_ATTEMPT_UNAVAILABLE"))
            assert report["original_conformance_roster"]==() and report["original_signed_review_readback"] is None
            row,=observed
            assert row["lane"]=="REPLAY"
            prefix=b"LP03_COLD_NATIVE_ORIGINAL_CUT="
            original_cut,=tuple(json.loads(line[len(prefix):]) for line in writer_raw.splitlines() if line.startswith(prefix))
            assert original_cut["case"]==case
            pointer=m.EvidencePublicationRefV1.from_canonical_mapping(original_cut["original_inert_publication_pointer"])
            if case=="before_data":
                assert row["original_pointer"] is None and row["original_parent_bytes"]==()
            else:
                assert pointer==row["original_pointer"]
                assert len(row["original_parent_bytes"])==(1 if case=="data_only" else 11)
            assert row["disposition"]==("CURRENT_PUBLICATION_READBACK_FINALIZATION_UNPROVEN"
                if case=="publication_pending_readback" else "EVIDENCE_PUBLICATION_UNPROVEN")
        chronological=(report["revocation_commit_observation"],report["revocation_readback_observation"],report["archive_observation"],
            report["durable_archive_commit"],report["durable_archive_readback"],report["final_archive_observation"])
        assert all(tuple(sorted(values))==values for values in zip(*chronological,strict=True))
        archived = report["durable_archive_result"]
        durable_payload = {key:value for key,value in report.items() if key not in ("durable_archive_result",
            "durable_archive_commit", "durable_archive_readback", "final_archive_observation", "final_archive_consumed")}
        assert report["final_archive_consumed"].control_writes > report["selected_consumed"].control_writes
        assert report["final_archive_consumed"].record_reads > report["selected_consumed"].record_reads
        durable_wire=deterministic_json(durable_payload).encode("utf-8")
        assert archived==dict(record_ref=report["revocation"].record_id+"::ARCHIVE:1",bytes=len(durable_wire),
            sha256=sha256(durable_wire).hexdigest())
        state=context._state_for_owner_v1(issuer)
        assert state.lifecycle_original is None and state.lifecycle_unresolved and not state.preparations and not state.registrations
        assert state.supervisor is None
        with pytest.raises(ComputationControlPlaneError,match="LP03_COLD_CONTROL_ARCHIVE_ALREADY_RESERVED") as duplicate:
            issuer.recover_cold_evidence_control_v1(envelope.envelope_ref,
                historical_owner_envelope_ref=old_envelope.envelope_ref,issuer_context=context)
        assert duplicate.value.reason_code is ReasonCode.EVIDENCE_RUN_UNRESOLVED
        print("LP03_COLD_NATIVE_ARCHIVE="+deterministic_json(dict(case=case,original_writer_pid=writer.pid,
            current_reader_process=_EvidenceLocalClockV1().process_identity_ref,original_live_holder_denied=str(contention.value),
            original_writer_stdout_bytes=len(writer_raw),original_writer_stdout_sha256=sha256(writer_raw).hexdigest(),
            exact_public_transfer_sha256=sha256(transfer_raw).hexdigest(),report=report,duplicate=str(duplicate.value))))
    finally:
        for adapter in reversed(adapters):adapter.close()


