def _assert_lp03_spa_registration(issuer, issuer_context, state, preparation, request, protocol, store, *, cut):
    import sys
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import implementation_registry as formulas
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.persistence import _EvidenceRegistrationOperationV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.receipts import _lp03_spine_from_storage_v1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json
    math_id = preparation.envelope_entry[3].component_closure[0]
    reasons = dict(zero_budget="LP03_NUMERICAL_ZERO_BUDGET", wrong_bounds="LP03_SPA_DECLARED_BINARY64_ENCLOSURE",
        expectation_outside="LP03_SPA_EXPECTATION_MEMBER_BOUNDS", serialization="LP03_SPA_EXPECTATION_BYTES")
    formula_codes = (formulas.compute_math_16_hansen_spa.__code__, formulas._v34_spa_long_run_variance.__code__,)
    calls, previous, result, error = [], sys.getprofile(), None, None
    claim_bound_denials = []
    def observe(frame, event, arg):
        if event == "call" and frame.f_code in formula_codes:
            calls.append(frame.f_code.co_name)
    try:
        sys.setprofile(observe)
        if cut is None:
            result = issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
        else:
            assert cut in reasons
            with pytest.raises(ComputationControlPlaneError, match=reasons[cut]) as caught:
                issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
            error = str(caught.value)
    finally:
        sys.setprofile(previous)
    registration = state.registrations[preparation.grant_record.record_id]
    work = registration.numerical_work
    original = registration.numerical_original
    assert calls == [] and registration.attempts == {} and state.supervisor is None
    assert state.operation is None and not store._connection.in_transaction
    assert registration.accounting_observation_state == "OBSERVED" and registration.parent_readback_observation is not None
    assert original is preparation.registration_numerical_original and original[2] is work
    assert work._math26_context_steps == [] and work._math26_context_prefix == ()
    assert all(entry[3] == "STATISTICAL_EXACT_DECIMAL_V1" for entry in work._decimal_admissions)
    assert all(work.consumed[key] == 0 for key in ("log_series_terms", "square_roots", "random_draws"))
    if cut is None:
        assert registration.commit_state == "COMMITTED_AND_READBACK" and registration.handle is result
        assert len(registration.readback_refs) == len(registration.readback_rows) == 10
        assert registration.commit_observation[0] <= registration.readback_observation[0]
        assert _EvidenceRegistrationOperationV1._assert_numerical_original_v1(registration) is original
        assert registration.resolved_policy_original[5] is original
        assert math_id == "MATH-16" and work.consumed["decimal_parse_attempts"] == work.consumed["retained_decimal_inputs"] == 2
        proof = original[8]
        assert proof["profile"] == "DECLARED_NORMALIZED_SPA_BINARY64_COORDINATE_ENCLOSURE_V1" and proof["math_id"] == "MATH-16"
        assert proof["observations"] == 3 and proof["candidates"] == 1 and proof["replicates"] == 1 and proof["seed"] == 0
        assert proof["block_bits"] == "4000000000000000" and proof["alpha_bits"] == "3fe0000000000000"
        assert proof["fixed_lower"] == dict(numerator='-3599131035634557106248430806148785487095757694641533306480604458089470064537190296255232548883112685719936728506816716098566612844395439751206812144692131084107776', denominator="1") and proof["fixed_upper"] == dict(numerator='3599131035634557106248430806148785487095757694641533306480604458089470064537190296255232548883112685719936728506816716098566612844395439751206812144692131084107776', denominator="1")
        assert proof["bound_scope"] == "ALL_NUMERIC_RECORD_COORDINATES_WITH_MEMBER_DOMAINS" and proof["result_direction"] == "RECORD"
        assert proof["statistical_authority"] == "NO_EMPIRICAL_FAMILY_OR_SIGNIFICANCE_CERTIFICATION"
        assert protocol.formula_seed_bindings == preparation.plan.formula_seed_bindings == (("MATH-16", 0),)
        assert work._bootstrap_invocations == [] and 0 < work.consumed["serialized_bytes"] < protocol.numerical_work_limits["max_serialized_bytes"]
        for record in registration.records:
            body = store._connection.execute("SELECT payload_json FROM receipt_records WHERE record_id=?", (record.record_id,)).fetchone()[0]
            assert _lp03_spine_from_storage_v1(body.encode("utf-8"), expected_record_id=record.record_id).typed_payload.record == record
        before = dict(work.consumed)
        assert issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context) is result
        assert registration.numerical_original is original and dict(work.consumed) == before
        from dataclasses import replace
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import EvidenceClaimRecordV1
        claim = next(record for record in registration.records if type(record) is EvidenceClaimRecordV1)
        assert replace(claim) == claim and claim.fixed_upper == proof["fixed_upper"]["numerator"]
        assert claim.fixed_lower == proof["fixed_lower"]["numerator"]
        for name, changes in (
            ("leading_plus", dict(fixed_upper="+" + claim.fixed_upper)),
            ("leading_zero", dict(fixed_upper="0" + claim.fixed_upper)),
            ("exponent_spelling", dict(fixed_upper=claim.fixed_upper + "E+0")),
            ("changed_upper", dict(fixed_upper=claim.fixed_upper[:-1] + "7")),
            ("changed_lower", dict(fixed_lower=claim.fixed_lower[:-1] + "5")),
            ("reversed_pair", dict(fixed_lower=claim.fixed_upper, fixed_upper=claim.fixed_lower)),
            ("positive_lower", dict(fixed_lower=claim.fixed_upper)),
            ("foreign_metric_long_pair", dict(metric_id="CONFORMANCE::MATH-15::reality_check_receipt")),
            ("float_endpoint", dict(fixed_upper=1.0)),
            ("oversized_endpoint", dict(fixed_upper="9" * 4097)),
        ):
            with pytest.raises(ComputationControlPlaneError) as caught:replace(claim, **changes)
            claim_bound_denials.append(dict(case=name, diagnostic=str(caught.value)))
        assert dict(work.consumed) == before and registration.numerical_original is original
    else:
        assert registration.handle is None and registration.records == () and result is None
        assert registration.commit_state == "REGISTRATION_FAILED_REQUIRES_AUDIT"
        assert registration.commit_observation is registration.readback_observation is None
        assert work.state == "FAILED" and work.failure == reasons[cut]
        before = dict(registration.consumed)
        with pytest.raises(ComputationControlPlaneError, match="LP03_REGISTRATION_ALREADY_RESERVED_OR_UNRESOLVED"):
            issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
        assert registration.numerical_original is original and dict(registration.consumed) == before
    stored = {table: store._connection.execute("SELECT * FROM " + table + " ORDER BY 1").fetchall()
        for table in ("receipt_records", "idempotency_claims")}
    print("LP03_SPA_REGISTRATION_QUALIFICATION=" + deterministic_json(dict(math_id=math_id, case=cut or "original_registered_bounds",
        scope="ORIGINAL_COMPLETE_SYNTHETIC_FAMILY_AND_SPA_POLICY_PREREGISTRATION_ONLY", original_envelope=preparation.envelope_entry[3],
        original_snapshot=preparation.input_assembly_members[3], source_slices=preparation.input_assembly_members[1],
        original_protocol_body=original[10][1], policy_slices=registration.policy_slices,
        phase=registration.commit_state, numerical_phase=original[1], actual_error=error,
        numerical_consumed=dict(work.consumed), admitted_texts=[entry[2] for entry in work._decimal_admissions],
        bound_proof=original[8], parent_readback_observation=registration.parent_readback_observation,
        commit_observation=registration.commit_observation, readback_observation=registration.readback_observation,
        registration_records=registration.records, registration_rows=registration.readback_rows, stored_rows=stored,
        physical_consumption=dict(registration.consumed), formula_calls=calls, claim_bound_denials=claim_bound_denials)))
    return registration


