    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json
    assert cut is None and preparation.envelope_entry[3].component_closure==("MATH-01","MATH-02")
    math_id="MATH-02"
    reasons = dict(zero_budget="LP03_NUMERICAL_ZERO_BUDGET", wrong_bounds="LP03_MARKET_ADMISSION_DECLARED_ENCLOSURE",
                   expectation_outside="LP03_MARKET_ADMISSION_EXPECTATION_OUT_OF_BOUNDS")
    formula_codes = tuple(getattr(formulas, name).__code__ for name in ("compute_math_01_v34", "compute_math_02_v34"))
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.unit_conversion import UnitConversionOwnerV1
    formula_codes=(*formula_codes,UnitConversionOwnerV1.convert.__code__)
    calls, previous, result, error = [], sys.getprofile(), None, None
    def observe(frame, event, arg):
        if event == "call" and frame.f_code in formula_codes:
            calls.append(frame.f_code.co_name)
    try:
        sys.setprofile(observe)
        if cut is None:
            result = issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
        else:
            assert cut in reasons
            with pytest.raises(ComputationControlPlaneError, match=reasons[cut]) as caught:
                issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
            error = str(caught.value)
    except BaseException as failure:
        # Reporting never replaces the original registration failure.
        try:
            retained=state.registrations.get(preparation.grant_record.record_id)
            numerical=getattr(retained,"numerical_work",None)
            original=getattr(retained,"numerical_original",None)
            print("LP03_EDGE_REGISTRATION_FAILURE_PROGRESS="+deterministic_json(dict(
                failure_class=type(failure).__name__,failure_text=str(failure),formula_and_conversion_calls=calls,
                original_envelope=preparation.envelope_entry[3],original_source_slices=preparation.input_assembly_members[1],
                original_protocol=protocol,phase=getattr(retained,"commit_state",None),
                numerical_phase=original[1]if type(original)is tuple and len(original)>1 else None,
                numerical_consumed=dict(numerical.consumed)if numerical is not None and hasattr(numerical,"consumed")else None,
                parent_readback_observation=getattr(retained,"parent_readback_observation",None),
                stored_rows={table:store._connection.execute("SELECT * FROM "+table+" ORDER BY 1").fetchall()
                    for table in("receipt_records","idempotency_claims")})))
        except BaseException:
            pass
        raise
    finally:
        sys.setprofile(previous)
    registration = state.registrations[preparation.grant_record.record_id]
    work = registration.numerical_work
    original = registration.numerical_original
    assert calls == [] and registration.attempts == {} and state.supervisor is None
    assert state.operation is None and not store._connection.in_transaction
    assert registration.accounting_observation_state == "OBSERVED" and registration.parent_readback_observation is not None
