    assert work._math26_context_steps == [] and work._math26_context_prefix == ()
    assert all(entry[3] == "MARKET_FINANCIAL_DECIMAL_V1" for entry in work._decimal_admissions)
    assert all(work.consumed[key] == 0 for key in ("log_series_terms", "square_roots", "random_draws"))
    if cut is None:
        assert registration.commit_state == "COMMITTED_AND_READBACK" and registration.handle is result
        assert len(registration.readback_refs) == len(registration.readback_rows) == 10
        assert registration.commit_observation[0] <= registration.readback_observation[0]
