def _lp03_cashflow_fixture_values(math_id):
    """Prospective signed totals and hand-derived outputs, never formula returns."""
    basis="SIGNED_TOTAL_ACCOUNT_CASHFLOW_EACH_EVENT_INCLUDED_EXACTLY_ONCE"
    values=dict(fill_probability="0.50",entry_trade_cashflow_total="-0.40",no_fill_cashflow_total="-0.02",
        platform_fee_total="0.01",builder_fee_total="0.02",other_fee_total="0.03",expected_rebate_total="0.005",
        exit_slippage_reserve_total="0.01",market_impact_reserve_total="0.01",latency_adverse_selection_reserve_total="0.01",
        capital_time_cost_reserve_total="0.01",cashflow_basis=basis)
    if math_id=="MATH-06":
        values.update(p_win="0.50",p_void="0.25",win_terminal_cashflow_total="1.00",
            lose_terminal_cashflow_total="0.00",void_terminal_cashflow_total="0.40")
        expected=dict(expected_net_cash="0.042500",expected_net_cash_if_filled="0.1050",
            expected_terminal_cashflow="0.6000",p_lose="0.25")
    else:
        assert math_id=="MATH-07"
        values.update(outcome_ids=("CF-W","CF-L"),outcome_probabilities=("0.25","0.75"),
            outcome_terminal_cashflow_totals=("1.00","0.00"),probability_simplex_tolerance="0.00")
        expected=dict(expected_net_cash="-0.132500",expected_net_cash_if_filled="-0.2450",
            expected_terminal_cashflow="0.2500",outcome_ids=("CF-W","CF-L"),
            normalized_probabilities=("0.25","0.75"),original_probability_sum="1.00",normalization_applied=False)
    return values,expected


