def _lp03_original_private_execution_reference_v1(math_id, *, case=None):
    if math_id == "MATH-32":
        return dict(side="SELL", quantity="3", execution_price="0.49", decision_price="0.52",
            explicit_fees="0.02", opportunity_cost_unfilled="0.015", other_declared_costs="-0.005"), "0.120"
    if math_id == "MATH-33":
        if case == "sell_zero":
            return dict(side="SELL", quantity="0.00", execution_price="0.50", midpoint_at_decision="0.49"), "0.0000"
        return dict(side="SELL", quantity="3", execution_price="0.49", midpoint_at_decision="0.50"), "0.03"
    if math_id == "MATH-35":
        namespace = "ORIGINAL-PRIVATE-EXECUTION::MATH-35"
        quote = dict(receipt_id=namespace+"::QUANTIZATION-RECEIPT", policy_ref=namespace+"::CENT",
            field_id="SIGNED_FEE", pre_value="-0.0250", post_value="-0.02", residual="-0.0050",
            unit="USD", currency_or_asset="USD", basis="SIGNED_EXPLICIT_FEE", scale=2, rounding="ROUND_HALF_EVEN")
        expected = dict(amount_before_rounding="-0.0250", amount_after_rounding="-0.02",
            quantization_receipt=quote, component_class="EXPLICIT_MAKER_REBATE",
            source_binding_ref=namespace+"::FEE-SCHEDULE", embedded_in_price=False)
        return dict(contracts="2", theta="-0.05", price="0.5", liquidity_role="MAKER",
                    receipt_id=quote["receipt_id"]), expected
    if math_id == "MATH-36":
        inputs = dict(yes_bids=("0.20", "0.40"), no_bids=("0.25", "0.55"), payout="1.00",
            book_sequence=15, expected_sequence=14 if case == "book_sequence" else 15,
            book_state="CURRENT_CONTIGUOUS_SNAPSHOT_PLUS_DELTAS",
            price_ranges=(dict(minimum="1E-40" if case == "book_grid_decimal34" else "0.00",
                maximum="1.00", step="0.05"),))
        expected = dict(best_yes_bid="0.40", best_no_bid="0.55", derived_yes_ask="0.45",
            derived_no_ask="0.60", book_sequence=15)
        return inputs, expected
    if math_id == "MATH-38":
        return {}, "2" if case == "decimal34_fill_tolerance" else "2.3"
    if math_id == "MATH-39":
        return dict(displayed_quantity_before_order="7", net_prior_additions="1.25",
            observed_prior_cancellations="2", observed_trades_ahead="3"), "3.25"
    if math_id == "MATH-40":
        return dict(signed_fill_quantity="-4", midpoint_after_fill="0.51", fill_price="0.49"), "-0.08"
    if math_id == "MATH-42":
        return dict(Y=0.5,sigma=0.125,Q="-9",ADV="36"), 0.03125
    if math_id == "MATH-43":
        if case == "capacity_power_unproven":
            from struct import unpack

            return dict(participation=0.8534340747285752, approved_participation_cap=0.29884001841101715,
                penalty_scale=1.0), unpack(">d", bytes.fromhex("400b8d787e173e34"))[0]
        return dict(participation=0.75,approved_participation_cap=0.5,penalty_scale=0.125), 0.03125
    if math_id == "MATH-44":
        return dict(sample_covariance=((0.25,0.125),(0.125,0.5)),
            target=((0.5,0.0),(0.0,0.5)),delta=0.25), ((0.3125,0.09375),(0.09375,0.5))
    assert math_id == "MATH-45" and case in (None, "gate_tie")
    edge = "0.046875" if case == "gate_tie" else "0.0625"
    return dict(estimated_net_edge=edge, uncertainty="0.015625", z_or_quantile="2", model_risk_haircut="0.015625"), dict(
        lcb_net="0.000000" if case == "gate_tie" else "0.015625", trade_gate=case is None)


def _lp03_acknowledged_queue_packets_v1(common, *, source_ns, decision, projected, case):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import CURRENT_FORMULA_INPUT_AUTHORITY_BY_MATH_ID
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import EVIDENCE_PROJECTION_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    namespace = "ORIGINAL-ACKNOWLEDGED-QUEUE"
    context = common["scope"]
    order = namespace+"::ORDER"
    matching = namespace+"::PRICE-TIME-FIFO"
    ack_wall = (source_ns-4_000_000)//1000*1000+400
    observed = source_ns-1_000_000
    available = source_ns-500_000
    book_receipt, ack_receipt = namespace+"::BOOK-RECEIPT", namespace+"::ACK-RECEIPT"

    def time_text(tick):
        return projected(tick).strftime("%Y-%m-%dT%H:%M:%S")+f".{tick%1_000_000_000:09d}Z"

    identity = dict(venue_id=context.venue_scope_id, instrument_id=context.instrument_or_contract_scope_id,
        side="YES", price="0.40", venue_evidence_ref=matching, unit="units", basis="ACKNOWLEDGED_INSERTION_POINT")
    ack = dict(identity, order_id=order, acknowledged_at=time_text(ack_wall), available_at=time_text(ack_wall+10),
        matching_priority="PRICE_TIME_FIFO", producer_receipt_ref=ack_receipt)
    expected = "3.25"
    displayed_at = ack_wall+1 if case == "queue_ack_1ns" else ack_wall-1
    rows = tuple(dict(identity, event_id=namespace+"::EVENT:"+str(sequence), sequence=sequence, event_kind=kind, quantity=quantity,
        event_time=time_text(tick), available_at=time_text(available-1), priority_order_id=order,
        producer_receipt_ref=book_receipt, ahead_of_order=True)
        for sequence, (kind, quantity, tick) in enumerate((
            ("DISPLAYED_BEFORE_ORDER","7",displayed_at), ("PRIOR_ADDITION","1.25",ack_wall+20),
            ("PRIOR_CANCELLATION","2",ack_wall+40), ("TRADE_AHEAD","3",ack_wall+60)),15))

    packets, clocks_by_id = [], {}
    bindings = CURRENT_FORMULA_INPUT_AUTHORITY_BY_MATH_ID["MATH-39"]
    for binding, body, receipt, suffix in zip(bindings, (rows,ack), (book_receipt,ack_receipt), ("BOOK","ACK"), strict=True):
        packet_id = namespace+"::"+suffix
        clocks = tuple(zip(("observed_time", "effective_time", "available_time", "received_time", "processed_time", "as_of_time"),
                           (observed, observed, available, available, available, decision), strict=True))
        packet_common = dict(common, clocks=PointInTimeClocksV1(**{name:projected(tick) for name,tick in clocks}),
            provider_sequence=18 if suffix == "BOOK" else None, revision=namespace+"::REVISION:"+suffix)
        packets.append(OwnerValuePacketV1(**packet_common, packet_id=packet_id,
            owner_id=binding.accepted_upstream_owner_id, packet_type=binding.accepted_packet_or_snapshot_type,
            schema_id=binding.schema_id, schema_version=binding.schema_version, values={binding.exact_field_path:body},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=receipt,
            producer_receipt_type=binding.producer_receipt_type,
            source_state_and_claim_lineage=binding.source_state_and_claim_lineage))
        clocks_by_id[packet_id] = clocks
    quantities = dict(displayed_quantity_before_order="7",net_prior_additions="1.25",
        observed_prior_cancellations="2",observed_trades_ahead="3")
    scope = dict(quantity_scope_ref=order,horizon_ref=book_receipt,ordered_coordinate_ids=(order,),
        output_unit="units",output_basis=EVIDENCE_PROJECTION_CONTRACTS_V1["MATH-39"].basis_requirement)
    return tuple(packets), quantities, expected, scope, clocks_by_id


def _lp03_dynamic_binary_book_packets_v1(common, *, source_ns, decision, projected, case):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import FORMULA_INPUT_AUTHORITY_BY_MATH_ID
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import EVIDENCE_PROJECTION_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    inputs, expected = _lp03_original_private_execution_reference_v1("MATH-36", case=case)
    book = "ORIGINAL-BINARY-BOOK::BOOK-RECEIPT"
    grid = "ORIGINAL-BINARY-BOOK::GRID-RECEIPT"
    packets, companions = [], {}
    for binding in FORMULA_INPUT_AUTHORITY_BY_MATH_ID["MATH-36"]:
        is_grid = binding.input_name in ("payout", "price_ranges")
        effective = source_ns - (9000 if is_grid else 6000)
        original_clocks = (("observed_time", effective + 1000), ("effective_time", effective),
            ("available_time", effective + 2000), ("received_time", effective + 3000),
            ("processed_time", effective + 4000), ("as_of_time", decision))
        packet_id = "ORIGINAL-BINARY-BOOK::" + binding.input_name
        clocks = PointInTimeClocksV1(**{name: projected(value) for name, value in original_clocks})
        packets.append(OwnerValuePacketV1(**dict(common, clocks=clocks,
            provider_sequence=13 if is_grid else 15, revision=("GRID-REV-2"
                if is_grid and binding.input_name == "price_ranges" and case == "book_grid_revision"
                else "GRID-REV-3" if is_grid else "BOOK-REV-5")),
            packet_id=packet_id, owner_id=binding.accepted_upstream_owner_id,
            packet_type=binding.accepted_packet_or_snapshot_type, schema_id=binding.schema_id,
            schema_version=binding.schema_version, values={binding.exact_field_path: inputs[binding.input_name]},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=grid if is_grid else book,
            producer_receipt_type=binding.producer_receipt_type,
            source_state_and_claim_lineage=binding.source_state_and_claim_lineage))
        companions[packet_id] = original_clocks
    return tuple(packets), inputs, expected, dict(quantity_scope_ref=book, horizon_ref=grid,
        output_unit="DECLARED_PAYOUT_UNIT_AND_PROVIDER_SEQUENCE",
        output_basis=EVIDENCE_PROJECTION_CONTRACTS_V1["MATH-36"].basis_requirement,
        ordered_coordinate_ids=(book,)), companions


def _lp03_binary64_execution_source_packets_v1(common, math_id, *, source_ns, decision, projected, case):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import EVIDENCE_PROJECTION_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    values, expected = _lp03_original_private_execution_reference_v1(math_id, case=case)
    prefix = "ORIGINAL-BINARY64-EXECUTION::"+math_id
    scope = prefix+"::SCOPE"
    horizon = prefix+"::HORIZON"
    coordinates = (prefix+"::ASSET:A",prefix+"::ASSET:B") if math_id == "MATH-44" else (prefix+"::COORDINATE",)
    unit = ("USD-CASH" if case == "impact_wrong_unit" else
        {"MATH-42":"PRICE-FRACTION","MATH-43":"UTILITY-POINT","MATH-44":"RETURN-COVARIANCE"}[math_id])
    basis = EVIDENCE_PROJECTION_CONTRACTS_V1[math_id].basis_requirement
    clocks = tuple((name, decision if name == "as_of_time" else source_ns)
        for name in ("observed_time","effective_time","available_time","received_time","processed_time","as_of_time"))
    packets, observations = [], {}
    for binding in EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1[math_id].bindings:
        input_name = binding.input_name
        packet_ref = prefix+"::"+input_name
        receipt = packet_ref+"::RECEIPT"
        actual_horizon = prefix+"::FOREIGN-HORIZON" if case == "impact_horizon" and input_name == "ADV" else horizon
        role_fact = dict(original_receipt_ref=receipt, quantity_scope_ref=scope, horizon_ref=actual_horizon,
            basis_ref=binding.unit_or_basis_requirement)
        if math_id == "MATH-43" and input_name == "participation":
            fill, volume = ("0.8534340747285752", "1") if case == "capacity_power_unproven" else (
                "5" if case == "participation_ratio" else "3", "4")
            role_fact.update(filled_quantity=fill, observed_market_volume=volume, original_quantity_unit="CONTRACT")
        elif math_id == "MATH-44" and input_name in ("sample_covariance","target"):
            role_fact.update(ordered_coordinate_ids=tuple(reversed(coordinates))
                if case == "covariance_order" and input_name == "target" else coordinates,
                original_matrix_source_ref=packet_ref+"::MATRIX")
        else:
            role_fact["original_role_source_ref"]=packet_ref+"::DECLARED-PREDECESSOR"
        original = dict(quantity_scope_ref=scope, horizon_ref=actual_horizon, output_unit=unit, output_basis=basis,
            ordered_coordinate_ids=coordinates, original_time_unit="SECONDS", original_quantity_unit="CONTRACT",
            binding_id=binding.binding_id, producer_role=binding.producer_role,
            basis_ref=binding.unit_or_basis_requirement, original_fact=role_fact)
        packets.append(OwnerValuePacketV1(**dict(common,clocks=PointInTimeClocksV1(**{
            name:projected(tick) for name,tick in clocks})), packet_id=packet_ref,
            owner_id="ORIGINAL-SOFTWARE-EXECUTION-OWNER::"+binding.producer_role,
            packet_type="LP03OriginalBinary64ExecutionInputSourceV1",
            schema_id=f"LP03::{math_id}::ORIGINAL_INPUT_SOURCE_V1", schema_version="1.0",
            values={input_name:deterministic_json(values[input_name]),"original_execution_context":original},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=receipt,
            producer_receipt_type=f"LP03::{math_id}::ORIGINAL_INPUT_RECEIPT_V1",
            source_state_and_claim_lineage=f"LP03::{math_id}::ORIGINAL_EXECUTION_INPUT::{binding.producer_role}"))
        observations[packet_ref]=clocks
    return tuple(packets),values,expected,dict(quantity_scope_ref=scope,horizon_ref=horizon,output_unit=unit,
        output_basis=basis,ordered_coordinate_ids=coordinates),observations


def _lp03_original_quantum_source_packets_v1(common, math_id, *, source_ns, decision, projected, case, lock_policy_refs):
    """Register preexisting synthetic trace inputs under the exact source-owner roles."""
    from tests.stage1_prediction_markets.qku_computation_control_plane.tranche_f.test_quantum_benchmark_matrix import (
        _basis, _comparator, _qaoa_trace, _vqe_trace,
    )
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import EVIDENCE_PROJECTION_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import _LP03_ORIGINAL_QUANTUM_OUTPUT_UNITS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.quantum_benchmark import QuantumBenchmarkServiceV1

    prefix = "ORIGINAL-QUANTUM::" + math_id
    lock_ref = "ST12F-LOCK::LP03-ORIGINAL-COMPILATION"
    bindings = EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1[math_id].bindings
    source_refs = tuple(prefix+"::"+binding.input_name for binding in bindings)
    locked_refs = lock_policy_refs + source_refs
    pins = tuple(f"{record}={common['source_epoch_id']}" for record in sorted(locked_refs))
    if case == "quantum_lock_epoch_stale":
        pins = (*pins, "LP03-ORIGINAL::baseline=LP03-EPOCH::stale")
    basis = _basis(input_lock_id=lock_ref, scenario_set_ref="LP03-PLAN::one", version_epoch_pins=pins)
    classical = _comparator("STRONGEST_CLASSICAL", basis=basis)
    no_trade = _comparator("NO_TRADE", basis=basis, utility="0", resource="0", latency="0")
    original = _vqe_trace() if math_id == "MATH-51" else _qaoa_trace()
    trace = replace(original, input_lock_id=lock_ref, comparison_basis=basis,
        strongest_classical_comparator=classical, no_trade_comparator=no_trade)
    if math_id == "MATH-50":
        values = dict(trace=trace)
        expected = dict(trace_expected_locked_cost="1.25", original_economic_objective="0.7",
            selected_candidate_id="CANDIDATE::B", selected_original_model_feasible=True, effect_call_count=0)
        coordinates = tuple(point.candidate_id for point in trace.points)
        original_refs = (trace.trace_id,)
    elif math_id == "MATH-51":
        values = dict(trace=trace)
        expected = dict(trace_expectation="0.2", variance="0.01", original_economic_objective="0.55",
            selected_candidate_id="POINT::A", selected_original_model_feasible=True, effect_call_count=0)
        coordinates = tuple(point.parameter_point_id for point in trace.points)
        original_refs = (trace.trace_id,)
    else:
        preexisting = QuantumBenchmarkServiceV1().validate_qaoa_trace(trace)
        comparison_id = "ST12F-QUANTUM-COMPARISON::" + prefix + "::comparison_id::RECEIPT"
        if case == "quantum_basis_mismatch":
            classical = replace(classical, comparison_basis=replace(basis, accounting_basis_ref="ACCOUNTING::OTHER"))
        values = dict(comparison_id=comparison_id, quantum_receipt=preexisting,
            strongest_classical_receipt=classical, no_trade_receipt=no_trade)
        expected = dict(delta_quantum_vs_classical="0.05", delta_quantum_vs_no_trade="0.7",
            winner="VALIDATED_QUANTUM", quantum_advantage_claim_allowed=False)
        coordinates = (preexisting.receipt_id, classical.receipt_id, no_trade.receipt_id)
        original_refs = (comparison_id, *coordinates)

    clocks = tuple((name, decision if name == "as_of_time" else source_ns)
        for name in ("observed_time", "effective_time", "available_time", "received_time", "processed_time", "as_of_time"))
    packets, observations = [], {}
    selected_origin = ("OBSERVED_QPU_WITHOUT_ORIGINAL_AUTHORITY" if case == "observed_quantum_claim"
        else "PREEXISTING_SYNTHETIC_TRACE_CONFORMANCE")
    for binding, original_ref in zip(bindings, original_refs, strict=True):
        field, role = binding.input_name, binding.producer_role
        record = prefix+"::"+field
        original_context = dict(binding_id=binding.binding_id, producer_role=role,
            basis_requirement=binding.unit_or_basis_requirement, origin_profile=selected_origin,
            original_lock_id=lock_ref, economic_basis=dict(basis.as_mapping()), source_trace_or_comparator_ref=original_ref)
        packets.append(OwnerValuePacketV1(**dict(common, clocks=PointInTimeClocksV1(**{
            name:projected(tick) for name,tick in clocks})), packet_id=record,
            owner_id="ORIGINAL-SOFTWARE-QUANTUM-OWNER::"+role, packet_type="LP03OriginalQuantumInputSourceV1",
            schema_id=f"LP03::{math_id}::ORIGINAL_INPUT_SOURCE_V1", schema_version="1.0",
            values={field:deterministic_json(values[field]), "original_quantum_context":original_context},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=record+"::RECEIPT",
            producer_receipt_type=f"LP03::{math_id}::ORIGINAL_INPUT_RECEIPT_V1",
            source_state_and_claim_lineage=f"LP03::{math_id}::ORIGINAL_QUANTUM_INPUT::{role}"))
        observations[record] = clocks
    _rule = EVIDENCE_PROJECTION_CONTRACTS_V1[math_id]
    evidence_scope = dict(quantity_scope_ref=basis.original_formulation_id, horizon_ref=basis.ttl_policy_ref,
        output_unit=_LP03_ORIGINAL_QUANTUM_OUTPUT_UNITS_V1[math_id], output_basis=_rule.basis_requirement,
        ordered_coordinate_ids=coordinates, economic_basis=dict(basis.as_mapping()))
    return tuple(packets), values, expected, evidence_scope, observations


def _lp03_private_execution_source_packets_v1(common, math_id, *, source_ns, decision, projected, case):
    if math_id in ("MATH-42", "MATH-43", "MATH-44"):
        return _lp03_binary64_execution_source_packets_v1(common,math_id,source_ns=source_ns,decision=decision,
            projected=projected,case=case)
    if math_id == "MATH-36":
        return _lp03_dynamic_binary_book_packets_v1(common, source_ns=source_ns, decision=decision, projected=projected, case=case)
    if math_id == "MATH-39":
        return _lp03_acknowledged_queue_packets_v1(common, source_ns=source_ns, decision=decision, projected=projected, case=case)
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import EVIDENCE_PROJECTION_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.accounting import CostEmbeddingV1, TCADecompositionV1
    inputs, expected = _lp03_original_private_execution_reference_v1(math_id, case=case)
    prior, later = source_ns - 3_000_000, source_ns - 2_000_000
    namespace = "ORIGINAL-PRIVATE-EXECUTION::" + math_id
    if math_id in ("MATH-32", "MATH-33"):
        schema = "LP03OriginalSyntheticExecutionCostSourceV1"
        metadata = "execution_cost_context"
        basis_key = "bound_field_basis"
        authority = dict(original_lane_order_ref=namespace+"::ORDER", original_lane_fill_ref=namespace+"::FILL",
            original_decision_quote_ref=namespace+"::QUOTE", instrument_ref=common["scope"].instrument_or_contract_scope_id,
            venue_ref=common["scope"].venue_scope_id, currency="USD", quantity_unit="CONTRACT",
            price_basis="USD_PER_CONTRACT", decision_quote_wall_ns=prior, fill_effective_wall_ns=later)
        if math_id == "MATH-32":
            tca_ref = namespace+"::TCA"
            authority["original_tca_ref"] = tca_ref
            embedded_fee = case == "embedded_fee"
            attribution = tuple((key, CostEmbeddingV1.ALREADY_EMBEDDED
                if key == "spread_cost" or (key == "fees" and embedded_fee) else CostEmbeddingV1.EXPLICIT)
                for key in ("spread_cost", "slippage_cost", "impact_cost", "fees", "rebates",
                    "latency_cost", "adverse_selection_cost", "opportunity_cost", "other_declared_costs"))
            tca = TCADecompositionV1(tca_ref, authority["original_decision_quote_ref"], (authority["original_lane_fill_ref"],),
                "0.09", "0", "0", "0.02", "0", "0", "0", "0.015", "-0.005",
                "0.010" if embedded_fee else "0.030", attribution)
        quantity, horizon, coordinate, unit = tuple(authority[key] for key in (
            "original_lane_order_ref", "original_decision_quote_ref", "original_lane_fill_ref", "currency"))
    elif math_id == "MATH-35":
        schema = "LP03OriginalSignedQuadraticFeeSourceV1"
        metadata, basis_key = "fee_context", "input_basis"
        authority = dict(original_fill_ref=namespace+"::contracts::RECEIPT",
            original_payout_ref=namespace+"::price::RECEIPT", original_applicability_ref=namespace+"::schedule_binding::RECEIPT",
            schedule_family="SOFTWARE_ORIGINAL_SIGNED_THETA_QUADRATIC_V1" if case != "fee_family" else "INCOMPATIBLE_SOFTWARE_FEE_FAMILY",
            original_quantization_ref=namespace+"::CENT", currency="USD", payout_unit_amount="1.00",
            actual_venue_ref=common["scope"].venue_scope_id, original_market_ref=common["scope"].market_scope_id,
            horizon_ref=namespace+"::HORIZON", original_reservation_ref=inputs["receipt_id"],
            fill_effective_wall_ns=later // 1000 * 1000)
        fill = projected(authority["fill_effective_wall_ns"])
        inputs["schedule_binding"] = dict(binding_ref=namespace+"::FEE-SCHEDULE", venue_ref=authority["actual_venue_ref"],
            market_or_category_ref=authority["original_market_ref"], schedule_version="1", source_epoch_ref=common["source_epoch_id"],
            valid_from=(fill-timedelta(seconds=1)).isoformat(), valid_until=(fill+timedelta(seconds=1)).isoformat(),
            evaluated_at=fill.isoformat(), component_classes=("MAKER_REBATE",), component_rate_bindings=(("MAKER_REBATE","-0.05"),))
        inputs["quantization_policy"] = dict(policy_id=authority["original_quantization_ref"], field_id="SIGNED_FEE",
            increment="0.01", scale=2, rounding="ROUND_HALF_EVEN", unit="USD", currency_or_asset="USD",
            basis="SIGNED_EXPLICIT_FEE" if case != "fee_policy" else "UNRELATED_ACCOUNTING_BASIS",
            source_binding_ref=inputs["schedule_binding"]["binding_ref"])
        quantity, horizon, coordinate, unit = tuple(authority[key] for key in (
            "original_fill_ref", "horizon_ref", "original_reservation_ref", "currency"))
    elif math_id == "MATH-38":
        schema = "LP03OriginalFillQuantityDistributionSourceV1"
        metadata = "distribution_context"
        basis_key = "bound_field_basis"
        authority = dict(original_order_ref=namespace+"::ORDER", quantity_scope_ref=namespace+"::QUANTITY",
            quantity_unit="CONTRACT", original_model_source_ref=namespace+"::MODEL",
            horizon_ref=namespace+"::HORIZON", horizon_seconds=30, original_order_quantity="4")
        inputs = dict(artifact=dict(artifact_id=namespace+"::MODEL-ARTIFACT", artifact_version="1",
            source_binding_ref=authority["original_model_source_ref"], scope_ref=authority["quantity_scope_ref"], horizon_seconds=30,
            evaluated_at=projected(prior).isoformat(), artifact_valid_until=(projected(source_ns)+timedelta(seconds=60)).isoformat(),
            order_quantity="4", normalization_tolerance="0", fill_quantity_distribution=(("0","0.2"),("1","0.3"),("4","0.5"))))
        if case == "decimal34_fill_tolerance":
            inputs["artifact"].update(normalization_tolerance="0.8765432109876543210987654321898766",
                fill_quantity_distribution=(("2", "0.1234567890123456789012345678101234"),))
        quantity, horizon, coordinate, unit = tuple(authority[key] for key in (
            "quantity_scope_ref", "horizon_ref", "original_order_ref", "quantity_unit"))
    else:
        schema = "LP03OriginalSoftwareExecutionRiskSourceV1"
        metadata = "original_risk_context"
        basis_key = "input_basis"
        if math_id == "MATH-40":
            authority = dict(lane_fill_ref=namespace+"::FILL", post_fill_quote_ref=namespace+"::POST-FILL-QUOTE",
                instrument_ref=common["scope"].instrument_or_contract_scope_id, horizon_ref=namespace+"::MARKOUT-HORIZON",
                currency="USD", quantity_unit="CONTRACT", horizon_duration_ns=later-prior,
                fill_effective_wall_ns=prior, post_fill_quote_wall_ns=later)
            quantity, horizon, coordinate, unit = tuple(authority[key] for key in (
                "lane_fill_ref", "horizon_ref", "post_fill_quote_ref", "currency"))
        else:
            authority = dict(original_estimate_target_ref=namespace+"::NET-EDGE", claim_family_ref=namespace+"::CLAIM-FAMILY",
                horizon_ref=namespace+"::HORIZON", edge_unit="EDGE-POINTS", uncertainty_basis_ref=namespace+"::UNCERTAINTY-BASIS",
                allocation_ref=namespace+"::ALLOCATION", preregistered_wall_ns=prior, first_outcome_available_wall_ns=later)
            quantity, horizon, coordinate, unit = tuple(authority[key] for key in (
                "original_estimate_target_ref", "horizon_ref", "allocation_ref", "edge_unit"))
    packets, companions = [], {}
    for binding in EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1[math_id].bindings:
        key = binding.input_name
        role = binding.producer_role
        observed = source_ns
        if math_id in ("MATH-32","MATH-33"):
            observed = prior if role == "LANE_DECISION_QUOTE" else later if role == "LANE_FILL" else source_ns
        elif math_id == "MATH-35":
            observed = authority["fill_effective_wall_ns"] if role == "LANE_ORDER_OR_FILL" else prior
        elif math_id == "MATH-40":
            observed = later if key == "midpoint_after_fill" else prior
        elif math_id == "MATH-45" and key in ("z_or_quantile","model_risk_haircut"):
            observed = prior - 1
        clocks = tuple((name, decision if name == "as_of_time" else observed) for name in (
            "observed_time","effective_time","available_time","received_time","processed_time","as_of_time"))
        packet_ref = namespace+"::"+key
        metadata_body = dict(authority, binding_id=binding.binding_id, producer_role=role,
            **{basis_key: binding.unit_or_basis_requirement})
        owner_values = {key:inputs[key], metadata:metadata_body}
        if math_id == "MATH-32" and key == "other_declared_costs":
            owner_values["original_tca_decomposition_json"] = deterministic_json(tca)
        packets.append(OwnerValuePacketV1(**dict(common,clocks=PointInTimeClocksV1(**{
            name:projected(tick) for name,tick in clocks})), packet_id=packet_ref,
            owner_id="ORIGINAL-SOFTWARE-EXECUTION-OWNER::"+role, packet_type=schema,
            schema_id=f"LP03::{math_id}::ORIGINAL_INPUT_SOURCE_V1", schema_version="1.0",
            values=owner_values, authorized_binding_ids=(binding.binding_id,),
            producer_receipt_id=packet_ref+"::RECEIPT", producer_receipt_type=f"LP03::{math_id}::ORIGINAL_INPUT_RECEIPT_V1",
            source_state_and_claim_lineage=f"LP03::{math_id}::ORIGINAL_EXECUTION_INPUT::{role}"))
        companions[packet_ref]=clocks
    basis = EVIDENCE_PROJECTION_CONTRACTS_V1[math_id].basis_requirement
    return tuple(packets), inputs, expected, dict(quantity_scope_ref=quantity, horizon_ref=horizon, output_unit=unit,
        output_basis=basis, ordered_coordinate_ids=(coordinate,)), companions


def _lp03_private_analytic_vectors_v1(math_id, *, case=None):
    """Fixed references derived independently of the original kernels."""
    if case == "decimal34_tail":
        assert math_id in ("MATH-30", "MATH-31")
        # With 1/3 rounded before applying each row, a single final rounding
        # of the exact rational tail gives a different last digit.
        tail = "0.01851426138782460621541081311196253"
        inputs = dict(losses=("0.01", "0.01", "0.03"), alpha="0.217")
        if math_id == "MATH-30":
            raw = dict(value_at_risk="0.01", conditional_value_at_risk=tail, confidence="0.217")
            basis = "TAIL_LOSS_AT_ORIGINAL_CONFIDENCE"
        else:
            raw, basis = tail, "HISTORICAL_EXPECTED_SHORTFALL_AT_ORIGINAL_CONFIDENCE"
        return inputs, raw, "3f92f5670cae63b7", "LOSS", basis, ("LOSS-0", "LOSS-1", "LOSS-2")
    tail = "0.09333333333333333333333333333333333"
    loss_inputs = dict(losses=("0.01", "0.03", "0.06", "0.11"), alpha="0.625")
    loss_coordinates = ("LOSS-0", "LOSS-1", "LOSS-2", "LOSS-3")
    if math_id == "MATH-29":
        inputs = dict(weights=("0.25", "0.75"), expected_returns=("0.15", "0.05"),
            covariance=(("0.04", "0.01"), ("0.01", "0.09")), risk_aversion="0.80", transaction_cost="0.00725")
        if case == "decimal34_covariance":
            # The original Decimal34 context represents the symmetrized
            # off-diagonal as 1 before the semidefinite check.
            off_diagonal = "1.0000000000000000000000000000000001"
            inputs["covariance"] = (("1", off_diagonal), (off_diagonal, "1"))
            return (inputs, "-0.3322500000000000000000000000000000", "bfd54395810624dd",
                "UTILITY", "OBJECTIVE_FOR_ORIGINAL_INPUT_WEIGHTS", ("ASSET-A", "ASSET-B"))
        return inputs, "0.04500000", "3fa70a3d70a3d70a", "UTILITY", "OBJECTIVE_FOR_ORIGINAL_INPUT_WEIGHTS", ("ASSET-A", "ASSET-B")
    if math_id == "MATH-30":
        raw = dict(value_at_risk="0.06", conditional_value_at_risk=tail, confidence="0.625")
        return loss_inputs, raw, "3fb7e4b17e4b17e5", "LOSS", "TAIL_LOSS_AT_ORIGINAL_CONFIDENCE", loss_coordinates
    if math_id == "MATH-31":
        return loss_inputs, tail, "3fb7e4b17e4b17e5", "LOSS", "HISTORICAL_EXPECTED_SHORTFALL_AT_ORIGINAL_CONFIDENCE", loss_coordinates
    assert math_id == "MATH-37"
    return {}, "0.1", "3fb999999999999a", "PROBABILITY", "FILL_PROBABILITY_ON_ORIGINAL_CALIBRATED_HORIZON", ("FILL-FEATURE-SNAPSHOT",)


def _lp03_private_analytic_source_packets_v1(common, math_id, *, original_time, case):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1

    inputs, _, _, unit, basis, coordinates = _lp03_private_analytic_vectors_v1(math_id, case=case)
    quantity_scope_ref = "PRIVATE-ANALYTIC::SYNTHETIC::" + math_id
    horizon_ref = "PRIVATE-ANALYTIC::HORIZON::" + math_id
    if math_id == "MATH-37":
        inputs = dict(artifact=dict(artifact_id="FILL-ARTIFACT::ORIGINAL", artifact_version="1",
            feature_schema_ref="FILL-FEATURE-SCHEMA::V1", calibration_receipt_ref="FILL-CALIBRATION-RECEIPT::ORIGINAL",
            scope_ref=quantity_scope_ref, horizon_seconds=60, probability="0.1", feature_snapshot_ref=coordinates[0],
            feature_observed_at=(original_time - timedelta(seconds=2)).isoformat(),
            evaluated_at=(original_time - timedelta(seconds=1)).isoformat(),
            artifact_valid_until=(original_time + timedelta(seconds=30)).isoformat(),
            maximum_feature_age=dict(days=0, seconds=15, microseconds=0), calibration_state="VALIDATED"),
            feature_schema_ref="FILL-FEATURE-SCHEMA::V1", scope_ref=quantity_scope_ref, horizon_seconds=60)
    context = dict(quantity_scope_ref=quantity_scope_ref, horizon_ref=horizon_ref,
        ordered_coordinate_ids=coordinates, unit=unit, basis=basis)
    packets = []
    for binding in EVIDENCE_PRIVATE_INPUT_CONTRACTS_V1[math_id].bindings:
        name = binding.input_name
        packet_ref = f"PRIVATE-ANALYTIC::{math_id}::{name}"
        packets.append(OwnerValuePacketV1(**common, packet_id=packet_ref,
            owner_id="LP03-SYNTHETIC-OWNER::" + binding.producer_role,
            packet_type="LP03OriginalPrivateInputSourceV1", schema_id=f"LP03::{math_id}::ORIGINAL_INPUT_SOURCE_V1",
            schema_version="1.0", values={name: inputs[name], "private_source_context": dict(context,
                binding_id=binding.binding_id, producer_role=binding.producer_role,
                original_basis_ref=binding.unit_or_basis_requirement)},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=packet_ref+"::RECEIPT",
            producer_receipt_type=f"LP03::{math_id}::ORIGINAL_INPUT_RECEIPT_V1",
            source_state_and_claim_lineage=f"LP03::{math_id}::ORIGINAL_INPUT::{binding.producer_role}"))
    return tuple(packets), inputs, context


def _assert_lp03_private_analytic_registration(issuer, issuer_context, state, preparation, request, protocol, store, *, cut):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.persistence import _EvidenceRegistrationOperationV1

    if cut == "quantum_lock_epoch_stale":
        import pytest
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError

        with pytest.raises(ComputationControlPlaneError, match="LP03_QUANTUM_ORIGINAL_LOCK_EPOCHS_AND_SCENARIO") as caught:
            issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
        failed = state.registrations[preparation.grant_record.record_id]
        assert failed.handle is None and failed.records == () and not failed.attempts
        assert failed.commit_observation is failed.readback_observation is None
        assert state.operation is None and state.supervisor is None and not store._connection.in_transaction
        print("LP03_QUANTUM_ORIGINAL_LOCK_EPOCH_DENIAL=" + deterministic_json(dict(
            diagnostic=str(caught.value), snapshot_source_epochs=dict(preparation.input_assembly_outcome.canonical_snapshot.source_epochs),
            declared_basis=protocol.numeric_profile["economic_basis"], registration_consumption=dict(failed.consumed))))
        return failed
    assert cut is None
    result = issuer.register_evidence_experiment_v1(request, issuer_context=issuer_context)
    registration = state.registrations[preparation.grant_record.record_id]
    original = _EvidenceRegistrationOperationV1._assert_numerical_original_v1(registration)
    assert registration.commit_state == "COMMITTED_AND_READBACK" and registration.handle is result
    assert original is preparation.registration_numerical_original and not registration.attempts
    execution = protocol.analysis_profile in ("DETERMINISTIC_ORIGINAL_PRIVATE_DECIMAL_EXECUTION_CONFORMANCE_V1", "DETERMINISTIC_ORIGINAL_PRIVATE_BINARY64_EXECUTION_CONFORMANCE_V1")
    quantum = protocol.analysis_profile == "DETERMINISTIC_ORIGINAL_QUANTUM_CONSTRUCTOR_CONFORMANCE_V1"
    if quantum:
        assert original[8]["profile"] == "ORIGINAL_QUANTUM_CONSTRUCTOR_ADMISSION_V1"
    elif execution:
        assert original[8]["profile"] == "ORIGINAL_PRIVATE_EXECUTION_ADMISSION_V1"
    else:
        assert original[8]["conversion_work_limits"] == protocol.numeric_profile["conversion_work_limits"]
    assert state.operation is None and not store._connection.in_transaction
    print(("LP03_QUANTUM_REGISTERED=" if quantum else "LP03_PRIVATE_EXECUTION_REGISTERED=" if execution else "LP03_PRIVATE_ANALYTIC_REGISTERED=")+deterministic_json(dict(math_id=protocol.numeric_profile["math_id"],
        original_bound=original[8],protocol=protocol,numerical_consumption=dict(registration.numerical_work.consumed),
        committed=registration.commit_observation,independently_read=registration.readback_observation,
        records=registration.records,readbacks=registration.readback_rows)))
    return registration



def _lp03_recorded_ope_point_source_packets_v1(common, math_id, *, clock, project_clock, cutoff_wall_ns):
    """Issue the original synthetic point-estimator inputs and owner observations."""
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import FORMULA_INPUT_AUTHORITY_BY_MATH_ID
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    inputs, expected = _lp03_recorded_ope_point_vectors_v1(math_id)
    fit_cutoff = clock() // 1000 * 1000
    _lp03_wait_until_native_clock_v1(clock, clock() + 1_000_000)
    first_labels = clock() // 1000 * 1000
    published = clock() // 1000 * 1000
    assert fit_cutoff < first_labels <= published <= cutoff_wall_ns
    names = ("observed_time", "effective_time", "available_time", "received_time", "processed_time", "as_of_time")
    clocks = tuple((name, cutoff_wall_ns if name == "as_of_time" else published) for name in names)
    common = dict(common, clocks=PointInTimeClocksV1(**{name: project_clock(value) for name, value in clocks}))
    if math_id == "MATH-24":
        row_ids = ("PT-W2", "PT-W1", "PT-W0")
        alignment = {"aligned_rows.row_ids": row_ids, "aligned_rows.snapshot_ref": "OPE-SNIPS-ALIGNED-ROWS"}
        extras = (alignment,) * 2
    else:
        rows = inputs["logged_rows"]
        row_ids = tuple(row["row_id"] for row in rows)
        folds = tuple(sorted({row["fold_id"] for row in rows}))
        fit_roster = tuple(dict(fold_id=fold,
            evaluation_row_ids=tuple(row["row_id"] for row in rows if row["fold_id"]==fold),
            training_row_ids=tuple(row["row_id"] for row in rows if row["fold_id"]!=fold),
            nuisance_prediction_receipt_ref=f"OPE-Q::{fold}", training_exclusion_ref=f"OPE-EXCLUDE::{fold}",
            fit_cutoff_wall_ns=fit_cutoff, first_evaluation_label_available_wall_ns=first_labels) for fold in folds)
        extras = (dict(original_nuisance_fit_roster=fit_roster),) + ({},) * (len(inputs)-1)
    packets = []
    for index, (binding, extra) in enumerate(zip(FORMULA_INPUT_AUTHORITY_BY_MATH_ID[math_id], extras, strict=True)):
        source_id = f"OPE-POINT::{index}"
        packets.append(OwnerValuePacketV1(**common, packet_id=source_id, owner_id=binding.accepted_upstream_owner_id,
            packet_type=binding.accepted_packet_or_snapshot_type, schema_id=binding.schema_id,
            schema_version=binding.schema_version, values={binding.exact_field_path: inputs[binding.input_name], **extra},
            authorized_binding_ids=(binding.binding_id,), producer_receipt_id=source_id+"::RECEIPT",
            producer_receipt_type=binding.producer_receipt_type, source_state_and_claim_lineage=binding.source_state_and_claim_lineage))
    return tuple(packets), inputs, expected, row_ids, clocks


def _lp03_recorded_dr_runtime_vectors_v1():
    """Four dyadic software rows with independently expected original estimator."""
    rows = (
        dict(row_id="DR-A",fold_id=0,logged_action_index=0,reward=0.25),
        dict(row_id="DR-B",fold_id=0,logged_action_index=1,reward=0.50),
        dict(row_id="DR-C",fold_id=1,logged_action_index=0,reward=0.50),
        dict(row_id="DR-D",fold_id=1,logged_action_index=1,reward=0.75),
    )
    originals = tuple(dict(row,behavior_action_probabilities=(0.5,0.5),target_action_probabilities=(0.5,0.5),
        cross_fitted_reward_model_predictions=(0.25,0.75),cross_fitted_prediction=True) for row in rows)
    # The original simplex tolerance admits this third supported action.
    # Its zero nuisance contribution preserves the independent expected score.
    near_simplex = (0.5, 0.5, 2.0**-43)
    originals = (dict(originals[0], behavior_action_probabilities=near_simplex, target_action_probabilities=near_simplex,
        cross_fitted_reward_model_predictions=(0.25, 0.75, 0.0)), *originals[1:])
    expected = dict(doubly_robust_estimate=0.5,row_values=(0.5,0.25,0.75,0.5),
        importance_weights=(1.0,)*4,effective_sample_size=4.0,clipping_applied=False)
    return originals, expected


def _lp03_recorded_dr_runtime_source_packets_v1(common, *, clock, project_clock, cutoff_wall_ns, case):
    """Create locked software source packets and their accepted typed policy."""
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.bindings import FORMULA_INPUT_AUTHORITY_BY_MATH_ID
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.input_resolver import OwnerValuePacketV1

    rows, _ = _lp03_recorded_dr_runtime_vectors_v1()
    row_ids = tuple(row["row_id"] for row in rows)
    log_ref, log_receipt, uncertainty_ref = "DR-ROWS", "DR-ROWS::RECEIPT", "DR-UNCERTAINTY-POLICY"
    protocol_ref = "LP03-ORIGINAL::parameter-protocol"
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PointInTimeClocksV1

    first_observation = clock() // 1000 * 1000
    _lp03_wait_until_native_clock_v1(clock, clock() + 1_000_000)
    second_observation = clock() // 1000 * 1000
    if case == "outcome_leak":
        first_labels, fitted = first_observation, second_observation
    else:
        fitted, first_labels = first_observation, second_observation
    published = clock() // 1000 * 1000
    assert first_observation < second_observation <= published <= cutoff_wall_ns
    names = ("observed_time","effective_time","available_time","received_time","processed_time","as_of_time")
    clocks = tuple((name,cutoff_wall_ns if name=="as_of_time" else published) for name in names)
    common = dict(common, clocks=PointInTimeClocksV1(**{name:project_clock(value) for name,value in clocks}))
    binding, = FORMULA_INPUT_AUTHORITY_BY_MATH_ID["MATH-22"]
    log = OwnerValuePacketV1(**common,packet_id=log_ref,owner_id=binding.accepted_upstream_owner_id,
        packet_type=binding.accepted_packet_or_snapshot_type,schema_id=binding.schema_id,schema_version=binding.schema_version,
        values={binding.exact_field_path:rows},authorized_binding_ids=(binding.binding_id,),
        producer_receipt_id=log_receipt,producer_receipt_type=binding.producer_receipt_type,
        source_state_and_claim_lineage=binding.source_state_and_claim_lineage)

    groups = (row_ids[:2],row_ids[2:]) if case!="unequal_groups" else (row_ids[:1],row_ids[1:])
    crossfit = tuple(dict(fold_id=index,training_row_ids=row_ids[2:] if index==0 else row_ids[:2],
        evaluation_row_ids=row_ids[:2] if index==0 else row_ids[2:],
        prediction_receipt_ref=f"DR-Q::{index}",training_exclusion_ref=f"DR-EXCLUDE::{index}") for index in range(2))
    group_lower = None if case == "unknown_group_bound" else "0"
    roles = (
        ("logging_policy_ref","LoggedPolicyEvaluationDatasetOwnerV1","LOGGING_POLICY_AND_POSITIVITY_RULE",
            dict(behavior_propensity_rule="ORIGINAL_RECORDED_ACTION_POLICY",target_support_required=True)),
        ("support_receipt_ref","LoggedPolicyEvaluationDatasetOwnerV1","ORIGINAL_TARGET_ACTION_SUPPORT_TRACE",
            dict(rule="ALL_POSITIVE_TARGET_ACTIONS_WITHIN_LOGGING_POLICY_SUPPORT",
                supported_logged_actions=tuple(row["logged_action_index"] for row in rows))),
        ("reward_basis_ref","LoggedPolicyEvaluationDatasetOwnerV1","ORIGINAL_REWARD_UNIT_AND_HORIZON",
            dict(unit="REWARD",basis="ORIGINAL_LOGGED_REWARD_UNITS",recorded_reward=True)),
        ("crossfit_plan_ref","LoggedPolicyEvaluationDatasetOwnerV1","ORIGINAL_NUISANCE_FIT_AND_EXCLUSION_PLAN",
            dict(policy="ORIGINAL_CROSSFIT",fit_receipts=tuple(dict(row,nuisance_fit_cutoff_wall_ns=fitted,
                first_evaluation_label_available_wall_ns=first_labels) for row in crossfit))),
        ("conditional_target_assumption_ref","ComputationParameterPolicyOwnerV1","SYNTHETIC_CONDITIONAL_RECORDED_SCORE_ASSUMPTION",
            dict(assumption="FIXED_SYNTHETIC_CONDITIONAL_RECORDED_SCORE_MEAN",origin="SOFTWARE_CONFORMANCE",original_policy_value_claim=False)),
        ("group_bound_proof_ref","ComputationParameterPolicyOwnerV1","ORIGINAL_BOUNDED_GROUP_AND_ERROR_ALLOCATION",
            dict(coverage="COMPLETE_EQUAL_SIZE_EQUAL_WEIGHT_ORDERED_GROUPS",group_lower=group_lower,group_upper="1",alpha="0.05",claim_ordinal=1)),
    )
    material = []
    refs = {}
    for field,owner,role,support in roles:
        if case=="missing_assumption" and field=="conditional_target_assumption_ref":
            refs[field]=None
            continue
        ref="DR-ASSUME::"+field
        refs[field]=ref
        claim=dict(role=role,dataset_receipt_ref=log_receipt,protocol_ref=protocol_ref,row_ids=row_ids,
            declared_target="MEAN_CONDITIONAL_RECORDED_DR_SCORE",basis="ORIGINAL_LOGGED_REWARD_UNITS",unit="REWARD",
            supporting_record=support)
        material.append(OwnerValuePacketV1(**common,packet_id=ref,owner_id=owner,packet_type="EvidenceRecordedDrAssumptionV1",
            schema_id="LP03::RECORDED_DR_ASSUMPTION_V1",schema_version="1.0",values={"assumption":claim},
            authorized_binding_ids=("LP03::RECORDED_DR_ASSUMPTION_RIGHT_V1::"+field,),
            producer_receipt_id=ref+"::RECEIPT",producer_receipt_type="EvidenceRecordedDrAssumptionReceiptV1",
            source_state_and_claim_lineage="ORIGINAL_SOFTWARE_RECORDED_DR_ASSUMPTION"))
    policy = dict(profile="RECORDED_DR_EQUAL_GROUPS_V1",protocol_ref=protocol_ref,raw_receipt_ref="ORIGINAL_ATTEMPT_RAW_RESULT_REQUIRED",
        input_receipt_ref=log_receipt,row_ids=row_ids,groups=tuple(dict(ordinal=index,row_ids=group) for index,group in enumerate(groups,1)),
        group_weights=("1","1"),group_lower=group_lower,group_upper="1",alpha="0.05",claim_ordinal=1,
        unit="REWARD",basis="ORIGINAL_LOGGED_REWARD_UNITS",crossfit_records=crossfit,**refs)
    uncertainty = OwnerValuePacketV1(**common,packet_id=uncertainty_ref,owner_id="ComputationParameterPolicyOwnerV1",
        packet_type="EvidenceRecordedDrUncertaintyPolicyV1",schema_id="LP03::RECORDED_DR_UNCERTAINTY_POLICY_V1",schema_version="1.0",
        values={"policy_json":deterministic_json(policy)},authorized_binding_ids=("LP03::RECORDED_DR_UNCERTAINTY_POLICY_RIGHT_V1",),
        producer_receipt_id=uncertainty_ref+"::RECEIPT",producer_receipt_type="EvidenceRecordedDrUncertaintyPolicyReceiptV1",
        source_state_and_claim_lineage="ORIGINAL_SOFTWARE_GROUP_AND_UNCERTAINTY_POLICY")
    return (log,uncertainty,*material), policy, clocks


def _lp03_heldout_runtime_reference_v1(math_id):
    """Independent expected topology and per-fold scorer outputs for eight samples."""
    from decimal import Decimal, localcontext
    from fractions import Fraction
    from itertools import combinations

    ids = tuple(f"F{index}" for index in range(8))
    intervals = tuple(dict(sample_id=name, start=float(2 * index), end=float(2 * index + 1))
        for index, name in enumerate(ids))
    interval_by_id = {row["sample_id"]: (row["start"], row["end"]) for row in intervals}
    shuffled = tuple(intervals[index] for index in (3, 6, 0, 5, 2, 7, 1, 4))
    groups = tuple(ids[index:index + 2] for index in range(0, len(ids), 2))
    fold = math_id == "MATH-20"
    assert fold or math_id == "MATH-21"
    combos = tuple((index,) for index in range(4)) if fold else tuple(combinations(range(4), 2))
    splits = []
    expected = []
    for index, combination in enumerate(combos):
        test = tuple(name for group in combination for name in groups[group])
        train = tuple(name for name in ids if name not in test)
        split = dict(test_sample_ids=test, train_sample_ids=train, purged_sample_ids=(), embargoed_sample_ids=(),
            merged_test_intervals=tuple(interval_by_id[name] for name in test))
        if fold:
            split["fold_id"] = index
            points = tuple(0.125 if ids.index(name) % 2 == 0 else 1.125 for name in test)
            expected.append(dict(mean_brier_score=0.625, per_observation=points))
        else:
            split.update(split_id=index, test_groups=combination)
            with localcontext() as ctx:
                ctx.prec = 160
                low = float(-Decimal("0.75").ln())
                high = float(-Decimal("0.25").ln())
            points = tuple(low if ids.index(name) % 2 == 0 else high for name in test)
            expected.append(dict(mean_log_loss=float(sum(map(Fraction, points), Fraction()) / len(points)),
                per_observation=points))
        splits.append(split)
    if fold:
        native = dict(sample_intervals=shuffled, folds=4, embargo_duration=0.5)
        topology = dict(ordered_sample_ids=ids, folds=tuple(splits),
            interval_semantics="HALF_OPEN_START_INCLUSIVE_END_EXCLUSIVE",
            embargo_basis="TIME_DURATION_AFTER_MERGED_TEST_INTERVAL")
    else:
        native = dict(sample_intervals=shuffled, N_groups=4, k_test_groups=2,
            embargo_duration=0.5, aggregation_rule="ALL_PATHS_NO_CHERRY_PICKING")
        matches = ((0, 5), (1, 4), (2, 3))
        topology = dict(N_groups=4, k_test_groups=2, split_count=6, path_count=3,
            expected_path_count=3, aggregation_rule="ALL_PATHS_NO_CHERRY_PICKING", splits=tuple(splits),
            paths=tuple(dict(path_id=ordinal, split_ids=path, test_group_partition=tuple(combos[i] for i in path))
                for ordinal, path in enumerate(matches)))
    return native, topology, tuple(expected), ids


