def _lp03_causal_public_events_v1(source_ns, projected):
    """Produce local Gemini candidates through the actual LP02 decoder."""
    import pytest
    from src.qtt.stage1_prediction_markets.market_data_ingest import policy
    from src.qtt.stage1_prediction_markets.market_data_ingest.adapter import PITRawFrameV1
    from src.qtt.stage1_prediction_markets.market_data_ingest.binding import build_selected_pit_public_data_contracts_v2
    from src.qtt.stage1_prediction_markets.market_data_ingest.validator import PITMarketDataIngestDispatcherV2
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence_execution import _evidence_timeline_public_candidate_v1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.point_in_time import PITEventKindV2
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.source_policy import (
        PITRightsAdmissionReceiptV1, PITSourceCurrentizationReceiptV1,
    )

    at = projected(source_ns)
    sources, rights = [], []
    for profile in policy.PIT_SELECTED_SCOPE_V2.serialization:
        source_id = f"FIXTURE-SOURCE::{profile.value}"
        sources.append(PITSourceCurrentizationReceiptV1(receipt_id=source_id + "::CURRENT", profile_id=profile,
            source_id=source_id, source_contract_version=source_id + "::V1", checked_at_utc=at,
            effective_at_utc=at - timedelta(hours=1), expires_at_utc=at + timedelta(hours=1),
            currentization_owner_id="SOURCE_CURRENTIZATION_OWNER_V1", recheck_triggers=("DETECTED_CHANGE", "EXPIRY"),
            invalidating_change_detected=False, admitted_current=True))
        rights.append(PITRightsAdmissionReceiptV1(receipt_id=source_id + "::RIGHTS", profile_id=profile,
            account_scope=f"PUBLIC-MARKET-DATA::{profile.value}", source_id=source_id, agreement_id=source_id + "::AGREEMENT",
            agreement_version="OWNER-ADMISSION-V1", internal_use_class="INTERNAL_REFERENCE_AND_RECONSTRUCTION",
            owner_decision="ADMITTED_INTERNAL_USE", checked_at_utc=at, expires_at_utc=at + timedelta(hours=1),
            recheck_triggers=("RIGHTS_CHANGE", "EXPIRY"), revoked=False,
            permitted_retention_class="APPEND_ONLY_INTERNAL_REFERENCE", prohibited_redistribution_class="NO_EXTERNAL_REDISTRIBUTION"))
    contracts = build_selected_pit_public_data_contracts_v2(policy.PIT_SELECTED_SCOPE_V2, tuple(sources), tuple(rights),
        evaluated_at_utc=at)
    contract = next(row for row in contracts if row.profile_id.value == "GEMINI_TITAN_DIRECT")
    dispatcher = PITMarketDataIngestDispatcherV2(contracts)
    kalshi = next(row for row in contracts if row.profile_id.value == "KALSHI_US_DCM_DIRECT")
    frame = PITRawFrameV1(frame_id="FIXTURE-FRAME::KALSHI-UNATTESTED", profile_id=kalshi.profile_id,
        connection_epoch="KALSHI-FIXTURE::EPOCH", capture_session_id="KALSHI-FIXTURE::CAPTURE",
        wire_dialect="KALSHI_TRADE_API_WS_V2_FIXED_POINT", channel="orderbook_delta", raw_utf8_text_or_none=None,
        parsed_source_scalar_tree_or_none={"type": "orderbook_snapshot", "sid": "SID-1", "seq": 1,
            "msg": {"market_ticker": "KALSHI-MARKET-1", "yes_dollars": [["0.40", "2.00"]], "no_dollars": [["0.50", "3.00"]]}},
        qtt_received_at_utc=at, qtt_received_monotonic_ns=10, process_epoch_id="FIXTURE::PROCESS",
        monotonic_clock_id="FIXTURE::MONOTONIC", wall_clock_source_id="FIXTURE::WALL", clock_quality_receipt_ref="FIXTURE::CLOCK",
        wall_clock_uncertainty_ns=1_000, source_contract_refs=(kalshi.contract_id,))
    original = dispatcher.ingest(frame, event_kind=PITEventKindV2.BOOK_SNAPSHOT, parse_completed_at_utc=at,
        parse_completed_monotonic_ns=11, price_increment_text="0.01", price_origin_text="0",
        quantity_increment_text_or_none="0.01")
    unwitnessed = m.EvidenceTimelineEventV1(event_id=original.event_record_id, kind=original.event_kind.value,
        origin=m.EvidenceOriginV1.SOFTWARE_CONFORMANCE, source_record_ref=m.EvidenceRecordRefV1("FIXTURE::STORE", "FIXTURE::RECORD"),
        availability_wall_ns=source_ns, effective_wall_ns=source_ns, provider_order_or_absence=(1, 1), source_revision=1,
        connection_epoch=original.connection_epoch, local_ordinal=0, payload=dict(candidate=json.loads(deterministic_json(original)),
            transport_state="CONNECTED_HEALTHY", lifecycle_state="ADMISSIBLE"))
    with pytest.raises(ContractValidationError, match="LP03_TIMELINE_ORIGINAL_STREAM_WITNESS_REQUIRED") as denied:
        _evidence_timeline_public_candidate_v1(unwitnessed)
    assert denied.value.reason_code is ReasonCode.EVIDENCE_INPUT_UNAVAILABLE
    print("LP03_CAUSAL_UNWITNESSED_VENUE_DENIAL=" + deterministic_json(dict(event=unwitnessed, reason=denied.value.reason_code.value)))
    old_epoch, next_epoch = "GEMINI-FIXTURE::EPOCH:1", "GEMINI-FIXTURE::EPOCH:2"
    channel = "prediction_markets.depth"
    instrument, market = "GEMINI-EVENT-1", "GEMINI-MARKET-1"

    def book(label, kind, sequence, epoch, elapsed):
        frame = PITRawFrameV1(frame_id="FIXTURE-FRAME::" + label, profile_id=contract.profile_id, connection_epoch=epoch,
            capture_session_id="GEMINI-FIXTURE::CAPTURE", wire_dialect="GEMINI_TITAN_DIFFERENTIAL_DEPTH_V1", channel=channel,
            raw_utf8_text_or_none=None, parsed_source_scalar_tree_or_none=dict(instrumentSymbol=instrument, marketId=market,
                U=sequence, u=sequence, bids=[["0.40", "2.00"]], asks=[["0.60", "3.00"]]),
            qtt_received_at_utc=at, qtt_received_monotonic_ns=sequence * 10,
            process_epoch_id="GEMINI-FIXTURE::PROCESS", monotonic_clock_id="GEMINI-FIXTURE::MONOTONIC",
            wall_clock_source_id="GEMINI-FIXTURE::WALL", clock_quality_receipt_ref="GEMINI-FIXTURE::QUALITY",
            wall_clock_uncertainty_ns=1_000, source_contract_refs=(contract.contract_id,))
        original = dispatcher.ingest(frame, event_kind=kind, parse_completed_at_utc=at,
            parse_completed_monotonic_ns=sequence * 10 + 1, price_increment_text="0.01", price_origin_text="0",
            quantity_increment_text_or_none="0.01")
        body = json.loads(deterministic_json(original))
        return elapsed, sequence, epoch, original.event_record_id, kind.value, dict(
            candidate=body, transport_state="CONNECTED_HEALTHY", lifecycle_state="ADMISSIBLE")

    reconnect = (0, None, old_epoch, "GEMINI-FIXTURE::RECONNECT", "SYNTHETIC_RECONNECT", dict(
        profile_id=contract.profile_id.value, market_id=market, instrument_id=instrument, channel=channel,
        next_connection_epoch=next_epoch))
    return (book("NEW", PITEventKindV2.BOOK_SNAPSHOT, 3, next_epoch, 1),
            book("PRE_ANCHOR", PITEventKindV2.BOOK_DELTA, 2, next_epoch, 1),
            reconnect, book("OLD", PITEventKindV2.BOOK_SNAPSHOT, 1, old_epoch, 0))


