def _lp03_causal_fixture_cash_v1(text):
    return dict(amount_text=text, currency_or_asset="USD", ledger_unit="CURRENCY", basis="SYNTHETIC_RESERVE",
                scale=2, rounding_policy_ref="FIXTURE::EXACT")


def _lp03_causal_fixture_reality_v1(event, immutable_inputs, lane_state):
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import EvidenceStepObservationV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json

    grant_ref = lane_state["attempt_ref"]
    primary, parallel = grant_ref + "::LEG:A", grant_ref + "::LEG:B"
    now = datetime(1970, 1, 1, tzinfo=UTC) + timedelta(microseconds=event.effective_wall_ns // 1000)

    def observation(kind, identity, payload):
        return EvidenceStepObservationV1(observation_id=grant_ref + "::OBS:" + identity, parent_event_id=event.event_id,
            kind=kind, origin=event.origin, payload=json.loads(deterministic_json(payload)))

    def custody(leg, action, prior, candidate):
        return dict(custody_receipt_id=leg + "::" + action, event_identity=event.event_id + "::" + action,
            provider_request_ref=leg + "::FIXTURE_REQUEST", economic_intent_ref=leg, attempt_ref=grant_ref,
            provider_order_ref=leg + "::FIXTURE_ONLY", event_class=action,
            source_payload_custody_ref=event.source_record_ref.record_id, effective_at=now, recorded_at=now,
            sequence_ref=event.event_id + "::" + action, prior_state=prior, candidate_state=candidate,
            authority_class="DETERMINISTIC_FIXTURE_ONLY")

    if event.local_ordinal == 2:
        return tuple(observation("SYNTHETIC_ORDER_ACK", "ACK:" + suffix,
            dict(custody=custody(leg, "ACK", "PROVIDER_PENDING", "ACKNOWLEDGED")))
            for suffix, leg in (("A", primary), ("B", parallel)))
    if event.local_ordinal == 1:
        assert tuple(row["state"] for row in lane_state["domain"]["legs"]) == ("ACKNOWLEDGED", "ACKNOWLEDGED")
        fills = []
        if event.payload["timer_ref"] == "LP03-TIMER::PARTIAL_FILLS":
            quantities = ("0.10", "0.20", "0.15", "0.30", "0.25")
            for sequence, quantity in enumerate(quantities, 1):
                prior = "ACKNOWLEDGED" if sequence == 1 else "PARTIALLY_FILLED"
                state = "FILLED" if sequence == len(quantities) else "PARTIALLY_FILLED"
                receipt = custody(primary, "FILL", prior, state)
                for field in ("custody_receipt_id", "event_identity", "sequence_ref"):
                    receipt[field] += f":{sequence}"
                fills.append(observation("SYNTHETIC_FILL", f"FILL:A:{sequence}", dict(custody=receipt,
                    fill=dict(fill_id=primary + f"::FILL:{sequence}", sequence=sequence, quantity_text=quantity,
                        payload_json=deterministic_json(dict(leg="A", match=sequence, quantity=quantity))))))
        else:
            fills.append(observation("SYNTHETIC_FILL", "FILL:A", dict(custody=custody(primary, "FILL", "ACKNOWLEDGED", "FILLED"),
                fill=dict(fill_id=primary + "::FILL:1", sequence=1, quantity_text="1.00", payload_json='{"fixture":"first-leg"}'))))
        return (
            *fills,
            observation("SYNTHETIC_MULTILEG_OUTCOME", "AFTER_FILL", dict(candidate_ref=grant_ref + "::BUNDLE", legs=(
                dict(intent_ref=primary, state="FILLED", filled_quantity_text="1.00", remaining_quantity_text="0.00"),
                dict(intent_ref=parallel, state="ACKNOWLEDGED", filled_quantity_text="0", remaining_quantity_text="2.00")))),
        )
    balances = {name: _lp03_causal_fixture_cash_v1("100.00" if name in ("available_cash", "accepted_cash_basis") else "0.00")
        for name in ("available_cash", "reserved_cash", "pending_cash", "owner_protected_cash", "quarantined_cash", "accepted_cash_basis")}
    budget = dict(budget_ref="FIXTURE::RATE", provider_ref="FIXTURE::VENUE", account_scope_ref="FIXTURE::ACCOUNT",
        endpoint_ref="FIXTURE::ENDPOINT", window_ref="FIXTURE::WINDOW", source_binding_ref=event.source_record_ref.record_id,
        capacity_units="2", remaining_units="1", operation_costs=(("FIXTURE_READ", "1", "1"),),
        operation_class="FIXTURE_READ", item_count=1, evaluated_at=now, reset_at=now + timedelta(seconds=1),
        retry_after_until=None, refill_units_per_second=None)
    return (
        observation("SYNTHETIC_AMEND", "AMEND:B", dict(intent=_lp03_causal_fixture_intent_v1(lane_state,
            immutable_inputs["original_owner_envelope_ref"], "B", "1.50"))),
        observation("SYNTHETIC_CANCEL", "CANCEL:B", dict(custody=custody(parallel, "CANCEL", "CANCEL_PENDING", "CANCELLED"))),
        observation("SYNTHETIC_SETTLEMENT", "SETTLE:A", dict(custody=custody(primary, "SETTLEMENT", "FILLED", "SETTLED"), reserve=balances)),
        observation("SYNTHETIC_VOID", "VOID:B", dict(intent_ref=parallel, void_reason_ref="FIXTURE::VOID", reserve=balances)),
        observation("SYNTHETIC_RATE_BUDGET", "RATE", dict(budget=budget)),
    )


def _lp03_causal_callbacks_v1(package, origin):
    from src.qtt.plugins.contracts import PluginAdapterBase
    from src.qtt.plugins.registry import PluginRegistry
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m

    class Strategy(PluginAdapterBase):
        def on_event_v1(self, event, immutable_inputs, lane_state, scenario_values):
            from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import (
                EvidenceRecordRefV1, EvidenceStepComputationRequestV1, EvidenceStepOutcomeV1,
            )

            assert event.availability_wall_ns <= immutable_inputs["decision_wall_ns"]
            assert len(scenario_values) == 2 and tuple(row["namespace_ordinal"] for row in scenario_values) == (0, 1)
            if event.payload.get("timer_ref") == "LP03-TIMER::REJECT":
                return EvidenceStepOutcomeV1(next_lane_state_ref=lane_state["attempt_ref"] + "::STRATEGY:REJECTED",
                    proposed_intents=(), component_requests=(), generated_observations=(), disposition="REJECTED",
                    reasons=("FIXTURE_ORIGINAL_CALLBACK_DECLINED",))
            requests = ()
            intents = ()
            if event.kind == "SYNTHETIC_TIMER" and event.local_ordinal == 2:
                intents = tuple(_lp03_causal_fixture_intent_v1(lane_state, immutable_inputs["original_owner_envelope_ref"], leg, quantity)
                                for leg, quantity in (("A", "1.00"), ("B", "2.00")))
            if event.local_ordinal == 0:
                refs = tuple(EvidenceRecordRefV1.from_canonical_mapping(dict(row))
                             for row in immutable_inputs["available_component_input_refs"])
                requests = (EvidenceStepComputationRequestV1(math_id="MATH-03", original_input_refs=refs),)
            return EvidenceStepOutcomeV1(next_lane_state_ref=lane_state["attempt_ref"] + f"::STRATEGY:{event.local_ordinal}",
                proposed_intents=intents, component_requests=requests, generated_observations=(), disposition="CONTINUE", reasons=())

    class Venue(PluginAdapterBase):
        def on_event_v1(self, event, immutable_inputs, lane_state, scenario_values):
            from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import EvidenceStepOutcomeV1

            assert lane_state["state_ref"] == lane_state["attempt_ref"] + f"::STRATEGY:{event.local_ordinal}"
            assert len(scenario_values) == 2 and tuple(row["namespace_ordinal"] for row in scenario_values) == (0, 2)
            return EvidenceStepOutcomeV1(next_lane_state_ref=lane_state["attempt_ref"] + f"::VENUE:{event.local_ordinal}",
                proposed_intents=(), component_requests=(),
                generated_observations=(_lp03_causal_fixture_reality_v1(event, immutable_inputs, lane_state)
                                        if event.kind == "SYNTHETIC_TIMER" else ()),
                disposition="COMPLETE" if event.local_ordinal == 0 else "CONTINUE",
                reasons=("FINAL_ORIGINAL_EVENT",) if event.local_ordinal == 0 else ())

    registry = PluginRegistry()
    pins = []
    for ordinal, (role, adapter) in enumerate(((m.EvidenceCallbackRoleV1.STRATEGY, Strategy),
                                               (m.EvidenceCallbackRoleV1.VENUE_REALITY, Venue)), 1):
        pin = m.EvidenceCallbackPinV1(callback_id=f"LP03-CALLBACK::{role.value}", version=f"LP03-CALLBACK-VERSION::{ordinal}",
            role=role, package_identity_ref=package, implementation_ref=f"LP03-FIXTURE-CALLBACK::{ordinal}",
            namespace_ordinal=ordinal, origin=origin)
        adapter.evidence_callback_pin_v1 = pin
        registry.register(pin.callback_id, adapter())
        pins.append(pin)
    return tuple(pins), registry


def _assert_lp03_original_snapshot_and_seal(tmp_path, fixture_keys, envelope, message, hosts, bindings, parameters, adapters,
                                          *, baseline_currency="USD", expect_rejection=None, seal_cut=None, register=False,
                                          registration_cut=None, compilation_cut=None, attempt_cut=None, selected_math="MATH-03", review_cut=None,
                                          private26_cut=None, published_kelly_source=None,
                                          measured_edge_source=None, measured_decay_fit=None, cold_native_writer=False):
    import json
    import pytest
    from dataclasses import fields, replace
