    if held_out:
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane.implementation_registry import CURRENT_IMPLEMENTATION_REGISTRY
        economic_scope = m.ComputationScopeV1("FH-M", "FH-V", "FH-EV", "FH-I", "FH-MODE", "FH-SNAP")
        common.update(context_id="FH-C", scope=economic_scope, source_epoch_id="FH-E", revision="FH-W")
        topology_bindings = FORMULA_INPUT_AUTHORITY_BY_MATH_ID[selected_math]
        score_component = "MATH-08" if selected_math == "MATH-20" else "MATH-09"
