        economic_scope = m.ComputationScopeV1("CS-M","CS-V","CS-EV","CS-I","CS-MODE","CS-SNAP")
        common.update(context_id="CS-C",scope=economic_scope,source_epoch_id="CS-E",revision="CS-W")
