        assert packet.natural_key == (bound.experiment_revision, "REPLAY", 1, 0, "MATH-03")
        assert registered.consumed["record_reads"] >= before_inputs["record_reads"] + len(attempt.allowed_reads)
        assert len(attempt.source_slices) == len(attempt.allowed_reads)
        assert all(part.access_wall_ns >= attempt.grant_record.created_wall_ns for part in attempt.source_slices)
        assert all(all(part is not old for old in outcome._slices) for part in attempt.source_slices)
        assert EvidenceInvocationInputsV1._require_original_v1(packet, attempt).authoritative_values == outcome._resolved_inputs[0].authoritative_values
        if attempt_cut in ("cached_input_member_substitution", "cached_input_resolution_substitution", "cached_source_member_substitution"):
            validated_packet, changed_packet = [], []
            original_packet_check = EvidenceInvocationInputsV1._require_original_v1
            original_objects = _EvidenceBoundStoreV1._require_original_objects_v1
            with pytest.MonkeyPatch.context() as patch:
                def record_original_packet_check(selected, selected_attempt, *, canonical=True):
                    result = original_packet_check(selected, selected_attempt, canonical=canonical)
                    if selected is packet and canonical:
                        validated_packet.append(True)
