            lane_probes.append("availability_after_native_substitution_denied")
            checked = EvidenceAvailabilityHandleV1._require_current_v1(handle, operation=lane,
                purpose=purpose, current_grant=current_grant, clock=clock)
            assert checked[1] >= handle.available_at["monotonic_ns"] >= lane.publication_readback_observation[1]
            assert lane.publication[0].publication_observation["monotonic_ns"] <= lane.publication_commit_observation[1]
            assert lane.publication[0].successful_commit_return_observation["wall_ns"] == lane.commit_observation[0]
            assert lane.publication[0].independent_readback_observation["wall_ns"] == lane.readback_observation[0]
            lane_probes.append("full_publication_closure_and_current_consumer")
