        def checked_ready_commit(adapter, ready):
            assert ready.phase == "PARENTS_READBACK" and len(ready.parent_readbacks) == 3
            original_lanes, original_parents = ready.lanes, ready.parent_readbacks
            original_objects = _EvidenceBoundStoreV1._require_original_objects_v1
            for name, replacement in (("lanes", tuple(reversed(ready.lanes))), ("parent_readbacks", ready.parent_readbacks[:1])):
                for cut in ("before_validation", "after_native_observation"):
                    changed, queries = [], []

                    def substitute_ready_parent_after_native(retained, host, store):
                        original_objects(retained, host, store)
                        if not changed:
                            setattr(ready, name, replacement)
                            changed.append(True)

                    adapter._connection.set_trace_callback(queries.append)
                    try:
                        with pytest.MonkeyPatch.context() as probe:
                            if cut == "before_validation":
                                setattr(ready, name, replacement)
                            else:
                                probe.setattr(_EvidenceBoundStoreV1, "_require_original_objects_v1", substitute_ready_parent_after_native)
                            failure = ("LP03_CONFORMANCE_PARENT_READBACK_REQUIRED" if name == "parent_readbacks" and cut == "before_validation"
                                else "LP03_CONFORMANCE_ORIGINAL_PARENT_OBSERVATIONS_CHANGED" if name == "parent_readbacks"
                                else "LP03_CONFORMANCE_ORIGINAL_MEMBERS_CHANGED")
                            with pytest.raises(ComputationControlPlaneError, match=failure):
                                original_ready_commit(adapter, ready)
                        assert not queries and ready.phase == "PARENTS_READBACK"
                        if cut == "after_native_observation":
                            assert changed == [True]
                    finally:
                        ready.lanes, ready.parent_readbacks = original_lanes, original_parents
                        adapter._connection.set_trace_callback(None)
            ready_probes.append("original_lane_and_readback_substitution_denied")
            changed, queries = [], []
            original_service_tuple = evidence_service._measured_original

            def substitute_service_after_native(retained, host, store):
                original_objects(retained, host, store)
                if not changed:
                    evidence_service._measured_original = tuple(list(original_service_tuple))
                    changed.append(True)

            adapter._connection.set_trace_callback(queries.append)
            try:
                with pytest.MonkeyPatch.context() as probe:
                    probe.setattr(_EvidenceBoundStoreV1, "_require_original_objects_v1", substitute_service_after_native)
                    with pytest.raises(ComputationControlPlaneError, match="LP03_CONFORMANCE_ORIGINAL_MEMBERS_CHANGED|LP03_MEASURED_EVIDENCE_BINDING_CHANGED"):
                        original_ready_commit(adapter, ready)
                assert changed == [True] and not queries and ready.phase == "PARENTS_READBACK"
                assert state.measured_evidence_binding is issued_binding
            finally:
                evidence_service._measured_original = original_service_tuple
                adapter._connection.set_trace_callback(None)
            ready_probes.append("original_issued_service_binding_required")
            return original_ready_commit(adapter, ready)

