    svc = DashboardReadModelService()
    supervisor = svc.bind_evidence_supervisor_v1(host_binding=svc_host, issuer_context=issuer_context)
    edge = registered.protocol.analysis_profile == "DETERMINISTIC_SAME_SNAPSHOT_PROBABILITY_EDGE_CONFORMANCE_V1"
    multiple = registered.protocol.analysis_profile == "DETERMINISTIC_ORDERED_BINARY64_MULTIPLE_TESTING_CONFORMANCE_V1"
    pbo = registered.protocol.analysis_profile == "DETERMINISTIC_ORDERED_BINARY64_CSCV_CONFORMANCE_V1"
