                    from fractions import Fraction

                    assert certificate["arithmetic"]["estimator_minus_row_mean"] == dict(numerator="0", denominator="1")
                    interval = certificate["interval"]
                    def exact(name):
                        ratio = interval[name]
                        return Fraction(int(ratio["numerator"]), int(ratio["denominator"]))

                    assert interval["n"] == 2 and interval["claim_ordinal"] == 1
                    assert exact("delta") == Fraction(1, 240) and exact("mean") == Fraction(1, 2)
                    assert exact("lower") == 0 and exact("upper") == 1
                    with localcontext() as ctx:
                        ctx.prec = 100
                        log_value = Decimal(480).ln()
                        radius_value = (log_value / 4).sqrt()
                        def as_decimal(value):
                            return Decimal(value.numerator) / Decimal(value.denominator)
                        assert as_decimal(exact("log_lower")) <= log_value <= as_decimal(exact("log_upper"))
