def _assert_lp03_edge_frame_and_source_negatives(lane):
    """Closed original pair data checks; this creates no grant or native execution."""
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    grant = lane.attempt.payload
    result = json.loads(deterministic_json(lane.exchange[2]))
    chain = json.loads(result["chain_artifact_json"])
    pending = lane.exchange[0]._resolution
    frame = dict(protocol=worker.WORKER_PROTOCOL_V1, kind="INPUT_SEGMENT", attempt_ref=grant.grant_ref,
        fence_ref=grant.fence_ref, ordinal=1, payload=dict(segment_ordinal=0, final_segment=True,
            inputs=dict(market_input_json=chain["producer_input_json"], model_input_json=pending.model_input_json,
                execution_context_json=deterministic_json(pending.execution_context),
                conversion_receipt_id=grant.grant_ref+"::CONVERSION"),
            original_record_refs=result["original_record_refs"], event=json.loads(deterministic_json(lane.exchange[5])),
            producer_invocation_contract=result["producer_invocation_contract"], invocation_contract=result["invocation_contract"]))
    args = dict(direction="PARENT_TO_WORKER", attempt_ref=grant.grant_ref, fence_ref=grant.fence_ref,
        ordinal=1, frame_byte_limit=grant.budgets.frame_byte_limit)
    raw = worker.encode_evidence_worker_frame_v1(frame, **args)
    assert deterministic_json(worker.decode_evidence_worker_frame_v1(raw, **args)) == deterministic_json(frame)
    def slices(value): return value["payload"]["event"]["payload"]["source_slices"]
    def source(value, index): return slices(value)[index]["reconstructed_canonical_events"][0]
    def replace_wire(value, field, **updates):
        wire = json.loads(value["payload"]["inputs"][field]);wire.update(updates)
        value["payload"]["inputs"][field] = deterministic_json(wire)
    inputs = (
        ("missing_external_source", lambda value:slices(value).pop()),
        ("reordered_sources", lambda value:slices(value).reverse()),
        ("external_dependency_output", lambda value:value["payload"]["inputs"].update(market_implied_probability=0.25)),
        ("producer_wire_source_mismatch", lambda value:replace_wire(value,"market_input_json",contract_price="0.50")),
        ("model_wire_source_mismatch", lambda value:replace_wire(value,"model_input_json",calibrated_model_probability=0.5)),
        ("context_ttl_mismatch", lambda value:replace_wire(value,"execution_context_json",maximum_age=61.0)),
        ("foreign_conversion_identity", lambda value:value["payload"]["inputs"].update(conversion_receipt_id="E-FOREIGN::CONVERSION")),
        ("source_binding", lambda value:source(value,0).update(authorized_binding_ids=["FIVAB::MATH-01::foreign"])),
        ("source_epoch", lambda value:source(value,1).update(source_epoch_id="E-FOREIGN")),
        ("source_snapshot_ns", lambda value:source(value,2)["native_clocks"].update(as_of_time=source(value,2)["native_clocks"]["as_of_time"]+1)),
        ("different_contract_horizon", lambda value:source(value,1)["values"]["contract_context"].update(horizon_ref="E-FOREIGN")),
        ("different_winning_outcome", lambda value:source(value,2)["values"]["contract_context"].update(winning_outcome_ref="E-FOREIGN")),
        ("different_currency", lambda value:source(value,0)["values"]["market_state"].update(currency="EUR")),
        ("calibration_receipt_join", lambda value:source(value,2)["values"]["probability_edge_context"].update(calibration_receipt_id="E-FOREIGN")),
        ("calibration_source_join", lambda value:source(value,2)["values"]["probability_edge_context"].update(calibration_source_ref=["E-FOREIGN","E-IN::3"])),
        ("calibration_role", lambda value:source(value,3)["values"]["probability_edge_context"].update(producer_role="MODEL_PREDICTION")),
        ("calibration_revision", lambda value:source(value,3).update(revision="E-FOREIGN")),
        ("uncalibrated_state", lambda value:source(value,3)["values"].update(calibration_state="UNCALIBRATED")),
        ("model_binary64_boolean", lambda value:source(value,2)["values"]["prediction.calibrated_probability"].update(value_json="true")),
        ("producer_contract", lambda value:value["payload"]["producer_invocation_contract"].update(math_id="MATH-03")),
    )
    denials = []
    for label, mutate in inputs:
        changed = json.loads(deterministic_json(frame));mutate(changed)
        with pytest.raises(ComputationControlPlaneError) as caught:
            worker.encode_evidence_worker_frame_v1(changed, **args)
        denials.append(dict(case=label, diagnostic=str(caught.value)))
    result_frame = json.loads(deterministic_json(lane.native._terminal_original[4][2]))
    result_args = dict(direction="WORKER_TO_PARENT", attempt_ref=grant.grant_ref, fence_ref=grant.fence_ref,
        ordinal=2, frame_byte_limit=grant.budgets.frame_byte_limit)
    encoded_result = worker.encode_evidence_worker_frame_v1(result_frame, **result_args)
    assert deterministic_json(worker.decode_evidence_worker_frame_v1(encoded_result, **result_args)) == deterministic_json(result_frame)
    def change_chain(value, **updates):
        original = json.loads(value["payload"]["chain_artifact_json"]);original.update(updates)
        value["payload"]["chain_artifact_json"] = deterministic_json(original)
    outputs = (
        ("raw_chain_output_join", lambda value:value["payload"].update(raw_output_json="0.25")),
        ("producer_return_join", lambda value:change_chain(value, producer_output_json='"0.50"')),
        ("consumer_return_join", lambda value:change_chain(value, consumer_output_json="0.25")),
        ("missing_stage_measurement", lambda value:change_chain(value, measured_original_stages=[])),
        ("aggregate_identity", lambda value:value["payload"]["invocation_measurement"].update(process_identity_ref="E-FOREIGN")),
        ("missing_original_producer", lambda value:value["payload"].pop("producer_invocation_contract")),
    )
    for label, mutate in outputs:
        changed=json.loads(deterministic_json(result_frame));mutate(changed)
        with pytest.raises(ComputationControlPlaneError) as caught:
            worker.encode_evidence_worker_frame_v1(changed, **result_args)
        denials.append(dict(case=label, diagnostic=str(caught.value)))
    print("LP03_EDGE_WORKER_DATA_QUALIFICATION="+deterministic_json(dict(
        scope="CLOSED_ORIGINAL_INPUT_RESULT_DATA_ONLY_NO_NEW_EXECUTION_OR_AUTHORITY",
        original_input_frame=frame, original_result_frame=result_frame, denials=denials)))


def _assert_lp03_edge_worker_partial_failures(lane):
    """Portable injected call-entry failures; no new native attempt or authority."""
    import io
    import json
    import os
    import sys
