def _assert_lp03_cscv_review_payload_contract(payload):
    from dataclasses import replace
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import EvidenceReviewDecisionPayloadV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json

    canonical = deterministic_json(payload)
    assert EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical)) == payload
    def forge_both_log_cells(data):
        for lane in data["lane_calculations"]:
            proof = lane["proof"]
            raw = json.loads(proof["raw_json"])
            ordinal=next(index for index,value in enumerate(raw["logits"]) if value!=0.0)
            sign=-1 if raw["logits"][ordinal]<0.0 else 1
            raw["splits"][ordinal]["logit"]=raw["logits"][ordinal]=sign*0.5
            proof["raw_json"]=proof["expected_json"]=lane["projected_value_json"]=deterministic_json(raw)
            proof["splits"][ordinal].update(logit_bits="bfe0000000000000" if sign<0 else "3fe0000000000000",
                dyadic_log_interval=[sign*(2**127)]*2)

    denials = (
        ("unrelated_same_sign_log",forge_both_log_cells,"LP03_CSCV_REVIEW_SIGNED_LOG_SOURCE_JOIN"),
        ("swap_lane",lambda data:data["lane_calculations"].reverse(),"LP03_CSCV_REVIEW_LANE_PROFILE"),
        ("source_ref",lambda data:data["lane_calculations"][0]["source_record_refs"][0].update(record_id="substitute"),
            "LP03_CSCV_REVIEW_SOURCE_REFERENCE_JOIN"),
        ("bound_group",lambda data:data["registration_bound_proof"].update(groups=6-data["registration_bound_proof"]["groups"]),
            "LP03_CSCV_REVIEW_(CUMULATIVE_ALLOWANCE|BOUND_SOURCE_JOIN)"),
        ("wrong_mean",lambda data:[row["proof"]["splits"][0]["training_cells"][0].__setitem__(1,"0000000000000000")
            for row in data["lane_calculations"]],"LP03_CSCV_REVIEW_SIGNED_MEAN_JOIN"),
        ("shifted_split_rows",lambda data:data["lane_calculations"][0]["proof"]["splits"][0]["test_rows"].reverse(),
            "LP03_CSCV_REVIEW_SPLIT_GROUP_JOIN"),
    )
    for case,change,diagnostic in denials:
        data=json.loads(canonical)["independent_calculation"]
        change(data)
        with pytest.raises(ComputationControlPlaneError,match=diagnostic) as caught:
            replace(payload,independent_calculation=data)
        print("LP03_CSCV_REVIEW_DATA_DENIAL="+deterministic_json(dict(case=case,diagnostic=str(caught.value))))


def _assert_lp03_sharpe_review_payload_contract(payload):
    from dataclasses import replace
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.models import EvidenceReviewDecisionPayloadV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json

    canonical = deterministic_json(payload)
    assert EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical)) == payload
    unauthorized = (
        ("lane order", lambda x: x["lane_calculations"].reverse(), "LP03_SHARPE_REVIEW_LANE_PROFILE"),
        ("source reference", lambda x: x["lane_calculations"][0]["source_record_refs"][0].update(record_id="substitute"), "LP03_SHARPE_REVIEW_SOURCE_REFERENCE_JOIN"),
        ("projection", lambda x: x["lane_calculations"][0].update(projected_value_json="0.0"), "LP03_SHARPE_REVIEW_RAW_PROJECTION_AND_INPUT_JOIN"),
        ("count", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(count_minus_one=5), "LP03_SHARPE_REVIEW_RAW_PROJECTION_AND_INPUT_JOIN"),
        ("bound", lambda x: x["registration_bound_proof"].update(fixed_upper={"numerator":"2","denominator":"1"}), "LP03_SHARPE_REVIEW_BOUND_PROFILE"),
        ("budget", lambda x: x["review_numerical_limits"].update(max_serialized_bytes=0),
            "ST12A_INVALID_CONTRACT: public capture counter is outside its exact integer domain"),
    )
    failures = []
    for name, change, diagnostic in unauthorized:
        calculation = json.loads(canonical)["independent_calculation"]
        change(calculation)
        with pytest.raises(ComputationControlPlaneError, match=diagnostic) as caught:
            replace(payload, independent_calculation=calculation)
        failures.append(dict(case=name, diagnostic=str(caught.value)))
        print("LP03_SHARPE_REVIEW_DATA_DENIAL=" + deterministic_json(dict(
            math_id=payload.independent_calculation["math_id"], **failures[-1])))
    record_body = json.loads(canonical)["record_body"]
    record_body["limitations"] = ["SOFTWARE_CONFORMANCE_ONLY"]
    with pytest.raises(ComputationControlPlaneError, match="LP03_SHARPE_REVIEW_SIGNED_LIMITATIONS") as caught:
        replace(payload, record_body=record_body)
    failures.append(dict(case="limit substitution", diagnostic=str(caught.value)))
    print("LP03_SHARPE_REVIEW_DATA_DENIAL=" + deterministic_json(dict(
        math_id=payload.independent_calculation["math_id"], **failures[-1])))
    print("LP03_SHARPE_REVIEW_DATA_DENIALS=" + deterministic_json(dict(math_id=payload.independent_calculation["math_id"], denials=failures)))


def _assert_lp03_spa_review_payload_contract(payload):
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    canonical=deterministic_json(payload)
    assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical))==payload
    def first(value):return value["lane_calculations"][0]
    def proof(value):return first(value)["proof"]
    def summary(value):return proof(value)["summary"]
    def malformed_input(value,**changes):
        inputs=json.loads(summary(value)["typed_input_json"]);inputs.update(changes)
        summary(value)["typed_input_json"]=deterministic_json(inputs)
    def source_change(value):
        source=first(value)["original_source_payload"]
        source["source_slices"][2]["reconstructed_canonical_events"][0]["values"]["formula_policies['MATH-16'].seed"]=1
    def environment_change(value):
        env=json.loads(summary(value)["environment_json"]);env["build"]="different"
        summary(value)["environment_json"]=deterministic_json(env)
    def underreport_registration(value):
        value["registration_numerical_consumption"]["serialized_bytes"]-=1
        value["review_numerical_limits"]["max_serialized_bytes"]+=1
    def original(value, index=0):
        return first(value)["original_source_payload"]["source_slices"][index]["reconstructed_canonical_events"][0]
    def ledger(value):return original(value)["values"]["material_trial_ledger"]
    def changed_raw(value, name, replacement):
        raw=json.loads(summary(value)["original_raw_json"]);raw[name]=replacement
        summary(value)["original_raw_json"]=deterministic_json(raw)
    cases=(
        ("raw_variances",lambda value:changed_raw(value,"long_run_variances",[0.0])),
        ("raw_valid_mask",lambda value:changed_raw(value,"consistent_valid_columns",[False])),
        ("input_variant",lambda value:malformed_input(value,recenter_variant="OTHER")),
        ("original_variant",lambda value:original(value,6)["values"].update({"formula_policies['MATH-16'].recenter_variant":"OTHER"})),
        ("log_omission",lambda value:proof(value)["log_certificates"].pop()),
        ("log_trailing",lambda value:proof(value)["log_certificates"].append(dict(proof(value)["log_certificates"][-1]))),
        ("log_order",lambda value:proof(value)["log_certificates"].reverse()),
        ("log_position",lambda value:proof(value)["log_certificates"][0].update(position=0)),
        ("log_input",lambda value:proof(value)["log_certificates"][0].update(input_bits="4010000000000000")),
        ("log_terms",lambda value:proof(value)["log_certificates"][0].update(terms=63)),
        ("log_terms_boolean",lambda value:proof(value)["log_certificates"][0].update(terms=True)),
        ("log_candidate",lambda value:proof(value)["log_certificates"][0].update(candidate="3ff0000000000000")),
        ("cell_trailing",lambda value:proof(value)["cell_candidates"].append("0000000000000000")),
        ("cell_dictionary",lambda value:proof(value)["cell_candidates"].__setitem__(0,dict(candidate="3fe0000000000001"))),
        ("cell_nan",lambda value:proof(value)["cell_candidates"].__setitem__(0,"7ff8000000000000")),
        ("cell_oversized_bits",lambda value:proof(value)["cell_candidates"].__setitem__(0,"f"*4097)),
        ("ledger_omission",lambda value:original(value)["values"].pop("material_trial_ledger")),
        ("ledger_candidate_omission",lambda value:ledger(value)["rows"].pop()),
        ("ledger_time_omission",lambda value:ledger(value)["rows"][0]["observations"].pop()),
        ("ledger_candidate_order",lambda value:ledger(value)["rows"][0].update(original_candidate_index=1)),
        ("ledger_time_order",lambda value:ledger(value)["ordered_time_ids"].reverse()),
        ("ledger_cell_bits",lambda value:ledger(value)["rows"][0]["observations"][0].update(differential_binary64_bits="0000000000000000")),
        ("ledger_duplicate_receipt",lambda value:ledger(value)["rows"][0]["observations"][1].update(synthetic_input_receipt_id=ledger(value)["rows"][0]["observations"][0]["synthetic_input_receipt_id"])),
        ("ledger_wrong_benchmark",lambda value:ledger(value).update(benchmark_id="LP03::foreign")),
        ("ledger_incomplete_end",lambda value:ledger(value)["end_record"].update(cell_count=2)),
        ("ledger_late_visibility",lambda value:ledger(value).update(publication_visibility_wall_ns=first(value)["original_source_payload"]["consumer_cutoff_wall_ns"]+1)),
        ("bound_candidate_count",lambda value:value["registration_bound_proof"].update(candidates=2)),
        ("bound_alpha",lambda value:value["registration_bound_proof"].update(alpha_bits="3fd0000000000000")),
        ("wrong_branch",lambda value:proof(value).update(branch="ALL_ZERO_NO_RNG_CONSTRUCTION")),
        ("wrong_oriented_matrix",lambda value:proof(value)["oriented_matrix_bits"][0].__setitem__(0,"0000000000000000")),
        ("exceedance_count",lambda value:summary(value).update(exceedances=1)),
        ("reject_flag",lambda value:summary(value).update(reject_flag=0)),
        ("statistic_bits",lambda value:summary(value).update(statistic_bits="3fe6a09e667f3bce")),
        ("p_value_bits",lambda value:summary(value).update(p_value_bits="3ff0000000000000")),
        ("raw_statistic",lambda value:changed_raw(value,"statistic",0.0)),
        ("raw_p_value",lambda value:changed_raw(value,"p_value",1.0)),
        ("raw_reject",lambda value:changed_raw(value,"reject",False)),
        ("raw_means",lambda value:changed_raw(value,"candidate_means",[0.0,0.5])),
        ("raw_simulations",lambda value:changed_raw(value,"simulated_statistics",[0.5])),
        ("raw_recenter_variant",lambda value:changed_raw(value,"recenter_variant","OTHER")),
        ("extra_method_field",lambda value:value.update(preregistered_expected="0.0")),
        ("unit",lambda value:first(value).update(unit="probability")),
        ("basis",lambda value:first(value).update(basis="lower_upper_probability_interval")),
        ("source_omission",lambda value:first(value)["source_record_refs"].pop()),
        ("source_duplicate",lambda value:first(value)["source_record_refs"].__setitem__(2,first(value)["source_record_refs"][0])),
        ("source_lane_disagreement",lambda value:first(value)["source_record_refs"][2].update(record_id="LP03::foreign")),
        ("original_source_seed",source_change),
        ("source_graph_extra",lambda value:first(value)["original_source_payload"].update(extra=True)),
        ("source_graph_omission",lambda value:first(value)["original_source_payload"]["source_slices"].pop()),
        ("source_graph_wrong_type",lambda value:first(value).update(original_source_payload="{}")),
        ("false_observed_intermediates",lambda value:proof(value).update(intermediate_observation_scope="NATIVE_INTERNAL_STAGES_OBSERVED")),
        ("false_observed_rng",lambda value:proof(value).update(replay_observation_scope="NATIVE_FORMULA_RANDOM_DRAWS")),
        ("false_coverage_claim",lambda value:proof(value).update(statistical_authority="EXACT_COVERAGE_CERTIFIED")),
        ("false_binary_attestation",lambda value:proof(value).update(model_provenance="LOCAL_BINARY_ATTESTED")),
        ("wrong_seed",lambda value:summary(value).update(seed=1)),
        ("boolean_replicates",lambda value:summary(value).update(replicates=True)),
        ("input_boolean_seed",lambda value:malformed_input(value,seed=True)),
        ("input_scalar_alpha",lambda value:malformed_input(value,alpha="0.5")),
        ("input_wide_seed",lambda value:malformed_input(value,seed=2**256)),
        ("wrong_threshold",lambda value:proof(value)["consistency_threshold_bits"].__setitem__(0,"0000000000000000")),
        ("environment_lane_disagreement",environment_change),
        ("raw_expectation",lambda value:summary(value).update(preregistered_raw_json="{}")),
        ("projection",lambda value:first(value).update(projected_value_json="{}")),
        ("bound_math",lambda value:value["registration_bound_proof"].update(math_id="MATH-08")),
        ("bound_upper",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="2")),
        ("bound_seed",lambda value:value["registration_bound_proof"].update(seed=1)),
        ("bound_count",lambda value:value["registration_bound_proof"].update(observations=4)),
        ("bound_direction",lambda value:value["registration_bound_proof"].update(result_direction="CONTROL")),
        ("registration_rng_count",lambda value:value["registration_numerical_consumption"].update(random_draws=1)),
        ("review_log_count",lambda value:value["numerical_consumption_before_final_encoding"].update(log_series_terms=1)),
        ("review_sqrt_count",lambda value:value["numerical_consumption_before_final_encoding"].update(square_roots=1)),
        ("review_retained_count",lambda value:value["numerical_consumption_before_final_encoding"].update(retained_decimal_inputs=0)),
        ("rng_underreported",lambda value:value["numerical_consumption_before_final_encoding"].update(random_draws=5)),
        ("budget_reset",lambda value:value["review_numerical_limits"].update(max_serialized_bytes=65536)),
        ("review_bytes_underreported",lambda value:value["numerical_consumption_before_final_encoding"].update(serialized_bytes=1)),
        ("registration_bytes_underreported",underreport_registration),
        ("cell_omission",lambda value:proof(value)["cell_candidates"].pop()),
        ("cell_order",lambda value:proof(value)["cell_candidates"].reverse()),
        ("draw_omission",lambda value:proof(value)["draws"].pop()),
        ("draw_trailing",lambda value:proof(value)["draws"].append(dict(proof(value)["draws"][-1]))),
        ("draw_order",lambda value:proof(value)["draws"].reverse()),
        ("draw_method",lambda value:proof(value)["draws"][0].update(method="RANDOM_U53")),
        ("draw_width",lambda value:proof(value)["draws"][0].update(width=1)),
        ("draw_boolean_value",lambda value:proof(value)["draws"][0].update(value=True)),
        ("first_rejected_return_changed",lambda value:proof(value)["draws"][0].update(value=2)),
        ("uniform_value_same_disposition",lambda value:proof(value)["draws"][2].update(value=proof(value)["draws"][2]["value"]+1)),
        ("draw_population",lambda value:proof(value)["draws"][0].update(comparison="4")),
        ("draw_threshold",lambda value:proof(value)["draws"][2].update(comparison="3ff0000000000000")),
        ("draw_position",lambda value:proof(value)["draws"][0].update(position=1)),
        ("draw_disposition",lambda value:proof(value)["draws"][0].update(disposition="SELECTED")),
        ("index_bool",lambda value:proof(value)["indices"][0].__setitem__(0,True)),
        ("ratio_noncanonical",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="01")),
        ("ratio_zero_denominator",lambda value:value["registration_bound_proof"]["fixed_upper"].update(denominator="0")),
        ("ratio_allocation",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="9"*4097)),
    )
    denials=[]
    for name,mutate in cases:
        bad=json.loads(canonical);mutate(bad["independent_calculation"])
        with pytest.raises(ComputationControlPlaneError) as caught:m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case=name,diagnostic=str(caught.value)))
    # Every compact arithmetic position must be reconstructed and certified.
    for index, candidate in enumerate(payload.independent_calculation["lane_calculations"][0]["proof"]["cell_candidates"]):
        bad=json.loads(canonical)
        proof(bad["independent_calculation"])["cell_candidates"][index]="3ff0000000000000" if candidate=="0000000000000000" else "0000000000000000"
        with pytest.raises(ComputationControlPlaneError) as caught:m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case="compact_cell_position_"+str(index),diagnostic=str(caught.value)))
    # The clock variants remain valid within each original source graph.
    # Only their cross-lane identity is rejected. Fixed-width +1ns preserves
    # every original serialization charge; no allowance is recomputed.
    for clock_field in ("consumer_decision_wall_ns", "consumer_cutoff_wall_ns"):
        bad=json.loads(canonical)
        calculation=bad["independent_calculation"]
        if clock_field=="consumer_cutoff_wall_ns":
            for lane in calculation["lane_calculations"]:
                lane["original_source_payload"]["consumer_decision_wall_ns"]+=1
            assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        graph=first(calculation)["original_source_payload"]
        graph[clock_field]+=1
        assert len(m._evidence_spa_source_slices_v1(graph))==7
        with pytest.raises(ComputationControlPlaneError, match="LP03_SPA_REVIEW_ORIGINAL_LANE_JOIN") as caught:
            m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case="cross_lane_"+clock_field+"_plus_one_ns_locally_valid",diagnostic=str(caught.value)))
    print("LP03_SPA_REVIEW_PAYLOAD_QUALIFICATION="+deterministic_json(dict(
        scope="SIGNED_REVIEW_DATA_ONLY_NO_AUTHORITY",roundtrip=True,signed_denials=denials)))


def _assert_lp03_reality_check_frame_negatives(lane):
    import json
    import pytest
    from dataclasses import replace
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import _evidence_projection_spine_object_v1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.receipts import _lp03_spine_from_storage_v1
    spine = lane.records.receipt_records[1]
    spine_bytes = deterministic_json(spine).encode("utf-8")
    assert _lp03_spine_from_storage_v1(spine_bytes, expected_record_id=spine.record_id) == spine
    equality_calls, spine_denials = [], []
    class ForeignUnit:
        def __eq__(self, other):
            equality_calls.append(other)
            return True
    with pytest.raises(ComputationControlPlaneError) as caught:replace(spine.typed_payload.record, output_unit=ForeignUnit())
    assert equality_calls == []
    spine_denials.append(dict(case="foreign_unit_equality", diagnostic=str(caught.value)))
    def projection(value):return value["typed_payload"]["record"]
    def projected(value):return projection(value)["projected_value"]
    for name, mutate in (
        ("foreign_float_leaf", lambda value:value.update(foreign_binary64_leaf=1.0)),
        ("wrong_projection_schema", lambda value:projection(value).update(original_raw_schema_ref="MATH-14::OUTPUT")),
        ("scalar_projection", lambda value:projection(value).update(projected_value=0.5)),
        ("missing_member", lambda value:projected(value).pop("reject")),
        ("extra_member", lambda value:projected(value).update(alpha=0.5)),
        ("integer_statistic", lambda value:projected(value).update(statistic=0)),
        ("integer_p_value", lambda value:projected(value).update(p_value=1)),
        ("integer_reject", lambda value:projected(value).update(reject=1)),
        ("empty_candidate_means", lambda value:projected(value).update(candidate_means=[])),
        ("candidate_capacity", lambda value:projected(value).update(candidate_means=[0.0]*3)),
        ("integer_mean", lambda value:projected(value)["candidate_means"].__setitem__(0, 0)),
        ("empty_simulations", lambda value:projected(value).update(simulated_statistics=[])),
        ("simulation_capacity", lambda value:projected(value).update(simulated_statistics=[0.0]*5)),
        ("integer_simulation", lambda value:projected(value)["simulated_statistics"].__setitem__(0, 0)),
        ("wrong_recenter_policy", lambda value:projected(value).update(recenter_policy="OTHER")),
        ("wrong_field_selection", lambda value:projection(value).update(field_selections=[["p_value", "reality_check_receipt"]])),
        ("wrong_implementation", lambda value:projection(value).update(original_implementation_ref="MATH-15::1.1R1")),
    ):
        bad=json.loads(spine_bytes);mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:_evidence_projection_spine_object_v1(deterministic_json(bad).encode("utf-8"))
        spine_denials.append(dict(case=name,diagnostic=str(caught.value)))
    grant=lane.attempt.payload
    frame=dict(protocol=worker.WORKER_PROTOCOL_V1,kind="INPUT_SEGMENT",attempt_ref=grant.grant_ref,
        fence_ref=grant.fence_ref,ordinal=1,payload=dict(segment_ordinal=0,final_segment=True,
            inputs=json.loads(deterministic_json(lane.exchange[0]._resolution.authoritative_values)),
            event=json.loads(deterministic_json(lane.exchange[5])),invocation_contract=json.loads(deterministic_json(lane.exchange[1])),
            original_record_refs=json.loads(deterministic_json(lane.exchange[2]["original_record_refs"]))))
    args=dict(direction="PARENT_TO_WORKER",attempt_ref=grant.grant_ref,fence_ref=grant.fence_ref,ordinal=1,frame_byte_limit=grant.budgets.frame_byte_limit)
    encoded=worker.encode_evidence_worker_frame_v1(frame,**args);decoded=worker.decode_evidence_worker_frame_v1(encoded,**args)
    assert deterministic_json(decoded["payload"]["inputs"])==deterministic_json(frame["payload"]["inputs"])
    def inputs(value):return value["payload"]["inputs"]
    def original(value,index):return value["payload"]["event"]["payload"]["source_slices"][index]["reconstructed_canonical_events"][0]
    def ledger(value):return original(value,0)["values"]["material_trial_ledger"]
    cases=(
        ("boolean_seed",lambda value:inputs(value).update(seed=True)),
        ("float_seed",lambda value:inputs(value).update(seed=0.0)),
        ("wide_seed",lambda value:inputs(value).update(seed=2**256)),
        ("wrong_seed",lambda value:inputs(value).update(seed=1)),
        ("integer_matrix",lambda value:inputs(value).update(loss_differentials=[[0,1],[0,1]])),
        ("short_matrix",lambda value:inputs(value).update(loss_differentials=[[0.25,-0.25]])),
        ("wrong_matrix",lambda value:inputs(value)["loss_differentials"].reverse()),
        ("ragged_matrix",lambda value:inputs(value)["loss_differentials"][0].pop()),
        ("matrix_bound",lambda value:inputs(value)["loss_differentials"][0].__setitem__(0,1.5)),
        ("time_capacity",lambda value:inputs(value).update(loss_differentials=[[0.25]]*5)),
        ("candidate_capacity",lambda value:inputs(value).update(loss_differentials=[[0.25]*3]*2)),
        ("wrong_sign",lambda value:inputs(value).update(sign_convention="CANDIDATE_LOSS_MINUS_BENCHMARK_LOSS_NEGATED_TO_POSITIVE_IS_BETTER")),
        ("zero_replicates",lambda value:inputs(value).update(replicates=0)),
        ("wrong_replicates",lambda value:inputs(value).update(replicates=2)),
        ("replicate_capacity",lambda value:inputs(value).update(replicates=5)),
        ("integer_block",lambda value:inputs(value).update(expected_block_length=2)),
        ("wrong_block",lambda value:inputs(value).update(expected_block_length=1.0)),
        ("block_range",lambda value:inputs(value).update(expected_block_length=3.0)),
        ("zero_alpha",lambda value:inputs(value).update(alpha=0.0)),
        ("wrong_alpha",lambda value:inputs(value).update(alpha=0.75)),
        ("source_order",lambda value:value["payload"]["event"]["payload"]["source_slices"].reverse()),
        ("omitted_policy_source",lambda value:value["payload"]["event"]["payload"]["source_slices"].pop()),
        ("policy_revision",lambda value:original(value,1).update(revision="FOREIGN")),
        ("policy_owner",lambda value:original(value,2).update(owner_id="CompleteMaterialTrialLedgerOwnerV1")),
        ("policy_context",lambda value:original(value,2).update(context_id="LP03::foreign")),
        ("omitted_source_ref",lambda value:value["payload"]["original_record_refs"].pop(0)),
        ("wrong_implementation",lambda value:value["payload"]["invocation_contract"].update(raw_implementation_id="MATH-15::1.1R1")),
        ("foreign_float",lambda value:value["payload"]["event"].update(local_ordinal=0.0)),
        ("ledger_omitted",lambda value:original(value,0)["values"].pop("material_trial_ledger")),
        ("ledger_candidate_omitted",lambda value:ledger(value)["rows"].pop()),
        ("ledger_candidate_order",lambda value:ledger(value)["rows"].reverse()),
        ("ledger_time_order",lambda value:ledger(value)["ordered_time_ids"].reverse()),
        ("ledger_cell_omitted",lambda value:ledger(value)["rows"][0]["observations"].pop()),
        ("ledger_cell_bits",lambda value:ledger(value)["rows"][0]["observations"][0].update(differential_binary64_bits="0000000000000000")),
        ("ledger_receipt_duplicate",lambda value:ledger(value)["rows"][1]["observations"][0].update(synthetic_input_receipt_id=ledger(value)["rows"][0]["observations"][0]["synthetic_input_receipt_id"])),
        ("ledger_benchmark_end_join",lambda value:ledger(value).update(benchmark_id="LP03-BENCHMARK::foreign")),
        ("ledger_end_count",lambda value:ledger(value)["end_record"].update(cell_count=3)),
        ("ledger_visibility_after_cutoff",lambda value:ledger(value).update(publication_visibility_wall_ns=value["payload"]["event"]["payload"]["consumer_cutoff_wall_ns"]+1)),
    )
    denials=[]
    for name,mutate in cases:
        bad=json.loads(deterministic_json(frame));mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:worker.encode_evidence_worker_frame_v1(bad,**args)
        denials.append(dict(case=name,diagnostic=str(caught.value)))
    print("LP03_REALITY_WORKER_DATA_QUALIFICATION="+deterministic_json(dict(
        scope="CLOSED_ORIGINAL_COMPLETE_FAMILY_AND_REALITY_CHECK_POLICY_WORKER_DATA_ONLY",roundtrip=True,
        original_typed_input_json=deterministic_json(frame["payload"]["inputs"]),frame_denials=denials,
        stored_spine_roundtrip=True,stored_spine_denials=spine_denials)))


def _assert_lp03_reality_check_review_payload_contract(payload):
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    canonical=deterministic_json(payload)
    assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical))==payload
    def first(value):return value["lane_calculations"][0]
    def proof(value):return first(value)["proof"]
    def summary(value):return proof(value)["summary"]
    def malformed_input(value,**changes):
        inputs=json.loads(summary(value)["typed_input_json"]);inputs.update(changes)
        summary(value)["typed_input_json"]=deterministic_json(inputs)
    def source_change(value):
        source=first(value)["original_source_payload"]
        source["source_slices"][2]["reconstructed_canonical_events"][0]["values"]["formula_policies['MATH-15'].seed"]=1
    def environment_change(value):
        env=json.loads(summary(value)["environment_json"]);env["build"]="different"
        summary(value)["environment_json"]=deterministic_json(env)
    def underreport_registration(value):
        value["registration_numerical_consumption"]["serialized_bytes"]-=1
        value["review_numerical_limits"]["max_serialized_bytes"]+=1
    def original(value, index=0):
        return first(value)["original_source_payload"]["source_slices"][index]["reconstructed_canonical_events"][0]
    def ledger(value):return original(value)["values"]["material_trial_ledger"]
    def changed_raw(value, name, replacement):
        raw=json.loads(summary(value)["original_raw_json"]);raw[name]=replacement
        summary(value)["original_raw_json"]=deterministic_json(raw)
    def changed_cell(value, operation, **changes):
        next(row for row in proof(value)["cells"] if row["operation"]==operation).update(changes)
    cases=(
        ("ledger_omission",lambda value:original(value)["values"].pop("material_trial_ledger")),
        ("ledger_candidate_omission",lambda value:ledger(value)["rows"].pop()),
        ("ledger_time_omission",lambda value:ledger(value)["rows"][0]["observations"].pop()),
        ("ledger_candidate_order",lambda value:ledger(value)["rows"].reverse()),
        ("ledger_time_order",lambda value:ledger(value)["ordered_time_ids"].reverse()),
        ("ledger_cell_bits",lambda value:ledger(value)["rows"][0]["observations"][0].update(differential_binary64_bits="0000000000000000")),
        ("ledger_duplicate_receipt",lambda value:ledger(value)["rows"][1]["observations"][0].update(synthetic_input_receipt_id=ledger(value)["rows"][0]["observations"][0]["synthetic_input_receipt_id"])),
        ("ledger_wrong_benchmark",lambda value:ledger(value).update(benchmark_id="LP03::foreign")),
        ("ledger_incomplete_end",lambda value:ledger(value)["end_record"].update(cell_count=3)),
        ("ledger_late_visibility",lambda value:ledger(value).update(publication_visibility_wall_ns=first(value)["original_source_payload"]["consumer_cutoff_wall_ns"]+1)),
        ("bound_candidate_count",lambda value:value["registration_bound_proof"].update(candidates=1)),
        ("bound_alpha",lambda value:value["registration_bound_proof"].update(alpha_bits="3fd0000000000000")),
        ("wrong_branch",lambda value:proof(value).update(branch="ALL_ZERO_NO_RNG_CONSTRUCTION")),
        ("wrong_oriented_matrix",lambda value:proof(value)["oriented_matrix_bits"][0].reverse()),
        ("observed_column",lambda value:proof(value).update(observed_selected_column=1)),
        ("replicate_column",lambda value:proof(value)["replicate_selected_columns"].__setitem__(0,0)),
        ("replicate_column_boolean",lambda value:proof(value)["replicate_selected_columns"].__setitem__(0,False)),
        ("exceedance_count",lambda value:summary(value).update(exceedances=1)),
        ("reject_flag",lambda value:summary(value).update(reject_flag=0)),
        ("statistic_bits",lambda value:summary(value).update(statistic_bits="3fe6a09e667f3bce")),
        ("p_value_bits",lambda value:summary(value).update(p_value_bits="3ff0000000000000")),
        ("sqrt_midpoint",lambda value:changed_cell(value,"SQRT_N",candidate="3ff6a09e667f3bce")),
        ("center_operation",lambda value:changed_cell(value,"REPLICATE_0_CENTER_0",kind="ADD")),
        ("plus_one_denominator",lambda value:changed_cell(value,"PLUS_ONE_P_VALUE",operands_json='["3ff0000000000000","3ff0000000000000"]')),
        ("raw_statistic",lambda value:changed_raw(value,"statistic",0.0)),
        ("raw_p_value",lambda value:changed_raw(value,"p_value",1.0)),
        ("raw_reject",lambda value:changed_raw(value,"reject",False)),
        ("raw_means",lambda value:changed_raw(value,"candidate_means",[0.0,0.5])),
        ("raw_simulations",lambda value:changed_raw(value,"simulated_statistics",[0.5])),
        ("raw_recenter_policy",lambda value:changed_raw(value,"recenter_policy","OTHER")),
        ("extra_method_field",lambda value:value.update(preregistered_expected="0.0")),
        ("unit",lambda value:first(value).update(unit="probability")),
        ("basis",lambda value:first(value).update(basis="lower_upper_probability_interval")),
        ("source_omission",lambda value:first(value)["source_record_refs"].pop()),
        ("source_duplicate",lambda value:first(value)["source_record_refs"].__setitem__(2,first(value)["source_record_refs"][0])),
        ("source_lane_disagreement",lambda value:first(value)["source_record_refs"][2].update(record_id="LP03::foreign")),
        ("original_source_seed",source_change),
        ("source_graph_extra",lambda value:first(value)["original_source_payload"].update(extra=True)),
        ("source_graph_omission",lambda value:first(value)["original_source_payload"]["source_slices"].pop()),
        ("source_graph_wrong_type",lambda value:first(value).update(original_source_payload="{}")),
        ("false_observed_intermediates",lambda value:proof(value).update(intermediate_observation_scope="NATIVE_INTERNAL_STAGES_OBSERVED")),
        ("false_observed_rng",lambda value:proof(value).update(replay_observation_scope="NATIVE_FORMULA_RANDOM_DRAWS")),
        ("false_coverage_claim",lambda value:proof(value).update(statistical_authority="EXACT_COVERAGE_CERTIFIED")),
        ("false_binary_attestation",lambda value:proof(value).update(model_provenance="LOCAL_BINARY_ATTESTED")),
        ("wrong_seed",lambda value:summary(value).update(seed=1)),
        ("boolean_replicates",lambda value:summary(value).update(replicates=True)),
        ("input_boolean_seed",lambda value:malformed_input(value,seed=True)),
        ("input_scalar_alpha",lambda value:malformed_input(value,alpha="0.5")),
        ("input_wide_seed",lambda value:malformed_input(value,seed=2**256)),
        ("wrong_threshold",lambda value:summary(value).update(threshold_bits="3ff0000000000000")),
        ("environment_lane_disagreement",environment_change),
        ("raw_expectation",lambda value:summary(value).update(preregistered_raw_json="{}")),
        ("projection",lambda value:first(value).update(projected_value_json="{}")),
        ("bound_math",lambda value:value["registration_bound_proof"].update(math_id="MATH-08")),
        ("bound_upper",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="2")),
        ("bound_seed",lambda value:value["registration_bound_proof"].update(seed=1)),
        ("bound_count",lambda value:value["registration_bound_proof"].update(observations=3)),
        ("bound_direction",lambda value:value["registration_bound_proof"].update(result_direction="CONTROL")),
        ("registration_rng_count",lambda value:value["registration_numerical_consumption"].update(random_draws=1)),
        ("review_log_count",lambda value:value["numerical_consumption_before_final_encoding"].update(log_series_terms=1)),
        ("review_sqrt_count",lambda value:value["numerical_consumption_before_final_encoding"].update(square_roots=1)),
        ("review_retained_count",lambda value:value["numerical_consumption_before_final_encoding"].update(retained_decimal_inputs=0)),
        ("rng_underreported",lambda value:value["numerical_consumption_before_final_encoding"].update(random_draws=5)),
        ("budget_reset",lambda value:value["review_numerical_limits"].update(max_serialized_bytes=65536)),
        ("review_bytes_underreported",lambda value:value["numerical_consumption_before_final_encoding"].update(serialized_bytes=1)),
        ("registration_bytes_underreported",underreport_registration),
        ("cell_omission",lambda value:proof(value)["cells"].pop()),
        ("cell_order",lambda value:proof(value)["cells"].reverse()),
        ("cell_operation",lambda value:proof(value)["cells"][0].update(operation="ALPHA")),
        ("cell_kind",lambda value:proof(value)["cells"][0].update(kind="ADD")),
        ("cell_operands",lambda value:proof(value)["cells"][0].update(operands_json='["0000000000000000","4000000000000000"]')),
        ("cell_candidate",lambda value:proof(value)["cells"][0].update(candidate="3fe0000000000001")),
        ("cell_nan",lambda value:proof(value)["cells"][0].update(candidate="7ff8000000000000")),
        ("cell_oversized_bits",lambda value:proof(value)["cells"][0].update(candidate="f"*4097)),
        ("cell_extra_field",lambda value:proof(value)["cells"][0].update(observed=True)),
        ("draw_omission",lambda value:proof(value)["draws"].pop()),
        ("draw_trailing",lambda value:proof(value)["draws"].append(dict(proof(value)["draws"][-1]))),
        ("draw_order",lambda value:proof(value)["draws"].reverse()),
        ("draw_method",lambda value:proof(value)["draws"][0].update(method="RANDOM_U53")),
        ("draw_width",lambda value:proof(value)["draws"][0].update(width=1)),
        ("draw_boolean_value",lambda value:proof(value)["draws"][0].update(value=True)),
        ("rejected_value_still_rejected",lambda value:proof(value)["draws"][0].update(value=2)),
        ("uniform_value_same_disposition",lambda value:proof(value)["draws"][2].update(value=proof(value)["draws"][2]["value"]+1)),
        ("draw_population",lambda value:proof(value)["draws"][0].update(comparison="3")),
        ("draw_threshold",lambda value:proof(value)["draws"][2].update(comparison="3ff0000000000000")),
        ("draw_position",lambda value:proof(value)["draws"][0].update(position=1)),
        ("draw_disposition",lambda value:proof(value)["draws"][0].update(disposition="SELECTED")),
        ("index_bool",lambda value:proof(value)["indices"][0].__setitem__(0,True)),
        ("ratio_noncanonical",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="01")),
        ("ratio_zero_denominator",lambda value:value["registration_bound_proof"]["fixed_upper"].update(denominator="0")),
        ("ratio_allocation",lambda value:value["registration_bound_proof"]["fixed_upper"].update(numerator="9"*4097)),
    )
    denials=[]
    for name,mutate in cases:
        bad=json.loads(canonical);mutate(bad["independent_calculation"])
        with pytest.raises(ComputationControlPlaneError) as caught:m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case=name,diagnostic=str(caught.value)))
    # The clock variants remain valid within each original source graph.
    # Only their cross-lane identity is rejected. Fixed-width +1ns preserves
    # every original serialization charge; no allowance is recomputed.
    for clock_field in ("consumer_decision_wall_ns", "consumer_cutoff_wall_ns"):
        bad=json.loads(canonical)
        calculation=bad["independent_calculation"]
        if clock_field=="consumer_cutoff_wall_ns":
            for lane in calculation["lane_calculations"]:
                lane["original_source_payload"]["consumer_decision_wall_ns"]+=1
            assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        graph=first(calculation)["original_source_payload"]
        graph[clock_field]+=1
        assert len(m._evidence_reality_check_source_slices_v1(graph))==6
        with pytest.raises(ComputationControlPlaneError, match="LP03_REALITY_REVIEW_ORIGINAL_LANE_JOIN") as caught:
            m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case="cross_lane_"+clock_field+"_plus_one_ns_locally_valid",diagnostic=str(caught.value)))
    print("LP03_REALITY_REVIEW_PAYLOAD_QUALIFICATION="+deterministic_json(dict(
        scope="SIGNED_REVIEW_DATA_ONLY_NO_AUTHORITY",roundtrip=True,signed_denials=denials)))


def _assert_lp03_bootstrap_frame_negatives(lane):
    import json
    import pytest
    from dataclasses import replace
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import _evidence_projection_spine_object_v1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.receipts import _lp03_spine_from_storage_v1
    spine = lane.records.receipt_records[1]
    spine_bytes = deterministic_json(spine).encode("utf-8")
    assert _lp03_spine_from_storage_v1(spine_bytes, expected_record_id=spine.record_id) == spine
    equality_calls, spine_denials = [], []
    class ForeignUnit:
        def __eq__(self, other):
            equality_calls.append(other)
            return True
    with pytest.raises(ComputationControlPlaneError) as caught:replace(spine.typed_payload.record, output_unit=ForeignUnit())
    assert equality_calls == []
    spine_denials.append(dict(case="foreign_unit_equality", diagnostic=str(caught.value)))
    def projection(value):return value["typed_payload"]["record"]
    def projected(value):return projection(value)["projected_value"]
    for name, mutate in (
        ("foreign_float_leaf", lambda value:value.update(foreign_binary64_leaf=1.0)),
        ("wrong_projection_schema", lambda value:projection(value).update(original_raw_schema_ref="MATH-11::OUTPUT")),
        ("scalar_projection", lambda value:projection(value).update(projected_value=0.5)),
        ("missing_member", lambda value:projected(value).pop("seed")),
        ("extra_member", lambda value:projected(value).update(confidence=0.5)),
        ("integer_mean", lambda value:projected(value).update(sample_mean=0)),
        ("boolean_seed", lambda value:projected(value).update(seed=True)),
        ("wide_seed", lambda value:projected(value).update(seed=2**256)),
        ("boolean_replicates", lambda value:projected(value).update(replicates=True)),
        ("wrong_distribution_count", lambda value:projected(value)["bootstrap_distribution"].pop()),
        ("integer_distribution", lambda value:projected(value)["bootstrap_distribution"].__setitem__(0, 0)),
        ("reversed_endpoints", lambda value:projected(value).update(lower=0.9, upper=0.1)),
        ("wrong_method", lambda value:projected(value).update(interval_method="OTHER")),
        ("wrong_field_selection", lambda value:projection(value).update(field_selections=[["upper", "bootstrap_distribution_and_interval"]])),
        ("wrong_implementation", lambda value:projection(value).update(original_implementation_ref="MATH-14::1.1R1")),
    ):
        bad=json.loads(spine_bytes);mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:_evidence_projection_spine_object_v1(deterministic_json(bad).encode("utf-8"))
        spine_denials.append(dict(case=name,diagnostic=str(caught.value)))
    grant=lane.attempt.payload
    frame=dict(protocol=worker.WORKER_PROTOCOL_V1,kind="INPUT_SEGMENT",attempt_ref=grant.grant_ref,
        fence_ref=grant.fence_ref,ordinal=1,payload=dict(segment_ordinal=0,final_segment=True,
            inputs=json.loads(deterministic_json(lane.exchange[0]._resolution.authoritative_values)),
            event=json.loads(deterministic_json(lane.exchange[5])),invocation_contract=json.loads(deterministic_json(lane.exchange[1])),
            original_record_refs=json.loads(deterministic_json(lane.exchange[2]["original_record_refs"]))))
    args=dict(direction="PARENT_TO_WORKER",attempt_ref=grant.grant_ref,fence_ref=grant.fence_ref,ordinal=1,frame_byte_limit=grant.budgets.frame_byte_limit)
    encoded=worker.encode_evidence_worker_frame_v1(frame,**args);decoded=worker.decode_evidence_worker_frame_v1(encoded,**args)
    assert deterministic_json(decoded["payload"]["inputs"])==deterministic_json(frame["payload"]["inputs"])
    def inputs(value):return value["payload"]["inputs"]
    def original(value,index):return value["payload"]["event"]["payload"]["source_slices"][index]["reconstructed_canonical_events"][0]
    cases=(
        ("boolean_seed",lambda value:inputs(value).update(seed=True)),
        ("float_seed",lambda value:inputs(value).update(seed=0.0)),
        ("wide_seed",lambda value:inputs(value).update(seed=2**256)),
        ("wrong_seed",lambda value:inputs(value).update(seed=1)),
        ("integer_series",lambda value:inputs(value).update(series=[0,1])),
        ("short_series",lambda value:inputs(value).update(series=[0.25])),
        ("wrong_series",lambda value:inputs(value).update(series=[0.75,0.25])),
        ("proof_series_bound",lambda value:inputs(value).update(series=[0.25,1.5])),
        ("series_capacity",lambda value:inputs(value).update(series=[0.25]*9)),
        ("zero_replicates",lambda value:inputs(value).update(replicates=0)),
        ("wrong_replicates",lambda value:inputs(value).update(replicates=3)),
        ("replicate_capacity",lambda value:inputs(value).update(replicates=5)),
        ("integer_block",lambda value:inputs(value).update(expected_block_length=2)),
        ("wrong_block",lambda value:inputs(value).update(expected_block_length=1.0)),
        ("block_range",lambda value:inputs(value).update(expected_block_length=3.0)),
        ("zero_confidence",lambda value:inputs(value).update(confidence=0.0)),
        ("wrong_confidence",lambda value:inputs(value).update(confidence=0.75)),
        ("method",lambda value:inputs(value).update(interval_method="OTHER")),
        ("source_order",lambda value:value["payload"]["event"]["payload"]["source_slices"].reverse()),
        ("omitted_policy_source",lambda value:value["payload"]["event"]["payload"]["source_slices"].pop()),
        ("policy_revision",lambda value:original(value,1).update(revision=2)),
        ("policy_owner",lambda value:original(value,2).update(owner_id="LockedTimeSeriesEvidenceDatasetOwnerV1")),
        ("policy_context",lambda value:original(value,2).update(context_id="LP03::foreign")),
        ("omitted_source_ref",lambda value:value["payload"]["original_record_refs"].pop(0)),
        ("wrong_implementation",lambda value:value["payload"]["invocation_contract"].update(raw_implementation_id="MATH-14::1.1R1")),
        ("foreign_float",lambda value:value["payload"]["event"].update(local_ordinal=0.0)),
    )
    denials=[]
    for name,mutate in cases:
        bad=json.loads(deterministic_json(frame));mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:worker.encode_evidence_worker_frame_v1(bad,**args)
        denials.append(dict(case=name,diagnostic=str(caught.value)))
    print("LP03_BOOTSTRAP_WORKER_DATA_QUALIFICATION="+deterministic_json(dict(
        scope="CLOSED_ORIGINAL_SERIES_AND_BOOTSTRAP_POLICY_WORKER_DATA_ONLY",roundtrip=True,
        original_typed_input_json=deterministic_json(frame["payload"]["inputs"]),frame_denials=denials,
        stored_spine_roundtrip=True,stored_spine_denials=spine_denials)))


