def _assert_lp03_wilson_frame_negatives(lane):
    import json
    import pytest
    from dataclasses import replace
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import _evidence_projection_spine_object_v1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.receipts import _lp03_spine_from_storage_v1
    spine = lane.records.receipt_records[1]
    spine_bytes = deterministic_json(spine).encode("utf-8")
    assert _lp03_spine_from_storage_v1(spine_bytes, expected_record_id=spine.record_id) == spine
    equality_calls, spine_denials = [], []
    class ForeignUnit:
        def __eq__(self, other):
            equality_calls.append(other)
            return True
    with pytest.raises(ComputationControlPlaneError) as caught:
        replace(spine.typed_payload.record, output_unit=ForeignUnit())
    assert equality_calls == []
    spine_denials.append(dict(case="foreign_unit_equality", diagnostic=str(caught.value)))
    def projection(value): return value["typed_payload"]["record"]
    for name, mutate in (
        ("foreign_float_leaf", lambda value: value.update(foreign_binary64_leaf=1.0)),
        ("wrong_projection_schema", lambda value: projection(value).update(original_raw_schema_ref="MATH-10::OUTPUT")),
        ("scalar_projection", lambda value: projection(value).update(projected_value=0.5)),
        ("short_projection", lambda value: projection(value)["projected_value"].pop()),
        ("extra_endpoint", lambda value: projection(value)["projected_value"].append(1.0)),
        ("integer_endpoint", lambda value: projection(value)["projected_value"].__setitem__(0, 0)),
        ("boolean_endpoint", lambda value: projection(value)["projected_value"].__setitem__(0, False)),
        ("reversed_endpoints", lambda value: projection(value)["projected_value"].reverse()),
        ("negative_endpoint", lambda value: projection(value)["projected_value"].__setitem__(0, -0.5)),
        ("above_unit_endpoint", lambda value: projection(value)["projected_value"].__setitem__(1, 1.5)),
        ("wrong_field_selection", lambda value: projection(value).update(field_selections=[["upper", "interval"]])),
    ):
        bad = json.loads(spine_bytes); mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:
            _evidence_projection_spine_object_v1(deterministic_json(bad).encode("utf-8"))
        spine_denials.append(dict(case=name, diagnostic=str(caught.value)))
    grant = lane.attempt.payload
    frame = dict(protocol=worker.WORKER_PROTOCOL_V1, kind="INPUT_SEGMENT", attempt_ref=grant.grant_ref,
        fence_ref=grant.fence_ref, ordinal=1, payload=dict(segment_ordinal=0, final_segment=True,
            inputs=json.loads(deterministic_json(lane.exchange[0]._resolution.authoritative_values)),
            event=json.loads(deterministic_json(lane.exchange[5])),
            invocation_contract=json.loads(deterministic_json(lane.exchange[1])),
            original_record_refs=json.loads(deterministic_json(lane.exchange[2]["original_record_refs"]))))
    args = dict(direction="PARENT_TO_WORKER", attempt_ref=grant.grant_ref, fence_ref=grant.fence_ref,
                ordinal=1, frame_byte_limit=grant.budgets.frame_byte_limit)
    raw = worker.encode_evidence_worker_frame_v1(frame, **args)
    decoded = worker.decode_evidence_worker_frame_v1(raw, **args)
    assert deterministic_json(decoded["payload"]["inputs"]) == deterministic_json(frame["payload"]["inputs"])
    def inputs(value): return value["payload"]["inputs"]
    def original(value, index): return value["payload"]["event"]["payload"]["source_slices"][index]["reconstructed_canonical_events"][0]
    cases = (
        ("boolean_successes", lambda value: inputs(value).update(successes=True)),
        ("float_successes", lambda value: inputs(value).update(successes=5.0)),
        ("negative_successes", lambda value: inputs(value).update(successes=-1)),
        ("above_trials_successes", lambda value: inputs(value).update(successes=11)),
        ("wrong_successes", lambda value: inputs(value).update(successes=4)),
        ("boolean_trials", lambda value: inputs(value).update(trials=True)),
        ("zero_trials", lambda value: inputs(value).update(trials=0)),
        ("inexact_trial_conversion", lambda value: inputs(value).update(trials=2**53 + 1)),
        ("wrong_trials", lambda value: inputs(value).update(trials=11)),
        ("integer_confidence", lambda value: inputs(value).update(confidence=1)),
        ("zero_confidence", lambda value: inputs(value).update(confidence=0.0)),
        ("unit_confidence", lambda value: inputs(value).update(confidence=1.0)),
        ("wrong_confidence", lambda value: inputs(value).update(confidence=0.75)),
        ("source_order", lambda value: value["payload"]["event"]["payload"]["source_slices"].reverse()),
        ("omitted_policy_source", lambda value: value["payload"]["event"]["payload"]["source_slices"].pop()),
        ("counts_revision", lambda value: original(value, 1).update(revision=2)),
        ("policy_owner", lambda value: original(value, 2).update(owner_id="LockedBernoulliEvidenceDatasetOwnerV1")),
        ("policy_context", lambda value: original(value, 2).update(context_id="LP03::foreign")),
        ("omitted_source_ref", lambda value: value["payload"]["original_record_refs"].pop(0)),
        ("wrong_implementation", lambda value: value["payload"]["invocation_contract"].update(raw_implementation_id="MATH-11::2.0.0")),
        ("foreign_float", lambda value: value["payload"]["event"].update(local_ordinal=0.0)),
    )
    denials = []
    for name, mutate in cases:
        bad = json.loads(deterministic_json(frame)); mutate(bad)
        with pytest.raises(ComputationControlPlaneError) as caught:
            worker.encode_evidence_worker_frame_v1(bad, **args)
        denials.append(dict(case=name, diagnostic=str(caught.value)))
    print("LP03_WILSON_WORKER_DATA_QUALIFICATION=" + deterministic_json(dict(
        scope="CLOSED_ORIGINAL_COUNTS_AND_CONFIDENCE_WORKER_DATA_ONLY", roundtrip=True,
        original_typed_input_json=deterministic_json(frame["payload"]["inputs"]), frame_denials=denials,
        stored_spine_roundtrip=True, stored_spine_denials=spine_denials)))


def _assert_lp03_wilson_review_payload_contract(payload):
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    canonical = deterministic_json(payload)
    assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical)) == payload
    def first(value): return value["lane_calculations"][0]
    def proof(value): return first(value)["proof"]
    def summary(value): return proof(value)["summary"]
    def malformed_input(value, **changes):
        inputs = json.loads(summary(value)["typed_input_json"]); inputs.update(changes)
        summary(value)["typed_input_json"] = deterministic_json(inputs)
    def source_change(value):
        source = json.loads(first(value)["original_source_payload_json"])
        source["source_slices"][0]["reconstructed_canonical_events"][0]["values"]["counts.successes"] = 4
        first(value)["original_source_payload_json"] = deterministic_json(source)
    def underreport_registration(value):
        value["registration_numerical_consumption"]["serialized_bytes"] -= 1
        value["review_numerical_limits"]["max_serialized_bytes"] += 1
    cases = (
        ("extra_method_field", lambda value: value.update(preregistered_expected="0.0")),
        ("unit", lambda value: first(value).update(unit="nats/sample")),
        ("basis", lambda value: first(value).update(basis="absolute_calibration_gap")),
        ("source_omission", lambda value: first(value)["source_record_refs"].pop()),
        ("source_duplicate", lambda value: first(value)["source_record_refs"].__setitem__(2, first(value)["source_record_refs"][0])),
        ("source_lane_disagreement", lambda value: first(value)["source_record_refs"][2].update(record_id="LP03::foreign")),
        ("original_source_value", source_change),
        ("false_observed_intermediates", lambda value: proof(value).update(intermediate_observation_scope="NATIVE_INTERNAL_STAGES_OBSERVED")),
        ("false_coverage_claim", lambda value: proof(value).update(statistical_authority="EXACT_COVERAGE_CERTIFIED")),
        ("false_binary_attestation", lambda value: proof(value).update(model_provenance="LOCAL_BINARY_ATTESTED")),
        ("wrong_successes", lambda value: summary(value).update(successes=4)),
        ("boolean_trials", lambda value: summary(value).update(trials=True)),
        ("input_boolean_successes", lambda value: malformed_input(value, successes=True)),
        ("input_scalar_confidence", lambda value: malformed_input(value, confidence="0.5")),
        ("input_inexact_trials", lambda value: malformed_input(value, trials=2**53 + 1)),
        ("confidence_bits", lambda value: summary(value).update(confidence_bits="3fe8000000000000")),
        ("raw_expectation", lambda value: summary(value).update(preregistered_raw_json="{}")),
        ("projection", lambda value: first(value).update(projected_value_json="[0.0,1.0]")),
        ("bound_math", lambda value: value["registration_bound_proof"].update(math_id="MATH-08")),
        ("bound_upper", lambda value: value["registration_bound_proof"]["fixed_upper"].update(numerator="2")),
        ("bound_confidence", lambda value: value["registration_bound_proof"]["confidence"].update(numerator="0")),
        ("bound_domain_minimum", lambda value: value["registration_bound_proof"]["rounded_domain_confidence_minimum"].update(numerator="2")),
        ("bound_direction", lambda value: value["registration_bound_proof"].update(result_direction="CONTROL")),
        ("registration_log_count", lambda value: value["registration_numerical_consumption"].update(log_series_terms=1)),
        ("review_log_count", lambda value: value["numerical_consumption_before_final_encoding"].update(log_series_terms=1)),
        ("review_sqrt_count", lambda value: value["numerical_consumption_before_final_encoding"].update(square_roots=0)),
        ("review_retained_count", lambda value: value["numerical_consumption_before_final_encoding"].update(retained_decimal_inputs=0)),
        ("rng", lambda value: value["numerical_consumption_before_final_encoding"].update(random_draws=1)),
        ("budget_reset", lambda value: value["review_numerical_limits"].update(max_serialized_bytes=65536)),
        ("review_bytes_underreported", lambda value: value["numerical_consumption_before_final_encoding"].update(serialized_bytes=1)),
        ("registration_bytes_underreported", underreport_registration),
        ("cell_omission", lambda value: proof(value)["cells"].pop()),
        ("cell_order", lambda value: proof(value)["cells"].reverse()),
        ("cell_operation", lambda value: proof(value)["cells"][0].update(operation="WILSON_PHAT")),
        ("cell_kind", lambda value: proof(value)["cells"][0].update(kind="ADD")),
        ("cell_left_operand", lambda value: proof(value)["cells"][0].update(left="0000000000000000")),
        ("cell_right_operand", lambda value: proof(value)["cells"][0].update(right="3fd0000000000000")),
        ("cell_candidate", lambda value: proof(value)["cells"][0].update(candidate="3fe0000000000001")),
        ("cell_nan", lambda value: proof(value)["cells"][0].update(candidate="7ff8000000000000")),
        ("cell_oversized_bits", lambda value: proof(value)["cells"][0].update(candidate="f" * 4097)),
        ("cell_extra_field", lambda value: proof(value)["cells"][0].update(observed=True)),
        ("coefficient_bits", lambda value: proof(value)["cells"][7].update(right="3ff0000000000000")),
        ("sqrt_cell", lambda value: next(row for row in proof(value)["cells"] if row["kind"] == "SQRT").update(candidate="3ff0000000000000")),
        ("central_log_present", lambda value: proof(value).update(log_enclosure={})),
        ("wrong_branch", lambda value: summary(value).update(branch="TAIL_LE_FIVE")),
        ("boolean_clamp_index", lambda value: summary(value).update(lower_selected_index=True)),
        ("wrong_clamp_index", lambda value: summary(value).update(upper_selected_index=0)),
        ("endpoint_bits", lambda value: summary(value).update(lower_bits="3fd95325bcf1db23")),
        ("ratio_noncanonical", lambda value: value["registration_bound_proof"]["confidence"].update(numerator="01")),
        ("ratio_zero_denominator", lambda value: value["registration_bound_proof"]["confidence"].update(denominator="0")),
        ("ratio_allocation", lambda value: value["registration_bound_proof"]["confidence"].update(numerator="9" * 4097)),
    )
    denials = []
    for name, mutate in cases:
        bad = json.loads(canonical); mutate(bad["independent_calculation"])
        with pytest.raises(ComputationControlPlaneError) as caught:
            m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(bad)
        denials.append(dict(case=name, diagnostic=str(caught.value)))
    print("LP03_WILSON_REVIEW_PAYLOAD_QUALIFICATION=" + deterministic_json(dict(
        scope="SIGNED_REVIEW_DATA_ONLY_NO_AUTHORITY", roundtrip=True, signed_denials=denials)))



