def _assert_lp03_brier_review_payload_contract(payload):
    import json
    import pytest
    from dataclasses import replace
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    canonical = deterministic_json(payload)
    assert m.EvidenceReviewDecisionPayloadV1.from_canonical_mapping(json.loads(canonical)) == payload
    cases = (
        ("extra_method_field", lambda x: x.update(preregistered_expected="0.0625")),
        ("wrong_method", lambda x: x.update(method="EXACT_RATIONAL_MIDPOINT_FROM_ORIGINAL_EVENT")),
        ("wrong_result", lambda x: x.update(result="ACCEPTED")),
        ("reversed_lanes", lambda x: x["lane_calculations"].reverse()),
        ("extra_lane_field", lambda x: x["lane_calculations"][0].update(source_record_ref={})),
        ("wrong_unit", lambda x: x["lane_calculations"][0].update(unit="USD")),
        ("wrong_basis", lambda x: x["lane_calculations"][0].update(basis="PER_TRADE")),
        ("wrong_source_order", lambda x: x["lane_calculations"][0]["source_record_refs"].reverse()),
        ("extra_proof_field", lambda x: x["lane_calculations"][0]["proof"].update(tolerance="0")),
        ("wrong_proof_profile", lambda x: x["lane_calculations"][0]["proof"].update(profile="ROUNDED")),
        ("wrong_row_identity", lambda x: x["lane_calculations"][0]["proof"].update(row_identity="SAMPLE_IDS")),
        ("wrong_row_position", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0].update(row_position=True)),
        ("wrong_outcome", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0].update(outcome_index=0)),
        ("rational_leading_zero", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0]["score"].update(numerator="01")),
        ("rational_zero_denominator", lambda x: x["lane_calculations"][0]["proof"]["summary"]["mean_brier_score"].update(denominator="0")),
        ("non_binary64_rational", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0]["ordered_score_prefix"].update(denominator="3")),
        ("contradictory_prefix", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0].update(
            ordered_score_prefix=dict(numerator="0", denominator="1"))),
        ("contradictory_final_mean", lambda x: (
            x["lane_calculations"][0]["proof"]["summary"].update(mean_brier_score=dict(numerator="1", denominator="8"),
                original_raw_json='{"mean_brier_score":0.125,"per_observation":[0.125,0.0]}',
                preregistered_raw_json='{"mean_brier_score":0.125,"per_observation":[0.125,0.0]}'),
            x["lane_calculations"][0].update(projected_value_json="0.125"))),
        ("wrong_raw_rational", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0]["score"].update(denominator="4")),
        ("foreign_float", lambda x: x["lane_calculations"][0]["proof"]["per_observation"][0]["score"].update(numerator=1.0)),
        ("wrong_observation_count", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(observation_count=1)),
        ("wrong_preregistered_raw", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(preregistered_raw_json="{}")),
        ("noncanonical_typed_json", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(typed_input_json=" {}")),
        ("scalar_probability_rows", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(
            typed_input_json='{"outcome_indices":[1,0],"probability_rows":1}')),
        ("boolean_outcomes", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(
            typed_input_json='{"outcome_indices":true,"probability_rows":[[0.25,0.75],[1.0,-0.0]]}')),
        ("flat_probability_rows", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(
            typed_input_json='{"outcome_indices":[1,0],"probability_rows":[0.25,0.75]}')),
        ("mapping_probability_rows", lambda x: x["lane_calculations"][0]["proof"]["summary"].update(
            typed_input_json='{"outcome_indices":[1,0],"probability_rows":{"row":[0.25,0.75]}}')),
        ("wrong_projection", lambda x: x["lane_calculations"][0].update(projected_value_json="0.125")),
        ("integer_projection", lambda x: x["lane_calculations"][0].update(projected_value_json="0")),
        ("counter_boolean", lambda x: x["numerical_consumption_before_final_encoding"].update(input_values=True)),
        ("extra_counter", lambda x: x["numerical_consumption_before_final_encoding"].update(retries=0)),
        ("foreign_numerical_profile", lambda x: x["numerical_consumption_before_final_encoding"].update(random_draws=1)),
    )
    denied = []
    for name, mutate in cases:
        calculation = json.loads(canonical)["independent_calculation"]
        mutate(calculation)
        expected_reason = ({"contradictory_prefix": "LP03_BRIER_REVIEW_PREFIX_JOIN",
            "contradictory_final_mean": "LP03_BRIER_REVIEW_PREFIX_MEAN_JOIN"}.get(name)
            if name not in ("scalar_probability_rows", "boolean_outcomes", "flat_probability_rows", "mapping_probability_rows")
            else "LP03_BRIER_REVIEW_PROOF_ROSTER")
        with pytest.raises(ComputationControlPlaneError, match=expected_reason):
            replace(payload, independent_calculation=calculation)
        denied.append(name)
    for name, mutation in (
        ("wrong_selected_profile", dict(limitations=("SOFTWARE_CONFORMANCE_ONLY", "SELECTED_MATH_03_CLOSURE_ONLY", "NATIVE_CLOCK_ACCURACY_NOT_QUALIFIED"))),
        ("wrong_observed_projection", dict(observed_metric_refs=("LP03-FOREIGN::projection", payload.record_body["observed_metric_refs"][1]))),
    ):
        with pytest.raises(ComputationControlPlaneError):
            replace(payload, record_body=dict(payload.record_body, **mutation))
        denied.append(name)
    print("LP03_BRIER_REVIEW_PAYLOAD_DENIALS_QUALIFICATION=" + deterministic_json(dict(
        scope="CLOSED_SIGNED_PAYLOAD_DATA_VALIDATION_ONLY", canonical_roundtrip=True, denied_fields=denied)))


def _assert_lp03_brier_final_artifact_denial(calculation, limits):
    import json
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import IndependentEvidenceReviewV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.parameter_policy import _EvidenceNumericalWorkV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    # Fix a new negative-only budget before any work. The already measured
    # review's budget and original work are never changed or reused here.
    canonical = deterministic_json(calculation).encode("utf-8")
    budget = dict(limits, max_serialized_bytes=len(canonical) - 1)
    work = _EvidenceNumericalWorkV1(budget, retained_input_capacity=0)
    for lane in calculation["lane_calculations"]:
        summary = lane["proof"]["summary"]
        IndependentEvidenceReviewV1._bounded_review_brier_v1(summary["typed_input_json"].encode("utf-8"),
            summary["original_raw_json"].encode("utf-8"), summary["preregistered_raw_json"].encode("utf-8"),
            0.0625, work=work)
    assert work.state == "OPEN" and 0 < work.consumed["serialized_bytes"] < budget["max_serialized_bytes"]
    prefix = dict(work.consumed)
    with pytest.raises(ComputationControlPlaneError, match="LP03_PROJECTION_JSON_BYTES"):
        IndependentEvidenceReviewV1._charge_brier_review_artifact_v1(json.loads(canonical), work=work)
    assert work.state == "FAILED" and dict(work.consumed) == prefix
    with pytest.raises(ComputationControlPlaneError, match="LP03_NUMERICAL_WORK_NOT_OPEN"):
        IndependentEvidenceReviewV1._charge_brier_review_artifact_v1({}, work=work)
    assert dict(work.consumed) == prefix
    print("LP03_BRIER_FINAL_ARTIFACT_DENIAL_QUALIFICATION=" + deterministic_json(dict(
        scope="PURE_DATA_SERIALIZATION_BUDGET_DENIAL_ONLY", fixed_limits=budget, whole_artifact_bytes=len(canonical),
        completed_lane_proofs=2, retained_consumption=prefix, retained_state=work.state, failure=work.failure,
        unchanged_work_retry_denied=True)))


def _assert_lp03_brier_frame_and_review_negatives(lane):
    import json
    import pytest
    from collections.abc import Mapping
    from types import MappingProxyType
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.evidence import IndependentEvidenceReviewV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.parameter_policy import _EvidenceNumericalWorkV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    grant = lane.attempt.payload
    event = json.loads(deterministic_json(lane.exchange[5]))
    inputs = json.loads(deterministic_json(lane.exchange[0]._resolution.authoritative_values))
    frame = dict(protocol=worker.WORKER_PROTOCOL_V1, kind="INPUT_SEGMENT", attempt_ref=grant.grant_ref,
        fence_ref=grant.fence_ref, ordinal=1, payload=dict(segment_ordinal=0, final_segment=True,
            inputs=inputs, event=event, invocation_contract=json.loads(deterministic_json(lane.exchange[1])),
            original_record_refs=json.loads(deterministic_json(lane.exchange[2]["original_record_refs"]))))
    args = dict(direction="PARENT_TO_WORKER", attempt_ref=grant.grant_ref, fence_ref=grant.fence_ref,
                ordinal=1, frame_byte_limit=grant.budgets.frame_byte_limit)
    raw = worker.encode_evidence_worker_frame_v1(frame, **args)
    decoded = worker.decode_evidence_worker_frame_v1(raw, **args)
    assert deterministic_json(decoded["payload"]["inputs"]) == deterministic_json(inputs)
    denials = []
    if lane.raw.existing_receipt.specification_id == "MATH-26":
        for name, mutate in (
            ("changed_scale", lambda value: value["payload"]["inputs"]["current_action_values"].__setitem__(0, "1.0")),
            ("changed_cost", lambda value: value["payload"]["inputs"].update(acquisition_cost="0.20")),
            ("source_order", lambda value: value["payload"]["event"]["payload"]["source_slices"].reverse()),
            ("utility_basis", lambda value: value["payload"]["event"]["payload"]["source_slices"][1]["reconstructed_canonical_events"][0]["values"]["private_source_context"].update(utility_basis_ref="LP03::foreign")),
            ("omitted_source", lambda value: value["payload"]["original_record_refs"].pop(0)),
            ("wrong_implementation", lambda value: value["payload"]["invocation_contract"].update(raw_implementation_id="MATH-26::1.1R1")),
        ):
            bad = json.loads(deterministic_json(frame))
            mutate(bad)
            with pytest.raises(ComputationControlPlaneError):
                worker.encode_evidence_worker_frame_v1(bad, **args)
            denials.append(name)
        print("LP03_MATH26_WORKER_DATA_QUALIFICATION=" + deterministic_json(dict(
            scope="CLOSED_ORIGINAL_RESEARCH_WORKER_DATA_ONLY", roundtrip=True, frame_denials=denials)))
        return
    for name, mutate in (
        ("integer_probability", lambda value: value["payload"]["inputs"]["probability_rows"][1].__setitem__(0, 1)),
        ("zero_sign", lambda value: value["payload"]["inputs"]["probability_rows"][1].__setitem__(1, 0.0)),
        ("boolean_outcome", lambda value: value["payload"]["inputs"]["outcome_indices"].__setitem__(0, True)),
        ("outcome_association", lambda value: value["payload"]["inputs"]["outcome_indices"].reverse()),
        ("source_order", lambda value: value["payload"]["event"]["payload"]["source_slices"].reverse()),
        ("dataset_revision", lambda value: value["payload"]["event"]["payload"]["source_slices"][1]["reconstructed_canonical_events"][0].update(revision=2)),
        ("omitted_source", lambda value: value["payload"]["original_record_refs"].pop(0)),
        ("foreign_float", lambda value: value["payload"]["event"].update(local_ordinal=0.0)),
    ):
        bad = json.loads(deterministic_json(frame))
        mutate(bad)
        with pytest.raises(ComputationControlPlaneError):
            worker.encode_evidence_worker_frame_v1(bad, **args)
        denials.append(name)
    calls = []
    class ForeignMapping(Mapping):
        def __getitem__(self, key):
            calls.append(key)
            return frame[key]
        def __iter__(self):
            calls.append("iterate")
            return iter(frame)
        def __len__(self):
            calls.append("length")
            return len(frame)
    foreign = ForeignMapping()
    for value in (foreign, MappingProxyType(foreign), dict(frame, payload=foreign),
                  dict(frame, payload=dict(frame["payload"], invocation_contract=foreign))):
        with pytest.raises(ComputationControlPlaneError):
            worker.encode_evidence_worker_frame_v1(value, **args)
    assert calls == []
    limits = lane.attempt.registration.protocol.numerical_work_limits
    review = IndependentEvidenceReviewV1._bounded_review_brier_v1
    original_input = deterministic_json(inputs).encode("utf-8")
    original_output = lane.raw.existing_receipt.output_json.encode("utf-8")
    proofs = []
    cases = (
        ("nonexact_intermediate", b'{"outcome_indices":[1],"probability_rows":[[0.1,0.9]]}',
         b'{"mean_brier_score":0.02,"per_observation":[0.02]}', 0.02, dict(limits)),
        ("numerical_exhaustion", original_input, original_output, 0.0625, dict(limits, max_work_bits=0)),
        ("wrong_projection", original_input, original_output, 0.125, dict(limits)),
        ("wrong_per_observation", original_input, b'{"mean_brier_score":0.0625,"per_observation":[0.0,0.125]}', 0.0625, dict(limits)),
    )
    for name, input_json, output_json, projected, budget in cases:
        work = _EvidenceNumericalWorkV1(budget, retained_input_capacity=0)
        with pytest.raises(ComputationControlPlaneError):
            review(input_json, output_json, output_json, projected, work=work)
        assert work.state == "FAILED"
        consumed = dict(work.consumed)
        with pytest.raises(ComputationControlPlaneError, match="LP03_NUMERICAL_WORK_NOT_OPEN"):
            review(input_json, output_json, output_json, projected, work=work)
        assert dict(work.consumed) == consumed
        proofs.append(dict(case=name, failure=work.failure, consumed=consumed))
    print("LP03_BRIER_DATA_DENIALS_QUALIFICATION=" + deterministic_json(dict(frame_denials=denials,
        foreign_mapping_calls=len(calls), numerical_failures=proofs, scope="CLOSED_DATA_AND_NUMERIC_PROOF_DENIALS_ONLY")))


def _assert_lp03_fresh_control_owner_denied(case, original_state, fixture_keys, *, old_attempt=None):
    """New local owners cannot turn retained CONTROL history into fresh authority.

    This deliberately retains the original objects: it qualifies concurrent
    owner replacement, not process death or a cold boot.
    """
    import json
    import pytest
    from dataclasses import replace
    from src.qtt.agents.pr169_agent_orch1_resolvers import AgentOrchService, EvidenceHostBindingV1
    from src.qtt.service.pr169_svc1_resolvers import DashboardReadModelService
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import models as m
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError, ReasonCode
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.migrations import REFERENCE_IDENTITY_COLUMN_BY_TABLE_V1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import deterministic_json
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.sqlite_reference import SQLiteReferenceAdapterV1
    original_store = original_state.control_store
    def snapshot():
        return tuple((table, tuple(original_store._connection.execute("SELECT * FROM " + table + " ORDER BY " + column)))
                     for table, column in REFERENCE_IDENTITY_COLUMN_BY_TABLE_V1.items())
    before = snapshot()
    _, signed, message, envelope = original_state.owner_envelopes[0]
    original_config = original_state.host.public_configuration
    variants = [("same_scope", original_config, envelope, signed)]
    experiment, revision = envelope.experiment_id + "::renamed", envelope.experiment_revision + "::renamed"
    bindings = tuple(replace(item, experiment_scope=(*item.experiment_scope, experiment)) for item in envelope.store_bindings)
    plan = envelope.assembly_scope.scenario_plan_body_or_existing_ref.plan
    plan = replace(plan, record_id=plan.record_id + "::renamed", scenario_plan_ref=plan.record_id + "::renamed",
                   experiment_id=experiment, experiment_revision=revision)
    scope = replace(envelope.assembly_scope, scope_ref=envelope.assembly_scope.scope_ref + "::renamed",
        intended_experiment_id=experiment, intended_experiment_revision=revision,
        scenario_plan_body_or_existing_ref=m.EvidenceInlinePlanV1(plan), preparation_limits=replace(
            envelope.assembly_scope.preparation_limits,
            aggregate_budget_ref=envelope.assembly_scope.preparation_limits.aggregate_budget_ref + "::renamed"))
    renamed = replace(envelope, envelope_ref=envelope.envelope_ref + "::renamed", experiment_id=experiment,
        experiment_revision=revision, assembly_scope=scope, store_bindings=bindings,
        claim_policy_ref=envelope.claim_policy_ref + "::renamed",
        per_attempt_limits=replace(envelope.per_attempt_limits,
            aggregate_budget_ref=envelope.per_attempt_limits.aggregate_budget_ref + "::renamed"),
        aggregate_execution_limits=replace(envelope.aggregate_execution_limits,
            aggregate_budget_ref=envelope.aggregate_execution_limits.aggregate_budget_ref + "::renamed"))
    wire = deterministic_json(replace(message, subject=renamed.envelope_ref, payload=json.loads(deterministic_json(renamed))))
    renamed_signed = m.EvidenceSignedMessageV1(wire, fixture_keys["owner"].sign(
        b"QTT-LP03-EVIDENCE-AUTH-V1\0" + wire.encode("utf-8")).hex())
    variants.append(("renamed_scope", replace(original_config, store_bindings=bindings), renamed, renamed_signed))
    first = original_state.lifecycle_first_operation
    assert first is not None and len(first.lifecycle_rows) == 2
    for variant, config, selected, authorization in variants:
        host = EvidenceHostBindingV1.for_software_conformance_v1(config, role_signing_key=fixture_keys["issuer"])
        control = next(item for item in config.store_bindings if item.role is m.EvidenceStoreRoleV1.CONTROL)
        adapter = SQLiteReferenceAdapterV1.open_evidence_store_v1(host_binding=host, store_binding=control,
            owned_role_root=Path(original_store.database_path).parent, busy_timeout_ms=0, max_transaction_attempts=1)
        try:
            issuer = AgentOrchService()
            context = issuer.bind_evidence_authority_v1(host, control_store=adapter,
                original_owner_envelopes=(authorization,), original_source_registries=tuple(
                    custody.registry for custody in original_state.source_custodies))
            fresh = context._state_for_owner_v1(issuer)
            denials = []
            for key in (first.request.idempotency_key, "LP03-REQUEST::replacement-owner-fresh-key"):
                with pytest.raises(ComputationControlPlaneError, match="LP03_CONTROL_LIFECYCLE_RECOVERY_REQUIRED") as denied:
                    issuer.issue_evidence_assembly_grant_v1(selected.envelope_ref,
                        assembly_request=m.EvidenceAssemblyRequestV1(selected.assembly_scope.scope_ref, key), issuer_context=context)
                assert denied.value.reason_code is ReasonCode.EVIDENCE_RUN_UNRESOLVED
                denials.append(denied.value.args)
            assert fresh.lifecycle_unresolved and fresh.lifecycle_original is None
            assert not fresh.registrations and all(handle is None for _, handle, _source_original in fresh.preparations.values())
            denied_operation = fresh.lifecycle_first_operation
            assert denied_operation.rollback_state == "RETURNED" and denied_operation.consumed["control_writes"] == 2
            assert denied_operation.failure_observation is not None and denied_operation.failure_secondary == []
            assert denied_operation.failure_accounting_state == "OBSERVED_THROUGH_NATIVE_SAMPLE"
            assert not denied_operation.failure_capture_failed and denied_operation.failure_unretained is None
            assert dict(denied_operation.failure_observation[3]) == denied_operation.consumed
            assert denied_operation.failure_observation[1] - denied_operation.grant_record.deadline_clock_and_process.admitted_monotonic_ns == denied_operation.consumed["wall_ns"]
            if old_attempt is not None:
                with pytest.raises(ComputationControlPlaneError, match="LP03_ATTEMPT_ORIGINAL_BINDING_JOIN"):
                    issuer.issue_evidence_attempt_v1(old_attempt.request, issuer_context=context)
            if original_state.assembler_context is not None:
                with pytest.raises(ComputationControlPlaneError, match="LP03_ASSEMBLY_ISSUER_NOT_ORIGINAL"):
                    issuer.resolve_evidence_assembly_grant_v1(first.grant_record.record_id,
                        purpose="EVIDENCE_INPUT_ASSEMBLY_V1", requester_context=original_state.assembler_context)
            svc_host = EvidenceHostBindingV1.for_software_conformance_v1(replace(config, service_owner="SVC1",
                service_principal="LP03-PRINCIPAL::svc_supervisor", signing_key_id="LP03-KEY::svc_supervisor"),
                role_signing_key=fixture_keys["svc_supervisor"])
            svc = DashboardReadModelService()
            with pytest.raises(ComputationControlPlaneError, match="LP03_CONTROL_LIFECYCLE_RECOVERY_REQUIRED") as denied:
                svc.bind_evidence_supervisor_v1(host_binding=svc_host, issuer_context=context)
            assert denied.value.reason_code is ReasonCode.EVIDENCE_RUN_UNRESOLVED
            assert fresh.supervisor is None and not hasattr(svc, "_evidence_supervisor_v1")
            assert snapshot() == before
            print("LP03_CONTROL_LIFECYCLE_QUALIFICATION=" + deterministic_json(dict(case=case, variant=variant,
                scope=selected.assembly_scope.scope_ref, experiment=selected.experiment_id, revision=selected.experiment_revision,
                preparation_budget=selected.assembly_scope.preparation_limits.aggregate_budget_ref,
                execution_budget=selected.aggregate_execution_limits.aggregate_budget_ref, claim_policy=selected.claim_policy_ref,
                root_rows=first.lifecycle_rows, original_phase=first.commit_state,
                first_commit=first.bootstrap_commit_observation, first_readback=first.bootstrap_readback_observation,
                unchanged_table_counts=tuple((table, len(rows)) for table, rows in before), denials=denials,
                attempted_phase=fresh.lifecycle_first_operation.commit_state,
                original_attempt_reservations=(() if old_attempt is None else tuple(
                    row for row in old_attempt.readback_rows if len(row) == 7)),
                rollback_state=denied_operation.rollback_state, failure_observation=denied_operation.failure_observation,
                failure_accounting_state=denied_operation.failure_accounting_state,
                consumed=tuple(fresh.lifecycle_first_operation.consumed.items()), qualification="CONCURRENT_OWNER_DENIED")))
        finally:
            adapter.close()


def _assert_lp03_prelaunch_capacity_denial(case, grant, supervisor, svc, store, registration):
    """Original signed limits reject before controller/native creation/base64."""
    import base64
    import json
    import pytest
    from src.qtt.service.pr169_svc1_resolvers import _WindowsEvidenceProcessV1, EvidenceProcessSupervisorV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import serialization
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ContractValidationError, ReasonCode
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.persistence import _EvidenceAttemptOperationV1
    attempt, entered, encoding = grant._attempt, [], []
    expected = {
        "capacity_input_reads": "LP03_FAILURE_AUDIT_RESERVE_INSUFFICIENT:input_reads",
        "capacity_input_bytes": "LP03_FAILURE_AUDIT_RESERVE_INSUFFICIENT:input_bytes",
        "capacity_persistent_operations": "LP03_FAILURE_AUDIT_RESERVE_INSUFFICIENT:persistent_operations",
        "capacity_persistent_bytes": "LP03_FAILURE_AUDIT_RESERVE_INSUFFICIENT:persistent_bytes",
        "capacity_header": "LP03_FAILURE_CAPTURE_HEADER_CAPACITY",
        "capacity_roster": "LP03_FAILURE_CAPTURE_ROSTER_CAPACITY",
        "capacity_manifest": "LP03_FAILURE_MAXIMUM_MANIFEST_UNREPRESENTABLE",
        "capacity_body": "LP03_PROJECTION_JSON_BYTES",
    }[case]
    original_encoder = serialization._encode_evidence_projection_json_v1

    def forbidden(name):
        def enter(*args, **kwargs):
            entered.append(name)
            raise AssertionError("capacity denial reached " + name)
        return enter

    def observe_encoding(value, **kwargs):
        prelaunch = attempt.failure_audit is None
        operation = value.get("operation") if type(value) is dict else None
        try:
            result = original_encoder(value, **kwargs)
        except BaseException as error:
            if prelaunch:
                encoding.append(dict(operation=operation, returned=False, original_args=BaseException.args.__get__(error)))
            raise
        if prelaunch:
            encoding.append(dict(operation=operation, returned=True, byte_count=len(result)))
        return result

    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(_WindowsEvidenceProcessV1, "_start_controller_v1", forbidden("controller_start"))
        patch.setattr(_WindowsEvidenceProcessV1, "prepare_suspended_v1", forbidden("native_preparation"))
        patch.setattr(_WindowsEvidenceProcessV1, "_load_api_v1", forbidden("native_api_load"))
        patch.setattr(base64, "b64encode", forbidden("base64"))
        patch.setattr(serialization, "_encode_evidence_projection_json_v1", observe_encoding)
        with pytest.raises(ContractValidationError) as caught:
            svc.dispatch_evidence_attempt_v1(grant)
    assert entered == [] and BaseException.args.__get__(caught.value) == (f"{ReasonCode.INVALID_CONTRACT}: {expected}",)
    native = next(item for item in supervisor._retained if item.original[1] is attempt)
    roots = tuple(entry for entry in supervisor._failure_trigger_originals if entry[0] is native and entry[2] == "TRIGGER")
    assert len(roots) == 1 and roots[0][3] is caught.value
    assert native._api_original is native._process_information_original is native._controller is None
    assert native._native_custody == (None, None, None, None, None) and native._no_child_original is not None
    assert tuple(entry[1] for entry in supervisor._creation_originals if entry[0] is native) == ("NOT_ENTERED",)
    assert tuple(entry[1] for entry in supervisor._controller_originals if entry[0] is native) == ("NOT_CREATED",)
    assert not any(entry[0] is native for entry in supervisor._capacity_originals)
    audit = attempt.failure_audit
    assert audit is not None and audit.trigger_original is roots[0]
    assert registration.active_attempt is None and registration.issuer.operation is None
    insufficient = case in ("capacity_input_reads", "capacity_input_bytes", "capacity_persistent_operations", "capacity_persistent_bytes")
    expected_reason = "RESOURCE_EXHAUSTED" if insufficient else "CAPACITY_EXHAUSTED"
    assert audit.failure_reason == expected_reason
    assert type(audit.body_json) is str and audit.body_json.encode("utf-8") == audit.snapshot[4]
    captured_body = json.loads(audit.body_json)
    assert serialization.deterministic_json(captured_body) == audit.body_json
    assert captured_body["primary_reason"] == expected_reason and captured_body["reason_codes"] == [expected_reason]
    # The same native error without the retained call-boundary association,
    # or paired with a different same-text error, keeps the ordinary fallback.
    assert EvidenceProcessSupervisorV1._failure_reason_v1(native, caught.value,
        trigger_original=roots[0]) == "SUPERVISION_FAILURE"
    other_error = ContractValidationError(ReasonCode.INVALID_CONTRACT, expected)
    assert EvidenceProcessSupervisorV1._failure_reason_v1(native, caught.value,
        trigger_original=roots[0], prelaunch_capacity_error=other_error) == "SUPERVISION_FAILURE"
    if insufficient:
        assert audit.phase == "RESERVED" and audit.body is None and audit.rows == () and attempt.terminal_proof is None
        assert supervisor._active is native and supervisor._unresolved
    else:
        assert audit.phase == "COMPLETED_RESERVED" and supervisor._active is None and not supervisor._unresolved
        assert serialization.deterministic_json(audit.body) == audit.body_json
        assert _EvidenceAttemptOperationV1._require_terminal_v1(attempt) is attempt.terminal_original
        assert audit.body["custody"]["kind"] == "NO_CHILD" and audit.body["custody"]["creation_stage"] == "NOT_ENTERED"
        assert audit.body["trigger_error"]["complete"] is True
    if case == "capacity_body":
        assert tuple((item["operation"], item["returned"]) for item in encoding) == (
            ("SVC_PROCESS_CAPTURE_MANIFEST_V1", True), ("SVC_PROCESS_FAILURE_AUDIT_V1", False))
    persisted = []
    for (table, ref), row in zip(audit.refs, audit.rows, strict=True):
        key = "record_id" if table == "receipt_records" else "claim_record_id"
        found = store._connection.execute("SELECT * FROM " + table + " WHERE " + key + "=?", (ref,)).fetchone()
        assert found == row
        persisted.append((table, found))
    errors = tuple(entry for entry in supervisor._failure_trigger_originals if entry[0] is native and entry[2] == "FAILURE_AUDIT")
    if insufficient:
        counter = {"capacity_input_reads": "record_reads", "capacity_input_bytes": "read_bytes",
                   "capacity_persistent_operations": "operations", "capacity_persistent_bytes": "control_bytes"}[case]
        assert len(errors) == 1 and type(errors[0][3]) is ContractValidationError
        assert errors[0][4] == (f"{ReasonCode.INVALID_CONTRACT}: LP03_FAILURE_AUDIT_RESOURCE_EXHAUSTED:{counter}",)
    else:
        assert errors == ()
    print("LP03_PRELAUNCH_CAPACITY_QUALIFICATION=" + serialization.deterministic_json(dict(case=case,
        boundary="SVC_PRELAUNCH", limits=attempt.limits, original_args=roots[0][4], entered=entered, encoding=encoding,
        creation_stages=("NOT_ENTERED",), controller_stages=("NOT_CREATED",), phase=audit.phase, attempt_phase=attempt.phase,
        body=None if audit.body_json is None else json.loads(audit.body_json), rows=persisted,
        commit=audit.commit_observation, readback=audit.readback_observation, released=supervisor._active is None,
        audit_errors=tuple(dict(stage=entry[2], exception_type=entry[9][1], original_args=entry[4]) for entry in errors),
        classification_probes=("original_prelaunch_error", "missing_boundary_denied", "same_text_different_error_denied"),
        consumed=registration.consumed)))


def _assert_lp03_native_failure_audit_cut(case, grant, supervisor, svc, store, registration, *, lane_platform=None):
    """Original CONTROL/native custody with finite, explicitly injected cuts."""
    import json
    import time
    import threading
    from pathlib import Path
    import pytest
    from src.qtt.service.pr169_svc1_resolvers import _WindowsEvidenceProcessV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError, ContractValidationError, ReasonCode
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.persistence import (
        _EvidenceAttemptFailureAuditV1, _EvidenceAttemptOperationV1, _EvidenceBoundStoreV1, EvidenceAvailabilityHandleV1)
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.sqlite_reference import SQLiteReferenceAdapterV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import (
        deterministic_json, _evidence_process_failure_body_v1)
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.latency_policy import _EvidenceLocalClockV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.lifecycle import EvidenceAttemptStateV1
    attempt, injected, callbacks, final_checks = grant._attempt, [], [], []
    original_resume = _WindowsEvidenceProcessV1.resume_v1
    original_load_api = _WindowsEvidenceProcessV1._load_api_v1
    original_native_observe = _WindowsEvidenceProcessV1.observe_v1
    original_receive = _WindowsEvidenceProcessV1._receive_v1
    original_commit = SQLiteReferenceAdapterV1._evidence_commit_failure_audit_v1
    original_read = _EvidenceBoundStoreV1._open_independent_readback_v1
    original_check = _EvidenceAttemptFailureAuditV1._check_current_v1
    original_clock = _EvidenceLocalClockV1.observe_v1
    original_objects = _EvidenceBoundStoreV1._require_original_objects_v1
    original_available = EvidenceAvailabilityHandleV1._require_current_v1
    initial_state = attempt.current_state
    sentinel = object()
    native_calls, query_cut, diagnostic_getters = [], [], []
    lineage_originals, lane_at_cut = [], []
    controller_original, controller_ready, controller_armed = [], threading.Event(), threading.Event()

    def controller_observation_then_error(native):
        observation = original_native_observe(native)
        if (controller_armed.is_set() and threading.current_thread() is native._controller and native.original[1] is attempt
                and native.resumed and attempt.current_state.state is EvidenceAttemptStateV1.RUNNING
                and not controller_original):
            error = ContractValidationError(ReasonCode.INVALID_CONTRACT, "LP03_TEST_ORIGINAL_CONTROLLER_OBSERVATION_FAILURE")
            controller_original.append((native, observation, error, BaseException.args.__get__(error)))
            native_calls.append(dict(operation="ORIGINAL_CONTROLLER_NATIVE_OBSERVATION", observation=observation))
            injected.append("after_original_controller_observation_with_running_predecessor")
            controller_ready.set()
            raise error
        return observation

    def wait_for_original_controller_error(native, ordinal, kind):
        if ordinal == 0:
            assert native.original[1] is attempt
            # START has already been written. Do not race that original write.
            controller_armed.set()
            assert controller_ready.wait(min(2.0, native._remaining_v1()))
            # The ready event marks the original raised error. Joining the
            # original thread proves its catch retained the error and stopped.
            native._controller.join(min(2.0, native._remaining_v1()))
            assert not native._controller.is_alive()
        return original_receive(native, ordinal, kind)

    def omit_lineage(audit, field):
        assert not lineage_originals
        prior = getattr(attempt, field)
        assert prior
        lineage_originals.append((field, prior))
        setattr(attempt, field, () if field == "observation_appends" else None)
        injected.append("original_" + field + "_omitted_at_" + audit.phase)

    def objects_with_lineage_cut(retained, host, adapter):
        result = original_objects(retained, host, adapter)
        audit = attempt.failure_audit
        if (audit is not None and adapter is store and audit.parent_original is not None and not lineage_originals
                and case in ("failure_process_prefix_omitted_after", "failure_lane_association_omitted_after")):
            omit_lineage(audit, "observation_appends" if case == "failure_process_prefix_omitted_after" else "lane_operation")
        return result

    def lane_current_cut(handle, *, operation, purpose, current_grant, clock):
        result = original_available(handle, operation=operation, purpose=purpose, current_grant=current_grant, clock=clock)
        selected = ((case == "failure_lane_before_commit" and operation.finalization_phase == "COMMIT_ATTEMPTED")
            or (case in ("failure_lane_final_return", "failure_lane_association_omitted_before", "failure_lane_association_omitted_after")
                and operation.finalization_phase == "COMMITTED_AND_READBACK"))
        if selected and not lane_at_cut:
            lane_at_cut.append(operation)
            injected.append("original_lane_" + operation.finalization_phase)
            raise RuntimeError("LP03_TEST_FAILURE_CUT")
        return result

    class ForeignExceptionName(type):
        @property
        def __name__(cls):
            diagnostic_getters.append("exception_class_name")
            raise RuntimeError("foreign diagnostic getter must not run")

    class CloseReturnError(OSError, metaclass=ForeignExceptionName):
        pass

    def before_controller(native):
        injected.append("before_controller_creation")
        if case == "failure_trigger_overflow":
            raise RuntimeError("LP03_TEST_FAILURE_CUT", "x" * 20000)
        if case == "failure_trigger_chain":
            try:
                raise ValueError("LP03_TEST_ORIGINAL_CAUSE")
            except ValueError as cause:
                raise RuntimeError("LP03_TEST_FAILURE_CUT") from cause
        raise RuntimeError("LP03_TEST_FAILURE_CUT")

    def native_false_create(native):
        original_load_api(native)
        original_create = native.kernel.CreateProcessW
        missing = str(Path(store.database_path).with_name("LP03-absent-native-launch-directory"))
        assert not Path(missing).exists()
        def failed_create(*args):
            # The original Windows function returns the failure. Only its
            # working-directory input is deliberately unavailable in this case.
            result = original_create(*args[:7], missing, *args[8:])
            error = native.ctypes.get_last_error()
            injected.append(dict(boundary="actual_native_false_create", returned=bool(result), winerror=error))
            native.ctypes.set_last_error(error)
            return result
        patch.setattr(native.kernel, "CreateProcessW", failed_create)

    def after_resume(native):
        original_resume(native)
        injected.append("after_actual_resume_before_running_append")
        raise RuntimeError("LP03_TEST_FAILURE_CUT")

    def native_effect_cuts(native):
        original_load_api(native)
        if case == "failure_suspended_hard_stop":
            original_stop = native.kernel.TerminateJobObject
            def stop_job(job, status):
                assert job == native._native_custody[0] and native.assigned
                before = original_clock(supervisor._clock)
                result = original_stop(job, status)
                last_error = native.ctypes.get_last_error() if not result else None
                after = original_clock(supervisor._clock)
                native_calls.append(dict(operation="TerminateJobObject", returned=bool(result), status=status,
                    error_on_failure=last_error, process_identity=native.identity, observed_between=(before, after)))
                if last_error is not None:
                    native.ctypes.set_last_error(last_error)
                return result
            patch.setattr(native.kernel, "TerminateJobObject", stop_job)
        elif case == "failure_close_return_ambiguity":
            original_close = native.api.CloseHandle
            def close_then_raise(handle):
                selected = handle == native._native_custody[1] and not native_calls
                result = original_close(handle)
                if selected:
                    native_calls.append(dict(operation="CloseHandle", original_returned=True,
                        target="ORIGINAL_PROCESS_HANDLE", process_identity=native.identity))
                    injected.append("successful_original_close_then_exception")
                    raise CloseReturnError("LP03_TEST_POST_CLOSE_RETURN_CUT")
                return result
            patch.setattr(native.api, "CloseHandle", close_then_raise)

    def suspended_hard_stop(native):
        from src.qtt.service.pr169_svc1_resolvers import EvidenceProcessSupervisorV1
        assert native.assigned and not native.resumed and attempt.current_state.state is EvidenceAttemptStateV1.ADMITTED
        EvidenceProcessSupervisorV1.request_stop_v1(supervisor, grant, reason="RESOURCE_EXHAUSTED")
        injected.append("original_assigned_suspended_hard_stop")
        raise RuntimeError("LP03_TEST_FAILURE_CUT")

    def final_query_failure(native):
        if (case in ("failure_unknown_final_query", "failure_final_query_recovery") and threading.current_thread() is threading.main_thread()
                and native._controller_done is not None and native._controller_done.is_set()
                and native._terminal_original is None and not query_cut):
            query_cut.append(True)
            injected.append("final_native_query_unavailable_before_terminal_witness")
            raise OSError("LP03_TEST_FINAL_QUERY_UNAVAILABLE")
        return original_native_observe(native)

    def cancellation_stop(native, ordinal, kind):
        if ordinal == 0:
            from src.qtt.service.pr169_svc1_resolvers import EvidenceProcessSupervisorV1
            EvidenceProcessSupervisorV1.request_stop_v1(supervisor, grant, reason="RESOURCE_EXHAUSTED")
            injected.append("actual_stop_after_running_commit")
            raise RuntimeError("LP03_TEST_FAILURE_CUT")
        return original_receive(native, ordinal, kind)

    def commit_with_callbacks(adapter, audit):
        adapter._connection.set_trace_callback(lambda *_: callbacks.append("trace"))
        adapter._connection.set_authorizer(lambda *_: callbacks.append("authorizer") or 1)
        adapter._connection.set_progress_handler(lambda: callbacks.append("progress") or 1, 1)
        return original_commit(adapter, audit)

    def read_cut(retained, host, adapter, operation):
        lane = attempt.lane_operation
        if (case == "failure_lane_readback" and lane is not None and adapter is store
                and lane.finalization_phase == "COMMITTED_PENDING_READBACK" and not lane_at_cut):
            lane_at_cut.append(lane)
            injected.append("original_lane_postcommit_before_independent_readback")
            raise RuntimeError("LP03_TEST_FAILURE_CUT")
        if type(operation) is _EvidenceAttemptFailureAuditV1 and case == "failure_audit_readback":
            injected.append("after_actual_commit_before_independent_readback")
            raise RuntimeError("LP03_TEST_AUDIT_READBACK_CUT")
        return original_read(retained, host, adapter, operation)

    def accounting_cut(audit):
        result = original_check(audit)
        if case == "failure_before_audit_commit" and audit.phase == "COMMIT_ATTEMPTED":
            injected.append("before_native_audit_commit")
            raise RuntimeError("LP03_TEST_AUDIT_COMMIT_CUT")
        if audit.phase == "COMMITTED_AND_READBACK":
            final_checks.append(True)
            if len(final_checks) == 2:
                if case == "failure_final_accounting":
                    injected.append("last_actual_accounting_then_failure")
                    raise RuntimeError("LP03_TEST_FINAL_ACCOUNTING_CUT")
                if case == "failure_final_slot":
                    injected.append("active_slot_substitution_after_last_native_observation")
                    supervisor._active = sentinel
        return result

    def commit_observation_cut(clock):
        audit = attempt.failure_audit
        lane = attempt.lane_operation
        if (case == "failure_lane_commit_observation" and lane is not None
                and lane.finalization_phase == "COMMITTED_PENDING_READBACK" and lane.final_commit_observation is None
                and not lane_at_cut):
            lane_at_cut.append(lane)
            injected.append("original_lane_postcommit_before_commit_clock")
            raise RuntimeError("LP03_TEST_FAILURE_CUT")
        if audit is not None and audit.phase == "ENTRY_RETAINED" and audit.started is None:
            if case in ("failure_process_prefix_omitted_before", "failure_lane_association_omitted_before"):
                omit_lineage(audit, "observation_appends" if case == "failure_process_prefix_omitted_before" else "lane_operation")
            elif case == "failure_trigger_custody":
                original = audit.trigger_original
                replacement = (*original[:4], ("substituted diagnostic",), *original[5:])
                supervisor._failure_trigger_originals = tuple(replacement if entry is original else entry
                    for entry in supervisor._failure_trigger_originals)
                injected.append("original_trigger_substitution_at_first_audit_clock")
            elif case == "failure_trigger_metadata":
                BaseException.args.__set__(audit.trigger_original[3], ("changed after first catch",))
                injected.append("live_error_args_changed_at_first_audit_clock")
        if case == "failure_audit_commit_observation" and audit is not None and audit.phase == "COMMITTED_PENDING_READBACK" and audit.commit_observation is None:
            injected.append("after_native_commit_before_commit_clock")
            raise RuntimeError("LP03_TEST_AUDIT_COMMIT_OBSERVATION_CUT")
        return original_clock(clock)

    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(SQLiteReferenceAdapterV1, "_evidence_commit_failure_audit_v1", commit_with_callbacks)
        patch.setattr(_EvidenceBoundStoreV1, "_open_independent_readback_v1", read_cut)
        patch.setattr(_EvidenceAttemptFailureAuditV1, "_check_current_v1", accounting_cut)
        patch.setattr(_EvidenceLocalClockV1, "observe_v1", commit_observation_cut)
        patch.setattr(_EvidenceBoundStoreV1, "_require_original_objects_v1", objects_with_lineage_cut)
        patch.setattr(EvidenceAvailabilityHandleV1, "_require_current_v1", lane_current_cut)
        if case == "failure_controller_original_error":
            patch.setattr(_WindowsEvidenceProcessV1, "observe_v1", controller_observation_then_error)
            patch.setattr(_WindowsEvidenceProcessV1, "_receive_v1", wait_for_original_controller_error)
        elif case == "failure_after_resume":
            patch.setattr(_WindowsEvidenceProcessV1, "resume_v1", after_resume)
        elif case in ("failure_cancellation_settlement", "failure_process_prefix_omitted_before", "failure_process_prefix_omitted_after"):
            patch.setattr(_WindowsEvidenceProcessV1, "_receive_v1", cancellation_stop)
        elif case == "failure_native_false_create":
            patch.setattr(_WindowsEvidenceProcessV1, "_load_api_v1", native_false_create)
        elif case == "failure_suspended_hard_stop":
            patch.setattr(_WindowsEvidenceProcessV1, "_load_api_v1", native_effect_cuts)
            patch.setattr(_WindowsEvidenceProcessV1, "resume_v1", suspended_hard_stop)
        elif case == "failure_close_return_ambiguity":
            patch.setattr(_WindowsEvidenceProcessV1, "_load_api_v1", native_effect_cuts)
        elif case == "failure_unknown_final_query":
            # Startup already failed after ResumeThread; its single settlement
            # query fails before any original terminal witness is retained.
            patch.setattr(_WindowsEvidenceProcessV1, "resume_v1", after_resume)
            patch.setattr(_WindowsEvidenceProcessV1, "observe_v1", final_query_failure)
        elif case == "failure_final_query_recovery":
            # The first query fails; dispatch's subsequent real observation
            # can prove later terminal custody without erasing that failure.
            patch.setattr(_WindowsEvidenceProcessV1, "observe_v1", final_query_failure)
        elif case == "failure_natural_expiry":
            before = original_clock(supervisor._clock)
            remaining = attempt.deadline.exclusive_deadline_monotonic_ns - before[1]
            assert 0 < remaining < 30_000_000_000
            _lp03_wait_until_native_clock_v1(time.monotonic_ns, attempt.deadline.exclusive_deadline_monotonic_ns + 1_000_000)
            after = original_clock(supervisor._clock)
            assert before[1] < attempt.deadline.exclusive_deadline_monotonic_ns <= after[1] < attempt.failure_bounds[1]
            injected.append(dict(boundary="actual_original_deadline_elapsed", before=before, after=after))
        elif not case.startswith("failure_lane_"):
            patch.setattr(_WindowsEvidenceProcessV1, "_start_controller_v1", before_controller)
        expected_error = (OSError if case == "failure_native_false_create" else
                          ComputationControlPlaneError if case in ("failure_natural_expiry", "failure_final_query_recovery",
                              "failure_close_return_ambiguity", "failure_controller_original_error") else RuntimeError)
        expected_message = "LP03_ATTEMPT_EXPIRED" if case == "failure_natural_expiry" else (
            "LP03_NATIVE_TERMINATION_UNKNOWN" if case == "failure_final_query_recovery" else
            "LP03_NATIVE_WORKER_TERMINAL_NONPOSITIVE" if case == "failure_close_return_ambiguity" else
            None if case in ("failure_native_false_create", "failure_trigger_metadata", "failure_controller_original_error") else "LP03_TEST_FAILURE_CUT")
        with pytest.raises(expected_error, match=expected_message) as caught:
            if case.startswith("failure_lane_"):
                assert lane_platform is not None
                lane_platform.run_lane_v1(grant)
            else:
                svc.dispatch_evidence_attempt_v1(grant)
    native = next(item for item in supervisor._retained if item.original[1] is attempt)
    audit = attempt.failure_audit
    audit_errors = tuple(entry for entry in supervisor._failure_trigger_originals if entry[0] is native and entry[2] == "FAILURE_AUDIT")
    assert type(audit) is _EvidenceAttemptFailureAuditV1 and injected and callbacks == []
    assert diagnostic_getters == []
    assert registration.active_attempt is None and registration.issuer.operation is None
    assert audit.started[1] < attempt.failure_bounds[2]
    if case not in ("failure_trigger_custody", "failure_lane_association_omitted_before"):
        assert audit.started is audit.identity_original[10]
    assert audit.prefix["control_writes"] <= registration.consumed["control_writes"]
    assert audit.trigger_original[3] is caught.value
    if case not in ("failure_trigger_custody", "failure_lane_association_omitted_before"):
        assert audit.trigger_original is audit.identity_original[17]
    if case in ("failure_process_prefix_omitted_before", "failure_process_prefix_omitted_after",
                "failure_lane_association_omitted_before", "failure_lane_association_omitted_after"):
        assert len(lineage_originals) == 1 and audit.rows == () and audit.record is None and audit.body is None
        assert audit.phase == ("ENTRY_RETAINED" if case == "failure_lane_association_omitted_before" else "RESERVED")
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        assert native._terminal_original is not None and native._terminal_original[0]["active_processes"] == 0
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ContractValidationError, ReasonCode
        expected_denial = {"failure_process_prefix_omitted_before": "LP03_FAILURE_COMPLETE_PROCESS_PREFIX_REQUIRED",
            "failure_process_prefix_omitted_after": "LP03_FAILURE_PARENT_ROSTER_CHANGED",
            "failure_lane_association_omitted_before": "LP03_FAILURE_ORIGINAL_LANE_ASSOCIATION_REQUIRED",
            "failure_lane_association_omitted_after": "LP03_FAILURE_ORIGINAL_LANE_ASSOCIATION_CHANGED"}[case]
        assert len(audit_errors) == 1 and type(audit_errors[0][3]) is ContractValidationError
        expected_code = (ReasonCode.EVIDENCE_PREFIX_INCOMPLETE if case == "failure_process_prefix_omitted_before"
            else ReasonCode.INVALID_CONTRACT)
        assert audit_errors[0][3].reason_code is expected_code
        assert audit_errors[0][4] == (f"{expected_code}: {expected_denial}",)
        field, prior = lineage_originals[0]
        setattr(attempt, field, prior)  # Restore only the injected omission for inspection; no retry or release.
        assert attempt.current_state is audit.predecessor
        with pytest.raises(ComputationControlPlaneError):
            _EvidenceAttemptOperationV1._require_terminal_v1(attempt)
    elif case == "failure_controller_original_error":
        assert len(controller_original) == len(native_calls) == 1
        observed_native, observation, error, original_args = controller_original[0]
        roots = tuple(entry for entry in supervisor._failure_trigger_originals if entry[0] is native and entry[2] == "CONTROLLER")
        assert observed_native is native and len(roots) == 1 and roots[0][3] is error
        assert roots[0][4] is original_args and roots[0][5] is BaseException.__traceback__.__get__(error)
        assert roots[0][4] == (f"{ReasonCode.INVALID_CONTRACT}: LP03_TEST_ORIGINAL_CONTROLLER_OBSERVATION_FAILURE",)
        assert observation["process_identity"] == native.identity
        assert audit.phase == "COMMITTED_QUARANTINED" and attempt.phase == "FAILURE_AUDITED_QUARANTINED"
        assert audit.body["primary_reason"] == "SUPERVISION_FAILURE"
        assert audit.body["trigger_error"]["secondary_error_count"] == 1 and not audit.body["trigger_error"]["complete"]
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        assert native._terminal_original is not None and native._terminal_original[0]["active_processes"] == 0
        assert type(native._terminal_original[0]["exit_code"]) is int
        assert native._terminal_original[1:3] == (True, True) and native._terminal_original[9]["complete"]
        assert not native._terminal_original[8] and not native.cleanup_errors
        assert native._exchange_original is None and attempt.lane_operation is None
        assert registration.conformance_operation is registration.review_operation is registration.closed_conformance_operation is None
        retained_report = _lp03_retained_failure_diagnostics(supervisor)
        reported = next(entry for entry in retained_report["retained_entries"] if entry["stage"] == "CONTROLLER")
        assert reported["arguments_complete"] and tuple(reported["argument_prefix"]) == original_args
        assert reported["traceback_complete"] and any(frame["function"] == "controller_observation_then_error" for frame in reported["traceback_prefix"])
        with pytest.raises(ComputationControlPlaneError):
            _EvidenceAttemptOperationV1._require_terminal_v1(attempt)
    elif case.startswith("failure_lane_"):
        assert len(lane_at_cut) == 1 and attempt.lane_operation is lane_at_cut[0]
        lane = lane_at_cut[0]
        expected_phase = {"failure_lane_before_commit": "ROLLED_BACK",
            "failure_lane_commit_observation": "COMMIT_OR_OBSERVATION_UNRESOLVED",
            "failure_lane_readback": "COMMITTED_PENDING_READBACK", "failure_lane_final_return": "COMMITTED_AND_READBACK"}[case]
        assert lane.finalization_phase == expected_phase
        assert audit.phase == "COMMITTED_QUARANTINED" and audit.record is None
        assert audit.body["lifecycle_disposition"] == "ORIGINAL_PREDECESSOR_RETAINED"
        assert attempt.current_state is audit.predecessor and attempt.current_state.state is EvidenceAttemptStateV1.RUNNING
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        assert lane.phase == "COMMITTED_AND_READBACK" and lane.publication_readback_original is not None
        assert lane.platform._store is lane_platform._store
    elif case in ("failure_before_controller", "failure_cancellation_settlement", "failure_native_false_create", "failure_natural_expiry",
                "failure_trigger_metadata"):
        assert audit.phase == "COMPLETED_RESERVED" and attempt.phase == "FAILURE_AUDITED_RESERVED"
        assert supervisor._active is None and not supervisor._unresolved
        assert _EvidenceAttemptOperationV1._require_terminal_v1(attempt) is attempt.terminal_original
        assert registration.retained_reservations[-1][0] is attempt and registration.retained_reservations[-1][1] is attempt.limits
        assert attempt.current_state.state is (EvidenceAttemptStateV1.FAILED if case == "failure_cancellation_settlement" else EvidenceAttemptStateV1.FAILED_TO_START)
        assert audit.body["trigger_error"]["complete"] is True
        if case == "failure_trigger_metadata":
            assert BaseException.args.__get__(caught.value) == ("changed after first catch",)
            assert tuple(audit.body["trigger_error"]["argument_prefix"]) == ("LP03_TEST_FAILURE_CUT",)
        elif case == "failure_natural_expiry":
            assert tuple(audit.body["reason_codes"]) == ("EXPIRED",) and audit.body["primary_reason"] == "EXPIRED"
            assert audit.body["custody"]["creation_stage"] == "NOT_ENTERED" and audit.body["custody"]["controller_status"] == "NOT_CREATED"
        elif case == "failure_native_false_create":
            assert audit.body["custody"]["creation_stage"] == "RETURNED_FAILURE"
            assert tuple(audit.body["reason_codes"]) == ("FAILED_TO_START",)
            assert injected[0]["returned"] is False and injected[0]["winerror"] > 0
            assert audit.body["trigger_error"]["native_error_or_absence"][1] == injected[0]["winerror"] == caught.value.winerror
    elif case in ("failure_trigger_overflow", "failure_trigger_chain"):
        assert audit.phase == "COMMITTED_QUARANTINED" and attempt.phase == "FAILURE_AUDITED_QUARANTINED"
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        trigger = audit.body["trigger_error"]
        assert trigger["complete"] is False
        if case == "failure_trigger_overflow":
            assert trigger["argument_count"] == 2 and tuple(trigger["argument_prefix"]) == ("LP03_TEST_FAILURE_CUT",)
            assert trigger["arguments_complete"] is False
        else:
            assert trigger["cause_retention"] == trigger["context_retention"] == "PRESENT_NOT_RETAINED"
    elif case == "failure_trigger_custody":
        assert audit.phase == "ENTRY_RETAINED" and audit.identity_original is None and not audit.rows and audit.body is None
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        assert audit.trigger_original[4] == ("LP03_TEST_FAILURE_CUT",)
        assert not any(entry is audit.trigger_original for entry in supervisor._failure_trigger_originals)
    elif case in ("failure_after_resume", "failure_suspended_hard_stop"):
        assert native.resumed is (case == "failure_after_resume") and native._terminal_original is not None
        assert audit.phase == "COMMITTED_QUARANTINED" and audit.record is None and attempt.current_state is initial_state
        assert audit.body["lifecycle_disposition"] == "ORIGINAL_PREDECESSOR_RETAINED"
        assert audit.body["custody"]["kind"] == "TERMINAL" and "FAILED_TO_START" not in audit.body["reason_codes"]
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        if case == "failure_suspended_hard_stop":
            assert len(native_calls) == 1 and native_calls[0]["returned"] is True and native_calls[0]["error_on_failure"] is None
            assert native._terminal_original[0]["exit_code"] == 1 and native._terminal_original[0]["active_processes"] == 0
            # TotalTerminatedProcesses counts limit violations, not explicit
            # TerminateJobObject calls. The exact call/return is retained above.
            assert native._terminal_original[0]["total_processes"] == 1 and native._terminal_original[0]["terminated_processes"] == 0
            assert native._terminal_original[9]["stdout"] == native._terminal_original[9]["stderr"] == b""
    elif case in ("failure_unknown_final_query", "failure_final_query_recovery", "failure_close_return_ambiguity"):
        assert audit.phase == "COMMITTED_QUARANTINED" and attempt.phase == "FAILURE_AUDITED_QUARANTINED"
        assert supervisor._active is native and supervisor._unresolved and attempt.terminal_proof is None
        assert audit.body["trigger_error"]["complete"] is False and audit.body["trigger_error"]["secondary_error_count"] == 1
        if case == "failure_unknown_final_query":
            assert query_cut == [True] and native._terminal_original is None
            assert audit.body["custody"]["kind"] == "TERMINATION_UNKNOWN" and audit.body["primary_reason"] == "TERMINATION_UNKNOWN"
            assert attempt.current_state.state is EvidenceAttemptStateV1.TERMINATION_UNKNOWN
            assert audit.body["custody"]["cleanup_complete"] is False
            assert audit.body["custody"]["native_observation_or_absence"]["exit_code"] == 1
            assert audit.body["custody"]["native_observation_or_absence"]["active_processes"] == 0
        elif case == "failure_final_query_recovery":
            assert caught.value.reason_code is ReasonCode.EVIDENCE_TERMINATION_UNKNOWN
            assert audit.body["trigger_error"]["reason_code_or_absence"] == ReasonCode.EVIDENCE_TERMINATION_UNKNOWN.value
            assert query_cut == [True] and native._terminal_original is not None
            assert native._terminal_original[0]["exit_code"] == 0 and native._terminal_original[0]["active_processes"] == 0
            assert audit.body["custody"]["kind"] == "TERMINAL" and audit.body["custody"]["cleanup_complete"] is True
            assert audit.body["controller_error_count"] == 1 and audit.body["primary_reason"] == "SUPERVISION_FAILURE"
            assert attempt.current_state.state is EvidenceAttemptStateV1.FAILED
        else:
            assert len(native_calls) == 1 and native_calls[0]["original_returned"] is True
            assert audit.body["custody"]["kind"] == "TERMINAL" and audit.body["cleanup_error_count"] == 1
            assert audit.body["custody"]["cleanup_complete"] is False
            assert native._terminal_original is not None and native.phase == "TERMINAL_RETAINED_CLEANUP_FAILED"
            assert native._native_custody[1] is not None  # Ambiguous mirror, not a claim this handle remains open.
            with pytest.raises(ComputationControlPlaneError, match="LP03_NATIVE_RELEASE_ALREADY_ATTEMPTED"):
                _WindowsEvidenceProcessV1._close_settled_v1(native, native._terminal_original)
    else:
        expected_phase = {"failure_before_audit_commit": "ROLLED_BACK",
            "failure_audit_commit_observation": "COMMIT_OR_OBSERVATION_UNRESOLVED",
            "failure_audit_readback": "COMMITTED_PENDING_READBACK", "failure_final_accounting": "COMMITTED_AND_READBACK",
            "failure_final_slot": "COMMITTED_AND_READBACK"}[case]
        assert audit.phase == expected_phase and attempt.current_state is initial_state and attempt.terminal_proof is None
        assert supervisor._active is (sentinel if case == "failure_final_slot" else native) and supervisor._unresolved
        with pytest.raises(ComputationControlPlaneError) as unresolved:
            _EvidenceAttemptOperationV1._require_terminal_v1(attempt)
        if case == "failure_audit_commit_observation":
            assert unresolved.value.reason_code is ReasonCode.EVIDENCE_COMMIT_AMBIGUOUS
            assert audit.commit_observation is audit.readback_observation is None
        if case == "failure_final_slot":
            supervisor._active = native  # Restore only the injected test substitution; custody stays quarantined.
    persisted = []
    lane_rows = []
    if lane_at_cut:
        lane = lane_at_cut[0]
        assert attempt.current_state is audit.predecessor and attempt.current_state.state is EvidenceAttemptStateV1.RUNNING
        assert store._connection.execute("SELECT 1 FROM receipt_records WHERE record_id=?",
            (grant.grant_ref + "::STATE:FAILURE",)).fetchone() is None
        for table, row, _record in lane.final_rows:
            key = "record_id" if table == "receipt_records" else "claim_record_id"
            found = store._connection.execute("SELECT * FROM " + table + " WHERE " + key + "=?", (row[0],)).fetchone()
            assert found == (None if case == "failure_lane_before_commit" else row)
            if found is not None:
                lane_rows.append((table, found))
        assert len(lane_rows) == (0 if case == "failure_lane_before_commit" else 4)
    for (table, ref), row in zip(audit.refs, audit.rows, strict=True):
        key = "record_id" if table == "receipt_records" else "claim_record_id"
        found = store._connection.execute("SELECT * FROM " + table + " WHERE " + key + "=?", (ref,)).fetchone()
        if case == "failure_before_audit_commit":
            assert found is None
        else:
            assert found == row
            persisted.append((table, found))
    if audit.body_json is not None and audit.rows_original is not None:
        decoded = _evidence_process_failure_body_v1(audit.body_json.encode("utf-8"), capture_segment_bodies=audit.capture_bodies,
            maximum_capture_bytes=attempt.limits.max_output_bytes, maximum_segment_bytes=attempt.limits.segment_max_bytes,
            maximum_segments=attempt.limits.max_persistent_operations, maximum_total_bytes=attempt.limits.max_persistent_bytes)
        assert deterministic_json(decoded) == audit.body_json
    print("LP03_NATIVE_FAILURE_AUDIT_QUALIFICATION=" + deterministic_json(dict(case=case, injected=injected, native_calls=native_calls,
        diagnostic_getter_calls=diagnostic_getters, retained_failure_roots=_lp03_retained_failure_diagnostics(supervisor),
        audit_errors=tuple(dict(stage=entry[2], exception_type=entry[9][1], original_args=entry[4]) for entry in audit_errors),
        lane_finalization=None if not lane_at_cut else dict(phase=lane_at_cut[0].finalization_phase, rows=lane_rows,
            commit=lane_at_cut[0].final_commit_observation, readback=lane_at_cut[0].final_readback_observation,
            data_commit=lane_at_cut[0].commit_observation, data_readback=lane_at_cut[0].readback_observation,
            publication_commit=lane_at_cut[0].publication_commit_observation,
            publication_readback=lane_at_cut[0].publication_readback_observation),
        phase=audit.phase, attempt_phase=attempt.phase, body=None if audit.body_json is None else json.loads(audit.body_json),
        capture_segment_bodies=tuple(raw.decode("utf-8") for raw in audit.capture_bodies), rows=persisted,
        commit=audit.commit_observation, readback=audit.readback_observation, consumed=registration.consumed,
        terminal=None if native._terminal_original is None else native._terminal_original[0],
        no_child=native._no_child_original is not None, released=supervisor._active is None)))


def _assert_lp03_math03_manifest_bounds(native, grant, segments, manifest_raw, require_both):
    import base64
    import pytest
    from unittest.mock import patch
    from src.qtt.service.pr169_svc1_resolvers import EvidenceProcessSupervisorV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError

    assert grant.lane.value == "REPLAY" and grant.component_closure == ("MATH-03",)
    capture = native._terminal_original[9]
    assert capture["complete"] and not capture["stderr"]
    size = len(capture["stdout"])
    manifest = json.loads(manifest_raw)
    stdout, stderr = manifest["streams"]
    assert stdout["stream"] == "STDOUT" and stderr["stream"] == "STDERR" and not stderr["segment_refs"]

    # Derive the conservative header width from the genuine first segment.
    # All seven counters and the ordinal suffix use the signed 64-bit maximum
    # width. Both boolean flags use the longer JSON spelling in the bound.
    first = json.loads(segments[0])
    assert first["stream"] == "STDOUT" and first["segment_ordinal"] == 0
    width = len(str(2**63 - 1))
    counters = ("segment_ordinal", "stream_segment_count", "first_byte_offset", "captured_byte_count",
                "stream_captured_byte_count", "stream_observed_byte_count", "stream_discarded_byte_count")
    header = len(segments[0]) - len(first["data_base64"]) + width - 1
    header += sum(width - len(str(first[key])) for key in counters)
    header += int(first["stream_eof"]) + int(first["capture_complete"])
    limit = 16_384
    def json_bytes(value):
        return len(deterministic_json(value).encode("utf-8"))

    if require_both:
        # With this much actual output each target has a three-byte-aligned
        # chunk width. These read-only narrowings never affect the worker.
        assert size >= 39_330
        cases = [(header + 4 * ((size - 1) // (3 * (count - 1))), count) for count in (114, 115)]
    else:
        cases = [(1161, None)]
    for cap, required_count in cases:
        assert header < cap <= min(grant.budgets.segment_max_bytes, grant.budgets.frame_byte_limit)
        chunk = 3 * ((cap - header) // 4)
        count = (size + chunk - 1) // chunk
        refs = [f'{manifest["observation_ref"]}::CAPTURE:STDOUT:{ordinal}' for ordinal in range(count)]
        refs_size = json_bytes(refs)
        refs_bound = 2 + count - 1 + count * json_bytes(refs[-1])
        full_size = len(manifest_raw) - json_bytes(stdout["segment_refs"]) + refs_size
        assert refs_size <= refs_bound
        if required_count is not None:
            assert count == required_count
            if count == 114:
                assert refs_bound <= limit < full_size
            else:
                assert refs_bound > limit
        planner = EvidenceProcessSupervisorV1._capture_manifest_v1
        if refs_bound > limit or full_size > limit:
            diagnostic = "LP03_CAPTURE_MANIFEST_BYTES" if refs_bound > limit else "LP03_PROJECTION_JSON_BYTES"
            with patch.object(base64, "b64encode", side_effect=AssertionError("encoded before rejection")) as encoding:
                with pytest.raises(ComputationControlPlaneError, match=diagnostic):
                    planner(native.original[0], native, maximum_segment_bytes=cap)
                encoding.assert_not_called()
        else:
            diagnostic = "ACCEPTED"
            raw, bodies = planner(native.original[0], native, maximum_segment_bytes=cap)
            assert len(raw) == full_size and json.loads(raw)["streams"][0]["segment_refs"] == refs
            assert b"".join(base64.b64decode(json.loads(body)["data_base64"], validate=True)
                            for body in bodies) == capture["stdout"]
        assert native._terminal_original[9] is capture
        print("LP03_MATH03_CAPTURE_BOUNDARY=" + deterministic_json(dict(stdout_bytes=size,
            segment_limit=cap, chunk_bytes=chunk, segment_count=count, reference_list_bytes=refs_size,
            reference_upper_bound=refs_bound, full_manifest_bytes=full_size, result=diagnostic)))


def _assert_lp03_native_capture_snapshot(native, grant, *, require_manifest_boundaries=False):
    import base64
    import io
    import json
    import pytest
    from dataclasses import replace
    from types import MappingProxyType
    from src.qtt.service.pr169_svc1_resolvers import EvidenceProcessSupervisorV1, _WindowsEvidenceProcessV1
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane import evidence_execution as worker
    terminal = native._terminal_original
    captured = terminal[9]
    assert type(captured) is MappingProxyType and captured["complete"] is True
    assert captured["stdout_observed_bytes"] == len(captured["stdout"])
    assert captured["stderr_observed_bytes"] == len(captured["stderr"]) == 0
    assert captured["stdout_discarded_bytes"] == captured["stderr_discarded_bytes"] == 0
    assert len(captured["stdout"]) + len(captured["stderr"]) == terminal[6] <= grant.budgets.max_output_bytes
    stream, decoded = io.BytesIO(captured["stdout"]), []
    while (raw := worker._read_worker_frame_bytes_v1(stream, grant.budgets.frame_byte_limit)) is not None:
        decoded.append(worker.decode_evidence_worker_frame_v1(raw, direction="WORKER_TO_PARENT", attempt_ref=grant.grant_ref,
            fence_ref=grant.fence_ref, ordinal=len(decoded), frame_byte_limit=grant.budgets.frame_byte_limit))
    assert tuple(decoded) == terminal[4]
    with pytest.raises(TypeError):
        captured["complete"] = False
    supervisor = native.original[0]
    encode = EvidenceProcessSupervisorV1._capture_segment_bodies_v1
    segments = encode(supervisor, native)
    manifest_raw, manifest_segments = EvidenceProcessSupervisorV1._capture_manifest_v1(supervisor, native)
    assert manifest_segments == segments
    manifest = json.loads(manifest_raw.decode("utf-8", "strict"))
    assert manifest["capture_complete"] and manifest["grant_ref"] == grant.grant_ref
    assert manifest["fence_ref"] == grant.fence_ref and manifest["supervisor_instance_ref"] == supervisor.instance_ref
    assert len(manifest["streams"]) == 2
    for stream, facts in zip(("STDOUT", "STDERR"), manifest["streams"], strict=True):
        assert facts["stream"] == stream and facts["eof"] and facts["discarded_byte_count"] == 0
        assert facts["observed_byte_count"] == facts["captured_byte_count"] == len(captured[stream.lower()])
        assert facts["segment_refs"] == [json.loads(body)["capture_segment_ref"] for body in segments
                                          if json.loads(body)["stream"] == stream]
    encoded_calls = []
    def forbid_encoding(*args, **kwargs):
        encoded_calls.append(True)
        raise AssertionError("base64 entered before complete output preflight")
    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(base64, "b64encode", forbid_encoding)
        with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_MANIFEST_TOTAL_BYTES"):
            EvidenceProcessSupervisorV1._capture_manifest_v1(supervisor, native,
                maximum_total_bytes=sum(len(body) for body in segments))
        for narrowed in ({"maximum_total_bytes": True}, {"maximum_segment_bytes": True},
                {"maximum_total_bytes": grant.budgets.max_persistent_bytes + 1},
                {"maximum_segment_bytes": min(grant.budgets.frame_byte_limit, grant.budgets.segment_max_bytes) + 1}):
            with pytest.raises(ComputationControlPlaneError):
                EvidenceProcessSupervisorV1._capture_manifest_v1(supervisor, native, **narrowed)
    assert encoded_calls == []
    if require_manifest_boundaries or (grant.lane.value == "REPLAY" and grant.component_closure == ("MATH-03",)
            and grant.causal_timeline_v1() is None):
        _assert_lp03_math03_manifest_bounds(native, grant, segments, manifest_raw, require_manifest_boundaries)
    rebuilt = {"STDOUT": bytearray(), "STDERR": bytearray()}
    ordinals = {"STDOUT": 0, "STDERR": 0}
    for raw in segments:
        assert type(raw) is bytes and len(raw) <= min(grant.budgets.segment_max_bytes, grant.budgets.frame_byte_limit)
        body = json.loads(raw.decode("utf-8", "strict"))
        stream = body["stream"]
        assert body["segment_ordinal"] == ordinals[stream] and body["first_byte_offset"] == len(rebuilt[stream])
        assert body["capture_segment_ref"] == grant.grant_ref + "::PROCESS:FAILURE::CAPTURE:" + stream + ":" + str(ordinals[stream])
        assert body["grant_ref"] == grant.grant_ref and body["fence_ref"] == grant.fence_ref
        assert body["supervisor_instance_ref"] == supervisor.instance_ref
        assert body["capture_complete"] and body["stream_eof"] and body["stream_discarded_byte_count"] == 0
        assert body["stream_observed_byte_count"] == body["stream_captured_byte_count"] == len(captured[stream.lower()])
        binary = base64.b64decode(body["data_base64"], validate=True)
        assert len(binary) == body["captured_byte_count"]
        rebuilt[stream].extend(binary)
        ordinals[stream] += 1
        assert (ordinals[stream] == body["stream_segment_count"]) is (len(rebuilt[stream]) == len(captured[stream.lower()]))
    assert all(bytes(rebuilt[stream]) == captured[stream.lower()] for stream in rebuilt)
    with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_ORIGINAL_NATIVE_REQUIRED"):
        encode(supervisor, object.__new__(_WindowsEvidenceProcessV1))
    for owner, field, changed in ((native, "_terminal_original", tuple(list(terminal))),
            (native, "original", tuple(list(native.original))),
            (native.original[1], "payload", replace(grant))):
        with pytest.MonkeyPatch.context() as patch:
            patch.setattr(owner, field, changed)
            with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_ORIGINAL_WITNESS_CHANGED"):
                encode(supervisor, native)
    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(supervisor, "_capture_originals", ())
        with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_ORIGINAL_WITNESS_REQUIRED"):
            encode(supervisor, native)
    # Inspection remains possible under quarantine; this grants no new launch,
    # durable write, slot release, successful result or source authority.
    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(supervisor, "_unresolved", True)
        assert encode(supervisor, native) == segments
        with pytest.raises(ComputationControlPlaneError, match="LP03_SUPERVISOR_NOT_ORIGINAL_OR_UNRESOLVED"):
            EvidenceProcessSupervisorV1._assert_original_v1(supervisor)
    return tuple(raw.decode("utf-8", "strict") for raw in segments), manifest_raw.decode("utf-8", "strict")


def _assert_lp03_capture_segment_data():
    """Independent opaque-byte fixtures; never process or grant evidence."""
    import base64
    import pytest
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.errors import ComputationControlPlaneError
    from src.qtt.stage1_prediction_markets.qku_computation_control_plane.serialization import (
        deterministic_json, _evidence_process_capture_segment_body_v1, _evidence_process_capture_manifest_v1)
    decode = _evidence_process_capture_segment_body_v1
    body = dict(schema_version="1.0", operation="SVC_PROCESS_CAPTURE_SEGMENT_V1",
        capture_segment_ref="data::PROCESS:FAILURE::CAPTURE:STDERR:0", observation_ref="data::PROCESS:FAILURE",
        grant_ref="data", fence_ref="data-fence", supervisor_instance_ref="data-supervisor", stream="STDERR",
        segment_ordinal=0, stream_segment_count=1, first_byte_offset=0, captured_byte_count=4,
        stream_captured_byte_count=4, stream_observed_byte_count=4, stream_discarded_byte_count=0,
        stream_eof=True, capture_complete=True, encoding="BASE64_RFC4648_STANDARD_PADDED", data_base64="AP9/gA==")
    raw = deterministic_json(body).encode("utf-8")
    frozen, binary = decode(raw, maximum_segment_bytes=len(raw))
    assert binary == b"\x00\xff\x7f\x80" and dict(frozen) == body
    with pytest.raises(TypeError):
        frozen["capture_complete"] = False
    for cap in (0, True, 65537, len(raw) - 1):
        with pytest.raises(ComputationControlPlaneError):
            decode(raw, maximum_segment_bytes=cap)
    for changed in ({"data_base64": "AP9/gB=="}, {"data_base64": "AP9/gA="},
            {"data_base64": "AP9_gA=="}, {"data_base64": "AP9/gA\n="}, {"data_base64": "AP9/gA\u00e9="},
            {"captured_byte_count": True}, {"stream_segment_count": 0}, {"segment_ordinal": 1},
            {"first_byte_offset": 1}, {"stream_observed_byte_count": 3}, {"stream_eof": False},
            {"stream_discarded_byte_count": 1}, {"encoding": "BASE64"}, {"stream": "stdin"},
            {"extra": "denied"}, {"grant_ref": "other"}, {"capture_segment_ref": "other"},
            {"stream_observed_byte_count": 2**63}, {"stream_captured_byte_count": 1048577}):
        with pytest.raises(ComputationControlPlaneError):
            decode(deterministic_json(dict(body, **changed)).encode("utf-8"), maximum_segment_bytes=65536)
    # Two contiguous segments independently reconstruct binary diagnostics. A
    # partial capture records its drops and EOF honestly, without claiming that
    # this data alone proves a native terminal result or complete manifest.
    rebuilt = bytearray()
    for ordinal, (first, chunk) in enumerate(((0, b"\x00\xff"), (2, b"\x7f\x80"))):
        part = dict(body, segment_ordinal=ordinal, stream_segment_count=2, first_byte_offset=first,
            captured_byte_count=2, capture_segment_ref="data::PROCESS:FAILURE::CAPTURE:STDERR:" + str(ordinal),
            capture_complete=False, stream_eof=False, stream_observed_byte_count=7, stream_discarded_byte_count=3,
            data_base64=base64.b64encode(chunk).decode("ascii"))
        result, opaque = decode(deterministic_json(part).encode("utf-8"), maximum_segment_bytes=65536)
        assert result["first_byte_offset"] == len(rebuilt) and not result["capture_complete"] and not result["stream_eof"]
        rebuilt.extend(opaque)
    assert bytes(rebuilt) == binary
    manifest = dict(schema_version="1.0", operation="SVC_PROCESS_CAPTURE_MANIFEST_V1",
        observation_ref="data::PROCESS:FAILURE", grant_ref="data", fence_ref="data-fence",
        supervisor_instance_ref="data-supervisor", capture_complete=True, streams=[
            dict(stream="STDOUT", observed_byte_count=0, captured_byte_count=0, discarded_byte_count=0, eof=True, segment_refs=[]),
            dict(stream="STDERR", observed_byte_count=4, captured_byte_count=4, discarded_byte_count=0, eof=True,
                 segment_refs=["data::PROCESS:FAILURE::CAPTURE:STDERR:0"])])
    manifest_raw = deterministic_json(manifest).encode("utf-8")
    limits = dict(maximum_capture_bytes=4, maximum_segment_bytes=len(raw), maximum_segments=1,
                  maximum_total_bytes=len(manifest_raw) + len(raw))
    decoded, streams = _evidence_process_capture_manifest_v1(manifest_raw, segment_bodies=(raw,), **limits)
    assert streams == (b"", b"\x00\xff\x7f\x80") and decoded["streams"][0]["segment_refs"] == ()
    for field, value in (("maximum_capture_bytes", 3), ("maximum_capture_bytes", True),
            ("maximum_segments", 0), ("maximum_segments", True), ("maximum_segment_bytes", len(raw) - 1),
            ("maximum_total_bytes", limits["maximum_total_bytes"] - 1)):
        with pytest.raises(ComputationControlPlaneError):
            _evidence_process_capture_manifest_v1(manifest_raw, segment_bodies=(raw,), **dict(limits, **{field: value}))
    for changed, segments in ((dict(manifest, streams=manifest["streams"][::-1]), (raw,)),
            (dict(manifest, capture_complete=False), (raw,)), (dict(manifest, fence_ref="other"), (raw,)),
            (manifest, ()), (manifest, (raw, raw)), (dict(manifest, unknown="denied"), (raw,))):
        with pytest.raises(ComputationControlPlaneError):
            _evidence_process_capture_manifest_v1(deterministic_json(changed).encode("utf-8"), segment_bodies=segments,
                maximum_capture_bytes=32, maximum_segment_bytes=65536, maximum_segments=16, maximum_total_bytes=65536)
    # No segments exist for discarded-only stdout. Its five observed bytes and
    # zero retained bytes must still be present, independently of stderr.
    dropped = dict(manifest, capture_complete=False, streams=[
        dict(manifest["streams"][0], observed_byte_count=5, discarded_byte_count=5), manifest["streams"][1]])
    dropped_raw = deterministic_json(dict(body, capture_complete=False)).encode("utf-8")
    decoded, streams = _evidence_process_capture_manifest_v1(deterministic_json(dropped).encode("utf-8"),
        segment_bodies=(dropped_raw,), maximum_capture_bytes=4, maximum_segment_bytes=65536,
        maximum_segments=1, maximum_total_bytes=65536)
    assert streams == (b"", binary) and decoded["streams"][0]["observed_byte_count"] == 5 and not decoded["capture_complete"]
    empty = dict(manifest, streams=[manifest["streams"][0], dict(manifest["streams"][1], observed_byte_count=0,
        captured_byte_count=0, segment_refs=[])])
    empty_raw = deterministic_json(empty).encode("utf-8")
    assert _evidence_process_capture_manifest_v1(empty_raw, segment_bodies=(), maximum_capture_bytes=0,
        maximum_segment_bytes=65536, maximum_segments=0, maximum_total_bytes=len(empty_raw))[1] == (b"", b"")
    # Each modified middle segment below is individually well formed. Only
    # the complete roster can detect the missing or repeated byte interval.
    triple = tuple(dict(body, segment_ordinal=i, stream_segment_count=3, first_byte_offset=i * 2,
        captured_byte_count=2, stream_captured_byte_count=6, stream_observed_byte_count=6,
        capture_segment_ref="data::PROCESS:FAILURE::CAPTURE:STDERR:" + str(i),
        data_base64=base64.b64encode(chunk).decode("ascii")) for i, chunk in enumerate((b"ab", b"cd", b"ef")))
    triple_manifest = dict(manifest, streams=[manifest["streams"][0], dict(manifest["streams"][1],
        captured_byte_count=6, observed_byte_count=6, segment_refs=[part["capture_segment_ref"] for part in triple])])
    triple_raw = deterministic_json(triple_manifest).encode("utf-8")
    encoded = tuple(deterministic_json(part).encode("utf-8") for part in triple)
    whole_limits = dict(maximum_capture_bytes=6, maximum_segment_bytes=65536, maximum_segments=3, maximum_total_bytes=65536)
    assert _evidence_process_capture_manifest_v1(triple_raw, segment_bodies=encoded, **whole_limits)[1] == (b"", b"abcdef")
    for first, chunk in ((3, b"d"), (1, b"bc")):
        middle = deterministic_json(dict(triple[1], first_byte_offset=first, captured_byte_count=len(chunk),
            data_base64=base64.b64encode(chunk).decode("ascii"))).encode("utf-8")
        assert decode(middle, maximum_segment_bytes=65536)[1] == chunk
        with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_SEGMENT_MANIFEST_MISMATCH"):
            _evidence_process_capture_manifest_v1(triple_raw, segment_bodies=(encoded[0], middle, encoded[2]), **whole_limits)
    for changed in ((encoded[0], encoded[2]), (encoded[0], encoded[0], encoded[2]), encoded[::-1]):
        with pytest.raises(ComputationControlPlaneError):
            _evidence_process_capture_manifest_v1(triple_raw, segment_bodies=changed, **whole_limits)
    decoded_calls = []
    def forbid_decoding(*args, **kwargs):
        decoded_calls.append(True)
        raise AssertionError("base64 entered before complete input preflight")
    understated = dict(manifest, streams=[manifest["streams"][0], dict(manifest["streams"][1],
        captured_byte_count=1, observed_byte_count=1)])
    mismatched_last = deterministic_json(dict(triple[2], fence_ref="other")).encode("utf-8")
    with pytest.MonkeyPatch.context() as patch:
        patch.setattr(base64, "b64decode", forbid_decoding)
        with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_SEGMENT_MANIFEST_MISMATCH"):
            _evidence_process_capture_manifest_v1(deterministic_json(understated).encode("utf-8"), segment_bodies=(raw,),
                maximum_capture_bytes=1, maximum_segment_bytes=65536, maximum_segments=1, maximum_total_bytes=65536)
        with pytest.raises(ComputationControlPlaneError, match="LP03_CAPTURE_SEGMENT_MANIFEST_MISMATCH"):
            _evidence_process_capture_manifest_v1(triple_raw, segment_bodies=(*encoded[:2], mismatched_last), **whole_limits)
    assert decoded_calls == []
    _assert_lp03_failure_observation_data(manifest, raw)


