                ("scenario_roster", "LP03_PRIVATE26_ORIGINAL_VALUE_ROSTER"),
                ("probability_receipt", "LP03_PRIVATE26_ORIGINAL_PROBABILITY_RECEIPT"),
                ("utility_basis", "LP03_PRIVATE26_ORIGINAL_ACTION_UTILITY_JOIN"),
                ("revision", "LP03_PRIVATE26_ORIGINAL_CONTEXT_JOIN"),
                ("duplicate_actions", "LP03_PRIVATE26_ORIGINAL_ACTION_ROSTER"),
                ("cost_scope", "LP03_PRIVATE26_ORIGINAL_COST_SCOPE"),
                ("currency", "LP03_PRIVATE26_UTILITY_CURRENCY_BASIS"),
                ("schema", "LP03_PRIVATE26_ORIGINAL_PRODUCER_SCHEMA"),
