        assert len(operation.readback_refs) == 11
        assert adapters[0]._connection.execute("SELECT COUNT(*) FROM receipt_records").fetchone() == (3,)
        assert adapters[0]._connection.execute("SELECT COUNT(*) FROM idempotency_claims").fetchone() == (8,)
        lifecycle = state._require_lifecycle_original_v1()
        assert lifecycle[1] is operation and lifecycle[5] is grant
        assert lifecycle[3] is operation.bootstrap_commit_observation
        assert lifecycle[4] is operation.bootstrap_readback_observation and lifecycle[3][1] <= lifecycle[4][1]
        root_body = json.loads(operation.lifecycle_rows[0][3])
        assert root_body["issuer_instance_ref"] == lifecycle[0][3]
        assert root_body["supervisor_instance_ref"] == lifecycle[0][4]
        assert root_body["generation"] == lifecycle[0][5]
        assert root_body["first_grant_ref"] == grant.grant_ref
        expected_bootstrap_bytes = sum(len(row[-1].encode("utf-8")) for row in operation.bootstrap_original[1])
        expected_bootstrap_bytes += sum(len(deterministic_json(value).encode("utf-8"))
                                        for row in operation.lifecycle_rows for value in row[:-1])
        assert operation.consumed["control_bytes"] == expected_bootstrap_bytes
        initial_bootstrap_observations = lifecycle[3:5]
