        assert replay is grant and operation.consumed["record_reads"] == reads_before + 13
        assert state._require_lifecycle_original_v1() is lifecycle
        assert operation.bootstrap_commit_observation is initial_bootstrap_observations[0]
        assert operation.bootstrap_readback_observation is initial_bootstrap_observations[1]
        assert operation.consumed["control_writes"] == writes_before
