        source_read = admit_historical_evidence_read_v1(assembly_grant=grant, requester_context=assembler,
            original_owner_registry=source_registry, source_selection=original_selection)
        import copy
        with pytest.raises(TypeError):
            copy.copy(source_read)
        forged_read = object.__new__(type(source_read))
        for name in type(source_read).__slots__:
            setattr(forged_read, name, getattr(source_read, name))
        before_forgery = dict(operation.consumed)
        with pytest.raises(ComputationControlPlaneError, match="LP03_PREPARATION_NOT_READABLE"):
            source_registry.read_evidence_source_slice_v1(forged_read)
        assert operation.consumed == before_forgery
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane import input_resolver as source_owner
        from src.qtt.stage1_prediction_markets.qku_computation_control_plane.persistence import _EvidenceControlBootstrapV1
        original_projection = source_owner._evidence_packet_projection_body_v1
        original_room = _EvidenceControlBootstrapV1._room_v1
        projection_bounds, acquired_bytes, source_prefix_bytes = [], [], []
        original_custody = state.source_custodies[0]
        base, field_sizes = original_custody.projection_sizes[(original_selection.required_original_rights_refs[0],
                                                            original_selection.selection.record_refs[0])]
        expected_bytes = base + sum(field_sizes.values()) + len(field_sizes) - 1
        with pytest.MonkeyPatch.context() as patch:
            def observe_room(active, **charges):
                original_room(active, **charges)
                if charges.get("read_bytes") == expected_bytes:
                    projection_bounds.append(dict(charges))
            def observe_projection(*args, **kwargs):
                assert len(projection_bounds) == 2  # complete batch, then exact member
                source_prefix_bytes.append(operation.consumed["read_bytes"])
                body = original_projection(*args, **kwargs)
                acquired_bytes.append(len(deterministic_json(body).encode("utf-8")))
                return body
            patch.setattr(_EvidenceControlBootstrapV1, "_room_v1", observe_room)
            patch.setattr(source_owner, "_evidence_packet_projection_body_v1", observe_projection)
            source_slice = source_registry.read_evidence_source_slice_v1(source_read)
        assert acquired_bytes == [expected_bytes]
        assert source_slice.origin is m.EvidenceOriginV1.SOFTWARE_CONFORMANCE
        assert source_slice.reconstructed_canonical_events[0]["values"] == {"ask": "0.60", "bid": "0.40", "payout": "1.00"}
        assert m.EvidenceSourceSliceV1.from_canonical_mapping(json.loads(deterministic_json(source_slice))) == source_slice
        for mutation in (lambda body: body["reconstructed_canonical_events"][0].update(unknown=True),
                         lambda body: body["reconstructed_canonical_events"][0].update(origin="OBSERVED_REPLAY"),
                         lambda body: body["reconstructed_canonical_events"][0]["native_clocks"].update(observed_time=0)):
            invalid = json.loads(deterministic_json(source_slice))
            mutation(invalid)
            with pytest.raises(ComputationControlPlaneError):
                m.EvidenceSourceSliceV1.from_canonical_mapping(invalid)
        assert operation.current_state.state is m.EvidenceAssemblyStateV1.READING and operation.state_ordinal == 2
        assert operation.acquired_slices[-1] is source_slice
        assert operation.current_state.consumed_preparation_budget.record_reads > reads_before
        assert adapters[0]._connection.execute("SELECT COUNT(*) FROM receipt_records").fetchone() == (4,)
        with pytest.raises(ComputationControlPlaneError, match="LP03_PREPARATION_ALREADY_RESERVED_OR_UNRESOLVED"):
            issuer.issue_evidence_assembly_grant_v1(actual_envelope.envelope_ref,
                assembly_request=replace(request, idempotency_key="LP03-REQUEST::second"), issuer_context=context)
        # Zero query allowance must deny before either source metadata or SQL.
